			{id=12096,title="Tanks",body="$bullet;Activating |cFF2959D3|Hspell:1244257|h[Deepfreeze Containment]|h|r removes |cFF2959D3|Hspell:1243566|h[Searing Mountain]|h|r from Ash'golm and causes |cFF2959D3|Hspell:1243622s|h[Volcanic Eruption]|h|r to subside."},
			{id=12097,title="Healers",body="$bullet;When |cFF2959D3|Hspell:1243630|h[Burning Ember]|h|r expires, it spawns a Living Ember at the target's location.\n$bullet;Activating |cFF2959D3|Hspell:1244257|h[Deepfreeze Containment]|h|r removes |cFF2959D3|Hspell:1243566|h[Searing Mountain]|h|r from Ash'golm and causes |cFF2959D3|Hspell:1243622s|h[Volcanic Eruption]|h|r to subside."},
			{id=12098,title="Damage Dealers",body="$bullet;Activating |cFF2959D3|Hspell:1244257|h[Deepfreeze Containment]|h|r causes Ash'golm and Living Embers to become |cFF2959D3|Hspell:1244248|h[Brittle]|h|r.\n$bullet;When |cFF2959D3|Hspell:1243632|h[Burning Ember]|h|r expires, it spawns a Living Ember at the target's location."},
