		sections={
			{id=12396,title="Overview",body="Using Elune's Light to properly counter Cordana's abilities is key to successfully defeating her."},
			{id=12397,title="Tanks",body="$bullet;|cFF2959D3|Hspell:197513|h[Detonating Moonglaive]|h|r causes you to take increased Physical damage.\n$bullet;|cFF2959D3|Hspell:213576|h[Deepening Shadows]|h|r continue to spread across the platform unless destroyed by |cFF2959D3|Hspell:192656|h[Elune's Light]|h|r.\n$bullet;|cFF2959D3|Hspell:197422|h[Creeping Doom's]|h|r spirits are invisible unless revealed by |cFF2959D3|Hspell:192656|h[Elune's Light]|h|r.\n$bullet;Quickly gain threat on Avatars of Vengeance that are revealed by |cFF2959D3|Hspell:192656|h[Elune's Light]|h|r."},
			{id=12398,title="Healers",body="$bullet;|cFF2959D3|Hspell:197513|h[Detonating Moonglaive]|h|r causes victims caught in its blast to take increased Physical damage.\n$bullet;|cFF2959D3|Hspell:213576|h[Deepening Shadows]|h|r continue to spread across the platform unless destroyed by |cFF2959D3|Hspell:192656|h[Elune's Light]|h|r.\n$bullet;|cFF2959D3|Hspell:197422|h[Creeping Doom's]|h|r spirits are invisible unless revealed by |cFF2959D3|Hspell:192656|h[Elune's Light]|h|r.\n$bullet;Avatars of Vengeance continually target members of your party at random with their damaging abilities."},
			{id=12399,title="Damage Dealers",body="$bullet;Enemies revealed by |cFF2959D3|Hspell:192656|h[Elune's Light]|h|r take $192752s1% more damage.\n$bullet;|cFF2959D3|Hspell:213576|h[Deepening Shadows]|h|r continue to spread across the platform unless destroyed by |cFF2959D3|Hspell:192656|h[Elune's Light]|h|r.\n$bullet;|cFF2959D3|Hspell:197422|h[Creeping Doom's]|h|r spirits are invisible unless revealed by |cFF2959D3|Hspell:192656|h[Elune's Light]|h|r.\n$bullet;Avatars of Vengeance must be revealed by |cFF2959D3|Hspell:192656|h[Elune's Light]|h|r, turning them into dangerous melee attackers."},
			{id=12414,title="Elune's Light",body="Elune's Light can be acquired from the Glowing Sentry on Illidan's platform, and can be picked up during the encounter when it is removed by Cordana's various abilities."},
