	[1486]={
		encounterID=1486,
		instanceID=721,
		order=2,
		name="Hyrja",
		lore="In life Hyrja was a warrior without equal, defending the Valkyra from all threats. Her valor and courage drew the attention of Eyir, a titan watcher.  Upon her death and ascension to the Halls of Valor Eyir has awarded Hyrja with her greatest honor, transformation into a Val'kyr.",
		dungeonEncounterID=1806,
		uiMapID=704,
		pin={x=0.6295,y=0.8479},
		difficultyIDs={1,2,8,23},
		npcIDs={95833},
		displayIDs={65076},
		loot={
			{itemID=133613,diffs={},faction=-1},
			{itemID=134196,diffs={},faction=-1},
			{itemID=133620,diffs={},faction=-1},
			{itemID=133622,diffs={},faction=-1},
			{itemID=134219,diffs={},faction=-1},
			{itemID=133646,diffs={},faction=-1},
			{itemID=136974,diffs={1,2,23},faction=-1},
			{itemID=136772,diffs={},faction=-1},
			{itemID=133679,diffs={},faction=-1},
			{itemID=134186,diffs={},faction=-1},
			{itemID=134209,diffs={},faction=-1},
			{itemID=136771,diffs={1,2,23},faction=-1},
			{itemID=140657,diffs={101},faction=-1},
		},
		sections={
			{id=12044,title="Overview",body="Hyrja becomes empowered by Olmyr the Enlightened and Solsten depending upon which mystic she is closest to. As she becomes empowered she is granted particular abilities that grow in power over time. Moving Hyrja out of range of a mystic slowly reduces that mystic's empowerment."},
			{id=12045,title="Damage Dealers",body="$bullet;Move away from other players when affected with |cFF2959D3|Hspell:192048|h[Expel Light]|h|r.\n$bullet;While Hyrja has |cFF2959D3|Hspell:192132|h[Mystic Empowerement: Thunder]|h|r be prepared to run to safety during |cFF2959D3|Hspell:192305|h[Eye of the Storm]|h|r\n$bullet;While Hyrja has |cFF2959D3|Hspell:192133|h[Mystic Empowerement: Holy]|h|r avoid the orbs of light during |cFF2959D3|Hspell:192307|h[Sanctify]|h|r"},
			{id=12046,title="Healers",body="$bullet;Move away from other players when affected with |cFF2959D3|Hspell:192048|h[Expel Light]|h|r.\n$bullet;While Hyrja has |cFF2959D3|Hspell:192132|h[Mystic Empowerement: Thunder]|h|r be prepared to run to safety during |cFF2959D3|Hspell:192305|h[Eye of the Storm]|h|r\n$bullet;While Hyrja has |cFF2959D3|Hspell:192133|h[Mystic Empowerement: Holy]|h|r avoid the orbs of light during |cFF2959D3|Hspell:192307|h[Sanctify]|h|r"},
			{id=12047,title="Tanks",body="$bullet;Move Hyrja between Olmyr and Solsten to manage how many stacks of |cFF2959D3|Hspell:192132|h[Mystic Empowerement: Thunder]|h|r and |cFF2959D3|Hspell:192133|h[Mystic Empowerement: Holy]|h|r she has.\n$bullet;While Hyrja has |cFF2959D3|Hspell:192132|h[Mystic Empowerement: Thunder]|h|r be prepared to run to safety during |cFF2959D3|Hspell:192305|h[Eye of the Storm]|h|r\n$bullet;While Hyrja has |cFF2959D3|Hspell:192133|h[Mystic Empowerement: Holy]|h|r avoid the orbs of light during |cFF2959D3|Hspell:192307|h[Sanctify]|h|r"},
			{id=12052,title="Section 7"},
			{id=12055,title="Section 10",body="$[!2,8,23\n\nIn this difficulty, stacks of Mystic Empowerment: Thunder slowly fade away while Hyrja is not being actively empowered by Solsten.$]"},
			{id=13650,title="Section 11"},
			{id=12056,title="Section 11"},
			{id=12053,title="Section 8",body="$[!2,8,23\n\nIn this difficulty, stacks of Mystic Empowerment: Holy slowly fade away while Hyrja is not being actively empowered by Olmyr the Enlightened.$]"},
			{id=12054,title="Section 9"},
			{id=12051,title="Section 6",body="$[!2,8,23\n\nIn this difficulty, after Expel Light bursts, the effect bounces to another player.$]"},
		},
	},
	[1487]={
		encounterID=1487,
		instanceID=721,
		order=3,
		name="Fenryr",
		lore="In the Fields of the Eternal Hunt, the greatest vrykul champions keep their skills sharp, competing to see who can fell the largest beast. But man and beast alike give a wide berth to the fearsome worg Fenryr, true master of the Fields, who stalks his prey and pounces with unnerving quickness.",
		dungeonEncounterID=1807,
		uiMapID=703,
		pin={x=0.2831,y=0.762},
