		sections={
			{id=12284,title="Overview",body="Fenryr leaps and shreds his enemies, eventually retreating to his den after becoming wounded."},
			{id=12285,title="Damage Dealers",body="$bullet;Avoid standing near allies targeted with |cFF2959D3|Hspell:196495|h[Ravenous Leap]|h|r.\n$bullet;Run away from Fenryr when affected with |cFF2959D3|Hspell:196838|h[Scent of Blood]|h|r.\n$bullet;Melee damage dealers should help split the damage of |cFF2959D3|Hspell:196512|h[Claw Frenzy]|h|r."},
			{id=12286,title="Healers",body="$bullet;Avoid standing near allies targeted with |cFF2959D3|Hspell:196495|h[Ravenous Leap]|h|r.\n$bullet;Run away from Fenryr when affected with |cFF2959D3|Hspell:196838|h[Scent of Blood]|h|r."},
			{id=12287,title="Tanks",body="$bullet;Avoid standing near allies targeted with |cFF2959D3|Hspell:196495|h[Ravenous Leap]|h|r.\n$bullet;Help split the damage of |cFF2959D3|Hspell:196512|h[Claw Frenzy]|h|r."},
			{id=12289,title="Claw Frenzy"},
			{id=12599,title="Unnerving Howl",body="$[!2,8,23\n\n In this difficulty, after being wounded, Unnerving Howl calls 3 Ebonclaw Worgs to assist Fenryr.$]"},
