	[1488]={
		encounterID=1488,
		instanceID=721,
		order=4,
		name="God-King Skovald",
		lore="Gul'dan approached the vrykul king Skovald with a simple proposition: he could join the Legion and receive ultimate power, or he would see his people destroyed. Dreaming of conquest and glory, Skovald has taken up the Legion's offer, and been set to a single crucial task. He must claim the Aegis of Aggramar from Odyn in the Halls of Valor and deliver it to Gul'dan. Only then can his endless conquest begin.",
		dungeonEncounterID=1808,
		uiMapID=705,
		pin={x=0.5151,y=0.8253},
