		sections={
			{id=12128,title="Overview",body="God-King Skovald battles the party for control of the Aegis of Aggramar. Players may wrest the Aegis from Skovald's grasp, and use it to defend against his ultimate attacks."},
			{id=12129,title="Damage Dealers",body="$bullet;Avoid standing too close to allies while Skovald casts |cFF2959D3|Hspell:193660|h[Felblaze Rush]|h|r.\n$bullet;Rely on the protective shield of the |cFF2959D3|Hspell:193765|h[Aegis of Aggramar]|h|r to survive |cFF2959D3|Hspell:193827|h[Ragnarok]|h|r."},
			{id=12130,title="Healers",body="$bullet;Rely on the protective shield of the |cFF2959D3|Hspell:193765|h[Aegis of Aggramar]|h|r to survive |cFF2959D3|Hspell:193827|h[Ragnarok]|h|r.\n$bullet;Avoid standing too close to allies while Skovald casts |cFF2959D3|Hspell:193660|h[Felblaze Rush]|h|r."},
			{id=12131,title="Tanks",body="$bullet;Active Mitigation can be used to reduce the damage of |cFF2959D3|Hspell:193668|h[Savage Blade]|h|r.\n$bullet;Rely on the protective shield of the |cFF2959D3|Hspell:193765|h[Aegis of Aggramar]|h|r to survive |cFF2959D3|Hspell:193827|h[Ragnarok]|h|r."},
