	[1489]={
		encounterID=1489,
		instanceID=721,
		order=5,
		name="Odyn",
		lore="Odyn, a titan keeper, was empowered by the titan Pantheon to lead the titan-forged armies against the Old Gods. In the aftermath, he raised the Halls of Valor into the skies, assembling a force of the greatest vrykul champions to defend Azeroth. But when Ulduar fell into the clutches of Yogg-Saron, he was betrayed by Loken and cursed by Helya, now trapped within these halls for eternity.",
