		sections={
			{id=12048,title="Overview",body="Lady Hatecoil assaults her enemies with raging storms and lightning strikes, using conductivity to her advantage. \n\n|cFF2959D3|Hspell:193597|h[Static Nova]|h|r strikes all players touching the water and |cFF2959D3|Hspell:193611|h[Focused Lightning]|h|r can blow away sand dunes."},
			{id=12061,title="Damage Dealers",body="$bullet;Move on top of a sand dune to avoid damage from |cFF2959D3|Hspell:193597|h[Static Nova]|h|r.\n$bullet;Move away from sand dunes when |cFF2959D3|Hspell:193611|h[Focused Lightning]|h|r strikes to prevent it from destroying them."},
			{id=12062,title="Healers",body="$bullet;Move on top of a sand dune to avoid damage from |cFF2959D3|Hspell:193597|h[Static Nova]|h|r.\n$bullet;Move away from sand dunes when |cFF2959D3|Hspell:193611|h[Focused Lightning]|h|r strikes to prevent it from destroying them."},
			{id=12063,title="Tanks",body="$bullet;Move on top of a sand dune to avoid damage from |cFF2959D3|Hspell:193597|h[Static Nova]|h|r.\n$bullet;Move away from sand dunes when |cFF2959D3|Hspell:193611|h[Focused Lightning]|h|r strikes to prevent it from destroying them.\n$bullet;Gain threat on loose Saltsea Globules when Lady Hatecoil casts |cFF2959D3|Hspell:193682|h[Beckon Storm]|h|r."},
