	[1492]={
		encounterID=1492,
		instanceID=716,
		order=5,
		name="Wrath of Azshara",
		lore="One of Azshara's most loyal handmaidens offered herself willingly to her Queen to serve as the instrument of her vengeance. Summoned by Hatecoil channelers as a last resort after Parjesh's failure, the terrifying Wrath of Azshara exists to wash away all landwalkers who would stand against her.",
		dungeonEncounterID=1814,
