		sections={
			{id=12057,title="Overview",body="The Wrath of Azshara crushes Queen Azshara's enemies with fierce storms and arcane energy, seeking to wash away her foes. Avoid the dangerous weather hazards and watch out when the storm intensifies!"},
			{id=12064,title="Damage Dealers",body="$bullet;Avoid being sucked into the air by moving away from |cFF2959D3|Hspell:192675|h[Mystic Tornado]|h|r when it spawns.\n$bullet;Move out of the detonation area of |cFF2959D3|Hspell:192708|h[Arcane Bomb]|h|r once it has been dispelled."},
			{id=12065,title="Healers",body="$bullet;Avoid being sucked into the air by moving away from |cFF2959D3|Hspell:192675|h[Mystic Tornado]|h|r when it spawns.\n$bullet;Dispel |cFF2959D3|Hspell:192708|h[Arcane Bomb]|h|r from players so they can avoid its detonation."},
			{id=12066,title="Tanks",body="$bullet;Remain within melee range of the Wrath of Azshara to prevent it from using |cFF2959D3|Hspell:192696|h[Raging Storms]|h|r.\n$bullet;Avoid being sucked into the air by moving away from |cFF2959D3|Hspell:192675|h[Mystic Tornado]|h|r when it spawns.\n$bullet;Move out of the area while |cFF2959D3|Hspell:192619|h[Massive Deluge]|h|r is being cast."},
			{id=12085,title="Massive Deluge"},
			{id=12088,title="Section 6"},
			{id=12089,title="Section 7"},
			{id=12090,title="Section 8"},
			{id=12272,title="Section 14",difficultyIDs={2,8,23,24}},
			{id=13446,title="Section 17"},
			{id=12423,title="Elemental Resonance",body="The Wrath of Azshara is a being of immense magical energy. Upon striking foes with magic, a lingering effect remains behind.",difficultyIDs={2,8,23,24}},
