	[1497]={
		encounterID=1497,
		instanceID=726,
		order=1,
		name="Ivanyr",
		lore="Cut off from the power of the Nightwell and cast into the dark expanse of the Arcway, Ivanyr wandered aimlessly, slowly withering away, until he came upon a trove in the foundations beneath the great library of Suramar. He spends his days feverishly working to decipher the tomes there, feeding off the power of relics in the achives in order to sustain himself. But even as that magic sustains his body, his mind cracks and weakens.",
		dungeonEncounterID=1827,
		uiMapID=749,
		pin={x=0.1686,y=0.7529},
		difficultyIDs={2,8,23},
