			{id=12262,title="Damage Dealers",body="$bullet;Ivanyr will gain stacks of |cFF2959D3|Hspell:196396|h[Overcharge]|h|r if |cFF2959D3|Hspell:196392|h[Overcharge Mana]|h|r is not interrupted."},
