	[1498]={
		encounterID=1498,
		instanceID=726,
		order=2,
		name="Corstilax",
		lore="This massive construct patrols the tunnels beneath Suramar, searching for anomalies and correcting them. He has detected one such anomaly - a breach in one of the conduits that carries the power of the Nightwell - and works to repair it. But living outsiders wandering the tunnels are also an anomaly; one that Corstilax is empowered to remedy.",
		dungeonEncounterID=1825,
		uiMapID=749,
		pin={x=0.3934,y=0.7767},
		difficultyIDs={2,8,23},
		npcIDs={98205},
		displayIDs={65791},
		loot={
			{itemID=137402,diffs={},faction=-1},
			{itemID=134488,diffs={},faction=-1},
