			{itemID=134453,diffs={},faction=-1},
		},
		sections={
			{id=12187,title="Overview",body="Corstilax guards the Nightwell breach, attempting to limit players' exposure to |cFF2959D3|Hspell:195362|h[Nightwell Energy]|h|r. Players must free their allies from |cFF2959D3|Hspell:195791|h[Quarantine]|h|r and avoid direct damage from |cFF2959D3|Hspell:196070|h[Suppression Protocol]|h|r."},
			{id=12188,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:195362|h[Nightwell Energy]|h|r significantly increases haste but will cause |cFF2959D3|Hspell:196115|h[Cleansing Force]|h|r to stun you."},
			{id=12189,title="Healers",body="$bullet;|cFF2959D3|Hspell:196070|h[Suppression Protocol]|h|r inflicts moderate group wide damage."},
			{id=12190,title="Tanks",body="$bullet;|cFF2959D3|Hspell:196142|h[Exterminate]|h|r inflicts heavy damage and stuns players within $196142A1 yards when |cFF2959D3|Hspell:196115|h[Cleansing Force]|h|r ends if they have |cFF2959D3|Hspell:195362|h[Nightwell Energy]|h|r."},
			{id=12191,title="Quarantine"},
