	[1499]={
		encounterID=1499,
		instanceID=726,
		order=3,
		name="General Xakal",
		lore="When Gul'dan threatened Suramar with destruction if Elisande did not comply with his demands, those were not idle words. A Legion invasion force has burrowed into the tunnels beneath the city, and Xakal leads those forces. He awaits further command, ready at a moment's notice to surge forth and bring death and destruction to the streets of Suramar.",
		dungeonEncounterID=1828,
		uiMapID=749,
		pin={x=0.7522,y=0.5022},
		difficultyIDs={2,8,23},
