		},
		sections={
			{id=12494,title="Overview",body="General Xakal periodically summons Dread Felbats and causes the ground to erupt with |cFF2959D3|Hspell:197776|h[Fel Fissures]|h|r. After several waves, he casts |cFF2959D3|Hspell:197810|h[Wicked Slam]|h|r, inflicting damage to all players and knocking them back."},
			{id=12495,title="Damage Dealers",body="$bullet;Avoid |cFF2959D3|Hspell:212030|h[Shadow Slash]|h|r when it is targeted towards you.\n$bullet;Position carefully to avoid |cFF2959D3|Hspell:197810|h[Wicked Slam]|h|r knocking you into |cFF2959D3|Hspell:197776|h[Fel Fissure]|h|r."},
			{id=12496,title="Healers",body="$bullet;|cFF2959D3|Hspell:197810|h[Wicked Slam]|h|r inflicts heavy group wide damage."},
			{id=12497,title="Tanks",body="$bullet;Dread Felbats periodically spawn and must be tanked."},
			{id=12445,title="Section 1"},
			{id=13271,title="Section 10"},
