		sections={
			{id=12750,title="Overview",body="Advisor Vandros uses the power of the Nightwell to influence time. He frequently summons |cFF2959D3|Hspell:203254|h[Chrono Shards]|h|r and attempts to erase players from existence with |cFF2959D3|Hspell:203882|h[Banish In Time]|h|r."},
			{id=12751,title="Damage Dealers",body="$bullet;Interrupt |cFF2959D3|Hspell:203176|h[Accelerating Blast]|h|r to prevent it from stacking.\n$bullet;Quickly defeat Timeless Wraiths while |cFF2959D3|Hspell:203882|h[Banished In Time]|h|r."},
			{id=12752,title="Healers",body="$bullet;|cFF2959D3|Hspell:202974|h[Force Bombs]|h|r inflict heavy damage to the entire group.\n$bullet;Timeless Wraiths use |cFF2959D3|Hspell:203952|h[Breach]|h|r to inflict damage to all nearby players."},
			{id=12753,title="Tanks",body="$bullet;Avoid standing near |cFF2959D3|Hspell:203254|h[Chrono Shards]|h|r.\n$bullet;Position the boss away from |cFF2959D3|Hspell:202974|h[Force Bombs]|h|r."},
			{id=12754,title="Section 5"},
			{id=12755,title="Section 6"},
