			{id=12145,title="Healers",body="$bullet;Be aware of the knockback from |cFF2959D3|Hspell:193977|h[Winds of Northrend]|h|r.\n$bullet;Dispel |cFF2959D3|Hspell:193364|h[Screams of the Dead]|h|r from affected targets."},
