		sections={
			{id=12238,title="Overview",body="The Amalgam of Souls battles players until reaching 50% health, at which point it ruptures, splitting into the tortured souls of the Ravencrest ancestors."},
			{id=12239,title="Damage Dealers",body="$bullet;Keep moving and avoid other players while afflicted with |cFF2959D3|Hspell:194960|h[Soul Echoes]|h|r.\n$bullet;When targeted by |cFF2959D3|Hspell:195254|h[Swirling Scythe]|h|r or |cFF2959D3|Hspell:196916|h[Glaive Toss]|h|r, move to avoid placing it in an inconvenient location."},
			{id=12240,title="Healer",body="$bullet;Keep moving and avoid other players while afflicted with |cFF2959D3|Hspell:194960|h[Soul Echoes]|h|r.\n$bullet;When targeted by |cFF2959D3|Hspell:195254|h[Swirling Scythe]|h|r or |cFF2959D3|Hspell:196916|h[Glaive Toss]|h|r, move to avoid placing it in an inconvenient location.\n$bullet;|cFF2959D3|Hspell:194956|h[Reap Soul]|h|r will deal high damage to the tank if it hits."},
			{id=12246,title="Tank",body="$bullet;Move out of the way of |cFF2959D3|Hspell:194956|h[Reap Soul]|h|r to avoid heavy damage."},
			{id=12241,title="Stage One: The Amalgam of Souls"},
			{id=12242,title="Section 4",body="$[!2,8,23\n\nOn Heroic difficulty and higher, this effect stacks.$]"},
			{id=12243,title="Section 3"},
			{id=12244,title="Section 2",body="$[!23\n\nOn Mythic difficulty, players damaged by Soul Echoes also flee in fear for $194960d.$]"},
			{id=12245,title="Stage Two: The Call of Souls",difficultyIDs={2,8,23,24}},
			{id=12247,title="Section 10"},
			{id=12248,title="Section 11"},
			{id=12249,title="Section 12"},
		},
