	[1653]={
		encounterID=1653,
		instanceID=740,
		order=1,
		name="Illysanna Ravencrest",
		lore="The daughter of Lord Ravencrest, imprisoned for millennia in the Vault of the Wardens shortly after the War of Ancients, found herself free after Maiev released the demon hunters from their prison. Returning to her ancestral home, she has sacrificed everything - including her very soul - to defend what she could not during the War of the Ancients.",
		dungeonEncounterID=1833,
		uiMapID=752,
		pin={x=0.6109,y=0.5912},
		difficultyIDs={1,2,8,23,24},
		npcIDs={101317,103013},
		displayIDs={65951},
		loot={
			{itemID=136769,diffs={1,2,23},faction=-1},
			{itemID=134490,diffs={},faction=-1},
			{itemID=136978,diffs={},faction=-1},
