		sections={
			{id=12293,title="Overview",body="Archdruid Glaidalis is a master shapeshifter, transforming into bear and cat forms with ease as he calls down corrupted starshards to bombard his foes."},
			{id=12294,title="Damage Dealers",body="$bullet;Avoid being in front of Archdruid Glaidalis when he is casting |cFF2959D3|Hspell:198360|h[Primal Rampage]|h|r."},
			{id=12295,title="Healers",body="$bullet;Avoid being in front of Archdruid Glaidalis when he is casting |cFF2959D3|Hspell:198360|h[Primal Rampage]|h|r.\n$bullet;Quickly heal targets affected by |cFF2959D3|Hspell:196376|h[Grevious Tear]|h|r to above 90% of their maximum health."},
			{id=12296,title="Tanks",body="$bullet;Position Archdruid Glaidalis so that |cFF2959D3|Hspell:198360|h[Primal Rampage]|h|r does not run over other players."},
