	[1663]={
		encounterID=1663,
		instanceID=727,
		order=3,
		name="Helya",
		lore="Helya, fallen queen of the val'kyr, was once at Odyn's right hand, raising the spirits of vrykul champions to the Halls of Valor to prepare for the final battle for the fate of Azeroth. But following Loken's betrayal, she was persuaded to join him and turn upon her master. She now lurks in the shadowy realm beneath the world, plotting her revenge.",
		dungeonEncounterID=1824,
		uiMapID=708,
		pin={x=0.0943,y=0.5616},
