		sections={
			{id=12354,title="Overview",body="Attaching herself to the Naglfar, Helya launches an all-out assault of the vessel from a distance. Defeating Helya's Tentacles wounds her, and after defeating several tentacles, Helya submerges and continues to barrage the Naglfar with her tentacles. After $196947D, Helya rips the front of the Naglfar in half and combats players directly, periodically retreating to the waves for the remainder of the encounter.$[!2\n\nOn this difficulty, Helya additionally casts Brackwater Barrage, assaulting the port or starboard side of the Naglfar.$]"},
			{id=12355,title="Damage Dealers",body="$bullet;Defeat Helya's Destructor and Grasping Tentacles to wound her during the Siege of the Naglfar.\n$bullet;Watch Helya's facing for |cFF2959D3|Hspell:227233|h[Corrupted Bellow]|h|r.",difficultyIDs={1}},
			{id=13895,title="Damage Dealers",body="$bullet;Defeat Helya's Destructor and Grasping Tentacles to wound her during the Siege of the Naglfar.\n$bullet;Watch Helya's facing for |cFF2959D3|Hspell:227233|h[Corrupted Bellow]|h|r.\n$bullet;When |cFF2959D3|Hspell:197262|h[Taint of the Sea]|h|r explodes, it and leaves behind a |cFF2959D3|Hspell:202472|h[Tainted Essence]|h|r.\n$bullet;Watch Helya during |cFF2959D3|Hspell:202098|h[Brackwater Barrage]|h|r to know which side of the Naglfar will be bombarded.",difficultyIDs={2,23}},
			{id=12356,title="Healers",body="$bullet;|cFF2959D3|Hspell:197262|h[Taint of the Sea]|h|r explodes when dispelled or when it expires.\n$bullet;Watch Helya's facing for |cFF2959D3|Hspell:227233|h[Corrupted Bellow]|h|r.",difficultyIDs={1}},
			{id=13896,title="Healers",body="$bullet;|cFF2959D3|Hspell:197262|h[Taint of the Sea]|h|r explodes when dispelled or when it expires, and leaves behind a |cFF2959D3|Hspell:202472|h[Tainted Essence]|h|r.\n$bullet;Watch Helya's facing for |cFF2959D3|Hspell:227233|h[Corrupted Bellow]|h|r.\n$bullet;Watch Helya during |cFF2959D3|Hspell:202098|h[Brackwater Barrage]|h|r to know which side of the Naglfar will be bombarded.",difficultyIDs={2,23}},
			{id=12357,title="Tanks",body="$bullet;Destructor Tentacles cast |cFF2959D3|Hspell:196534|h[Smash]|h|r and Helya casts |cFF2959D3|Hspell:198520|h[Wing Buffet]|h|r when untanked.\n$bullet;Watch Helya's facing for |cFF2959D3|Hspell:227233|h[Corrupted Bellow]|h|r.",difficultyIDs={1}},
			{id=13897,title="Tanks",body="$bullet;Destructor Tentacles cast |cFF2959D3|Hspell:196534|h[Smash]|h|r and Helya casts |cFF2959D3|Hspell:198520|h[Wing Buffet]|h|r when untanked.\n$bullet;Watch Helya's facing for |cFF2959D3|Hspell:227233|h[Corrupted Bellow]|h|r.\n$bullet;Watch Helya during |cFF2959D3|Hspell:202098|h[Brackwater Barrage]|h|r to know which side of the Naglfar will be bombarded.",difficultyIDs={2,23}},
