	[1664]={
		encounterID=1664,
		instanceID=740,
		order=2,
		name="Smashspite the Hateful",
		lore="A brutal, imposing Mo'arg Lieutenant, Smashspite the Hateful led the Legion's invasion of Black Rook Hold and commanded defense of the keep from the air via his colony of felbats.",
		dungeonEncounterID=1834,
		uiMapID=754,
		pin={x=0.7712,y=0.2325},
		difficultyIDs={1,2,8,23,24},
		npcIDs={92564,92990},
		displayIDs={65304},
		loot={
