		sections={
			{id=12459,title="Overview",body="Ursoc tramples his enemies with |cFF2959D3|Hspell:198109|h[Barreling Impact]|h|r and periodically roars for a |cFF2959D3|Hspell:197969|h[Roaring Cacophany]|h|r.$[!16\n\nIn Mythic difficulty, Nightmare Images periodically animate and attack players.$]"},
			{id=12460,title="Damage Dealers",body="$bullet;When not afflicted with |cFF2959D3|Hspell:198108|h[Momentum]|h|r, stand in Ursoc's path when he uses |cFF2959D3|Hspell:198006|h[Focused Gaze]|h|r to reduce the amount of damage |cFF2959D3|Hspell:198109|h[Barreling Impact]|h|r inflicts.\n$bullet;Get as far away from Ursoc as possible when the target of |cFF2959D3|Hspell:198006|h[Focused Gaze]|h|r to reduce the damage taken from |cFF2959D3|Hspell:199237|h[Trampling Slam]|h|r."},
			{id=12461,title="Healers",body="$bullet;When not afflicted with |cFF2959D3|Hspell:198108|h[Momentum]|h|r, stand in Ursoc's path when he uses |cFF2959D3|Hspell:198006|h[Focused Gaze]|h|r to reduce the amount of damage |cFF2959D3|Hspell:198109|h[Barreling Impact]|h|r inflicts.\n$bullet;Get as far away from Ursoc as possible when the target of |cFF2959D3|Hspell:198006|h[Focused Gaze]|h|r to reduce the damage taken from |cFF2959D3|Hspell:199237|h[Trampling Slam]|h|r."},
			{id=13886,title="Tanks",body="$bullet;Ensure that no tank overlaps the effects of both |cFF2959D3|Hspell:197943|h[Overwhelm]|h|r and |cFF2959D3|Hspell:197942|h[Rend Flesh]|h|r at the same time, taunting when necessary.\n$bullet;Switch off which tank holds Ursoc's attention for |cFF2959D3|Hspell:197943|h[Overwhelm]|h|r and |cFF2959D3|Hspell:197942|h[Rend Flesh]|h|r each time he charges.\n$bullet;Stay out of the proximity of Nightmare Images to avoid |cFF2959D3|Hspell:197980|h[Nightmarish Cacophany]|h|r.",difficultyIDs={15,16}},
			{id=12462,title="Tanks",body="$bullet;Ensure that no tank overlaps the effects of both |cFF2959D3|Hspell:197943|h[Overwhelm]|h|r and |cFF2959D3|Hspell:197942|h[Rend Flesh]|h|r at the same time, taunting when necessary.\n$bullet;Switch off which tank holds Ursoc's attention for |cFF2959D3|Hspell:197943|h[Overwhelm]|h|r and |cFF2959D3|Hspell:197942|h[Rend Flesh]|h|r each time he charges.",difficultyIDs={14,17}},
