	[1672]={
		encounterID=1672,
		instanceID=740,
		order=3,
		name="Lord Kur'talos Ravencrest",
		lore="Kur'talos Ravencrest, Lord of Black Rook Hold, was the commander of the Kal'dorei Resistance during the War of the Ancients until he was assassinated by Varo'then under the orders of Queen Aszhara. Millennia later, Gul'dan's foul soul magic has awoken Ravencrest's soul, and those of his ancestors, from their eternal repose. The Legion, seeking revenge, gleefully forced his soul into his body and mesmerized him, forcing him to eternally relive the horrors of the War of Ancients.",
		dungeonEncounterID=1835,
		uiMapID=756,
