			{id=12576,title="Damage Dealers",body="$bullet;Avoid |cFF2959D3|Hspell:197783|h[Shadow Crash]|h|r.\n$bullet;Defeat Faceless Tendrils summoned by |cFF2959D3|Hspell:201153|h[Eternal Darkness]|h|r."},
