		sections={
			{id=12584,title="Overview",body="Dargrul wields the Hammer of Khaz'goroth to shape earth and fire to strike the party, while summoning fiery minions that pursue random players.$[!2, 23\n\n\nOn Heroic difficulty, the Molten Charskins no longer use Magma Breaker, but instead increase their speed and damage over time with Rising Inferno. Dargrul now uses Magma Breaker to damage the party each time he moves.$]"},
			{id=12585,title="Damage Dealers",body="$bullet;Defeat Molten Charskins.\n$bullet;Take cover behind |cFF2959D3|Hspell:200551|h[Crystal Spikes]|h|r to avoid taking damage from |cFF2959D3|Hspell:200418|h[Magma Wave]|h|r."},
			{id=12586,title="Healers",body="$bullet;|cFF2959D3|Hspell:200732|h[Molten Crash]|h|r does massive damage to the tank.\n$bullet;Molten Charskins do continuous damage to the party while moving with |cFF2959D3|Hspell:209920|h[Magma Breaker]|h|r.\n$bullet;Take cover behind |cFF2959D3|Hspell:200551|h[Crystal Spikes]|h|r to avoid taking damage from |cFF2959D3|Hspell:200418|h[Magma Wave]|h|r.",difficultyIDs={1}},
