			{id=12587,title="Tanks",body="$bullet;Use defensive abilities to survive |cFF2959D3|Hspell:200732|h[Molten Crash]|h|r.\n$bullet;Take cover behind |cFF2959D3|Hspell:200551|h[Crystal Spikes]|h|r to avoid taking damage from |cFF2959D3|Hspell:200418|h[Magma Wave]|h|r.",difficultyIDs={1}},
