	[1693]={
		encounterID=1693,
		instanceID=777,
		order=1,
		name="Festerface",
		lore="Professor Putricide had many experiments seized when Icecrown Citadel fell. At best guess, Festerface appears to be a failed prototype that predated the construction of the professor's two most notorious creations: Rotface and Festergut.",
		dungeonEncounterID=1848,
		uiMapID=732,
		pin={x=0.3415,y=0.2774},
		difficultyIDs={1,2,23},
		npcIDs={112960,113222},
		displayIDs={31006},
		loot={
			{itemID=137435,diffs={},faction=-1},
			{itemID=137437,diffs={},faction=-1},
			{itemID=137439,diffs={},faction=-1},
			{itemID=134454,diffs={},faction=-1},
			{itemID=134414,diffs={},faction=-1},
			{itemID=137436,diffs={},faction=-1},
			{itemID=137479,diffs={},faction=-1},
			{itemID=137438,diffs={},faction=-1},
			{itemID=137434,diffs={},faction=-1},
			{itemID=137465,diffs={},faction=-1},
			{itemID=134468,diffs={},faction=-1},
		},
		sections={
			{id=12640,title="Overview",body="Festerface spews torrents of nasty bile that form into Congealed Goo. When a Congealed Goo is killed it begins to reform and will fully heal after a few seconds. During this time, Festerface can consume the Congealed Goo if he is brought close to it."},
			{id=12641,title="Damage Dealers",body="$bullet;Avoid standing in front of Festerface while he casts |cFF2959D3|Hspell:201598|h[Congealing Vomit]|h|r.\n$bullet;Quickly kill Congealed Goo to trigger |cFF2959D3|Hspell:201495|h[Recongealing]|h|r."},
			{id=12642,title="Healers",body="$bullet;Avoid standing in front of Festerface while he casts |cFF2959D3|Hspell:201598|h[Congealing Vomit]|h|r.\n$bullet;Each Congealed Goo increases the damage the party takes from |cFF2959D3|Hspell:201476|h[Fetid Stench]|h|r."},
			{id=12643,title="Tanks",body="$bullet;Avoid standing in front of Festerface while he casts |cFF2959D3|Hspell:201598|h[Congealing Vomit]|h|r.\n$bullet;Move Festerface to any Congealed Goo that is currently |cFF2959D3|Hspell:201495|h[Recongealing]|h|r so he can consume the Goo.\n$bullet;After consuming a Congealed Goo Festerface will gain |cFF2959D3|Hspell:201715|h[Yum!]|h|r."},
			{id=12644,title="Festerface"},
			{id=12645,title="Section 8"},
			{id=12646,title="Congealed Goo"},
			{id=12647,title="Section 8"},
			{id=12648,title="Section 9"},
			{id=12649,title="Section 10",body="$[!2,23\n\nIn Heroic or Mythic difficulty, each Congealed Goo that is consumed removes 20 energy from Festerface.$]"},
			{id=12650,title="Section 11",difficultyIDs={2,23}},
			{id=12651,title="Black Bile",difficultyIDs={2,23}},
			{id=12652,title="Section 13",difficultyIDs={2,23}},
		},
	},
	[1694]={
