		instanceID=777,
		order=1,
		name="Shivermaw",
		lore="Rumored to be one of Sindragosa's own brood, this fearsome frost wyrm was captured from the Frostwing Halls of Icecrown Citadel, where the forces of the Lich King labored to create these winged abominations.",
		dungeonEncounterID=1845,
		uiMapID=732,
