		sections={
			{id=12659,title="Overview",body="Shivermaw uses powerful Frost magic, forcing players to move between the upper and lower sections of the prison to avoid |cFF2959D3|Hspell:201672|h[Relentless Storm]|h|r and |cFF2959D3|Hspell:201960|h[Ice Bomb]|h|r."},
			{id=12660,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:201355|h[Wing Buffet]|h|r and |cFF2959D3|Hspell:201354|h[Tail Sweep]|h|r knock players back if they are in front of or behind Shivermaw.\n$bullet;Free players from Ice Blocks if they are hit by |cFF2959D3|Hspell:201672|h[Ice Bomb]|h|r."},
			{id=12661,title="Healers",body="$bullet;Tank movement speed is considerably slowed unless |cFF2959D3|Hspell:201379|h[Frost Breath]|h|r is dispelled.\n$bullet;|cFF2959D3|Hspell:201961|h[Ice Bomb]|h|r inflicts heavy damage to the entire group."},
			{id=12662,title="Tanks",body="$bullet;|cFF2959D3|Hspell:201379|h[Frost Breath]|h|r inflicts heavy damage and slows movement speed.\n$bullet;|cFF2959D3|Hspell:201355|h[Wing Buffet]|h|r periodically knocks back all players in front of Shivermaw."},
