	[1695]={
		encounterID=1695,
		instanceID=707,
		order=2,
		name="Inquisitor Tormentorum",
		lore="Of all the foul creatures that serve the Legion, the hooded inquisitors are perhaps the most mysterious, and most menacing. Tormentorum arrived in the aftermath of the initial assault upon the vault. As he drifts through the halls of the Vault, his gaze piercing the shadows in search of some vital secret, even other demons give him a wide berth.",
		dungeonEncounterID=1850,
		uiMapID=711,
		pin={x=0.4726,y=0.4935},
		difficultyIDs={1,2,8,23,24},
		npcIDs={111983,127336},
		displayIDs={64719},
		loot={
			{itemID=137525,diffs={},faction=-1},
			{itemID=137538,diffs={},faction=-1},
			{itemID=137511,diffs={},faction=-1},
			{itemID=137503,diffs={},faction=-1},
			{itemID=137518,diffs={},faction=-1},
			{itemID=137544,diffs={1,2,23},faction=-1},
			{itemID=137530,diffs={},faction=-1},
			{itemID=137543,diffs={1,2,23},faction=-1},
		},
		sections={
			{id=12668,title="Overview",body="Inquisitor Tormentorum siphons the energy of players and opens prisons at random. These prisons release additional enemies that players must deal with or risk getting overwhelmed."},
			{id=12669,title="Damage Dealers",body="$bullet;Interrupt |cFF2959D3|Hspell:200904|h[Sap Soul]|h|r.\n$bullet;Be prepared to dispatch the additional adds Inquisitor Tormentorum frees during the encounter.\n$bullet;Inquisitor Tormentorum is immune to all damage while he is freeing prisoners.\n$bullet;Facing a Tormenting Orb as it completes its |cFF2959D3|Hspell:212564|h[Inquisitive Stare]|h|r will negate the effects of the ability."},
			{id=12670,title="Healers",body="$bullet;If afflicted with |cFF2959D3|Hspell:200904|h[Sap Soul]|h|r, use an ability you can afford to not have available for a short while.\n$bullet;The prisoners freed by Inquisitor Tormentorum increase damage done to the party dramaticallly.\n$bullet;Facing a Tormenting Orb as it completes its |cFF2959D3|Hspell:212564|h[Inquisitive Stare]|h|r will negate the effects of the ability."},
			{id=12671,title="Tanks",body="$bullet;Interrupt |cFF2959D3|Hspell:200904|h[Sap Soul]|h|r.\n$bullet;Inquisitor Tormentorum frees prisoners when he reaches 70% and 40% health remaining. Be sure to establish threat on the freed prisoners.\n$bullet;Facing a Tormenting Orb as it completes its |cFF2959D3|Hspell:212564|h[Inquisitive Stare]|h|r will negate the effects of the ability."},
			{id=12672,title="Section 5",body="$[!23\n\nIn Mythic difficulty, Sap Soul is not interruptable.$]"},
			{id=13469,title="Section 29",difficultyIDs={2,8,23,24}},
			{id=13470,title="Section 30"},
			{id=12880,title="Open Prisons",body="Inquisitor opens groups of prison cells during the encounter."},
			{id=12881,title="Cellblock 3-3x468"},
			{id=12882,title="Felguard Annihilator",body="Will clear threat and charge to random enemies.  Deals a high amount of physical damage."},
			{id=12889,title="Section 20"},
			{id=12883,title="Shadowmoon Technician",body="Throws dynamite at random enemies and lays mines on the ground.  Also periodically silences a random caster."},
			{id=12890,title="Section 21"},
			{id=12884,title="Shadowmoon Warlock",body="Will empower allied demons to do significantly more damage."},
			{id=12891,title="Section 22"},
			{id=12892,title="Cellblock 3-0x68-1x0"},
			{id=12893,title="Faceless Voidcaster",body="Periodically fires a Shadow Crash at the location of a random enemy."},
			{id=12899,title="Section 23"},
