	[1696]={
		encounterID=1696,
		instanceID=777,
		order=2,
		name="Anub'esset",
		lore="Anub'esset, one of the few remaining ancient Nerubian crypt lords, was captured by the Kirin Tor during the invasion of Icecrown Citadel and imprisoned in Violet Hold. Set free during the Legion's invasion, his thoughts turn only to revenge against the living.",
		dungeonEncounterID=1852,
		uiMapID=732,
		pin={x=0.6682,y=0.256},
		difficultyIDs={1,2,23},
		npcIDs={205862},
		displayIDs={67630},
		loot={
			{itemID=137424,diffs={},faction=-1},
			{itemID=137429,diffs={},faction=-1},
