			{itemID=134418,diffs={},faction=-1},
		},
		sections={
			{id=12675,title="Overview",body="Anub'esset attacks the party and calls scarabs and beetles to assist him in battle. Players must quickly eliminate his minions before becoming overwhelmed."},
			{id=12676,title="Tank",body="$bullet;|cFF2959D3|Hspell:202217|h[Mandible Strike]|h|r deals heavy damage and reduces your healing taken for a short time.\n$bullet;|cFF2959D3|Hspell:202341|h[Impale]|h|r creates spikes in front of Anub'esset, which should be avoided."},
			{id=12677,title="Healer",body="$bullet;|cFF2959D3|Hspell:202217|h[Mandible Strike]|h|r deals heavy damage to the Tank and reduces their healing taken for a short time.\n$bullet;If Spitting Scarabs are not killed quickly, their |cFF2959D3|Hspell:202300|h[Poison Spit]|h|r will deal heavy damage.\n$bullet;When targeted by |cFF2959D3|Hspell:202341|h[Impale]|h|r, move away from other players to avoid damaging them."},
			{id=12678,title="Damage Dealers",body="$bullet;Quickly kill Spitting Scarabs after they are spawned by |cFF2959D3|Hspell:201863|h[Call of the Swarm]|h|r.\n$bullet;When targeted by |cFF2959D3|Hspell:202341|h[Impale]|h|r, move away from other players to avoid damaging them."},
			{id=12679,title="Section 5"},
			{id=12680,title="Section 6"},
			{id=12681,title="Section 7"},
			{id=12682,title="Spitting Scarab"},
			{id=12683,title="Section 9"},
			{id=12684,title="Blistering Beetle",body="On Heroic difficulty, Blistering Beetles will burrow into the fight, fixating on nearby players. When they come into contact with a player or die, they will explode, creating a pool of Blistering Ooze.",difficultyIDs={2,23}},
			{id=12685,title="Section 11",difficultyIDs={2,23}},
		},
	},
