	[1702]={
		encounterID=1702,
		instanceID=777,
		order=1,
		name="Blood-Princess Thal'ena",
		lore="Blood-Princess Thal'ena is the daughter of the powerful San'layn Queen Lana'thel. She has been locked inside Violet Hold since the Northrend campaign, suffering the gnawing pain of her eternal hunger. Now that her cell has opened, she intends to feed on the world.",
		dungeonEncounterID=1855,
		uiMapID=732,
		pin={x=0.3098,y=0.5648},
		difficultyIDs={1,2,23},
		npcIDs={102431},
		displayIDs={67638},
		loot={
			{itemID=137460,diffs={},faction=-1},
			{itemID=134457,diffs={},faction=-1},
			{itemID=134422,diffs={},faction=-1},
			{itemID=137461,diffs={},faction=-1},
			{itemID=137471,diffs={},faction=-1},
			{itemID=134404,diffs={},faction=-1},
			{itemID=137478,diffs={},faction=-1},
			{itemID=137462,diffs={},faction=-1},
			{itemID=134516,diffs={},faction=-1},
		},
		sections={
			{id=12720,title="Overview",body="Blood-Princess Thal'ena immediately uses |cFF2959D3|Hspell:202652|h[Vampyr's Kiss]|h|r to infect an enemy with |cFF2959D3|Hspell:202779|h[Essence of the Blood Princess]|h|r.\n\nWhen |cFF2959D3|Hspell:202779|h[Essence of the Blood Princess]|h|r wears off, the victim has a short amount of time to infect another target. If they cannot do so, they submit to |cFF2959D3|Hspell:202804|h[Uncontrollable Frenzy]|h|r.$[!2\n\nIn Heroic difficulty, Blood-Princess Thal'ena uses Blood Call to summon a Congealed Blood from a blood pool. If the Congealed Blood reaches the princess, it does damage to the party and heals the boss. Those effected by Essence of the Blood Princess can instantly kill a Congealed Blood by running through it.$]"},
			{id=12721,title="Damage Dealers",body="$bullet;When infected with |cFF2959D3|Hspell:202779|h[Essence of the Blood Princess]|h|r all your damage is increased."},
			{id=12722,title="Healers",body="$bullet;Every player infected with |cFF2959D3|Hspell:202779|h[Essence of the Blood Princess]|h|r increases the damage of |cFF2959D3|Hspell:203033|h[Shroud of Sorrow]|h|r."},
			{id=12723,title="Tanks",body="$bullet;Move Blood-Princess Thal'ena out of the blood pool when she casts |cFF2959D3|Hspell:202659|h[Blood Swarm]|h|r."},
			{id=12728,title="Blood-Princess Thal'ena"},
