			{id=12747,title="Section 12",difficultyIDs={2,23}},
			{id=12748,title="Congealed Blood",body="Summoned from existing blood pools in the area. Immediately begins making its way towards the Blood-Princess.",difficultyIDs={2,23}},
			{id=12749,title="Eternal Hunger",difficultyIDs={2,23}},
		},
	},
	[1703]={
