		sections={
			{id=12735,title="Overview",body="Nythendra's |cFF2959D3|Hspell:202977|h[Infested Breath]|h|r unleashes great gouts of insects and corruption, consuming 50 Energy. When Nythendra's Energy is depleted, she collapses to the ground and |cFF2959D3|Hspell:203552|h[Heart of the Swarm]|h|r begins. Once she is fully recharged, her form coalesces and she resumes her attack."},
			{id=13919,title="Damage Dealers",body="$bullet;Stay away from your allies while afflicted with |cFF2959D3|Hspell:203096|h[Rot]|h|r.\n$bullet;Quickly run out of |cFF2959D3|Hspell:202977|h[Infested Breath]|h|r.\n$bullet;Do not stand near insects during |cFF2959D3|Hspell:203552|h[Heart of the Swarm]|h|r.",difficultyIDs={14,15,17}},
			{id=13889,title="Damage Dealers",body="$bullet;Stay away from your allies while afflicted with |cFF2959D3|Hspell:203096|h[Rot]|h|r.\n$bullet;Quickly run out of |cFF2959D3|Hspell:202977|h[Infested Breath]|h|r.\n$bullet;Do not stand near insects during |cFF2959D3|Hspell:203552|h[Heart of the Swarm]|h|r.\n$bullet;Quickly damage allies aflicted with |cFF2959D3|Hspell:205043|h[Infested Mind]|h|r to free them.",difficultyIDs={16}},
			{id=12737,title="Healers",body="$bullet;Stay away from your allies while afflicted with |cFF2959D3|Hspell:203096|h[Rot]|h|r.\n$bullet;Quickly run out of |cFF2959D3|Hspell:202977|h[Infested Breath]|h|r.\n$bullet;Do not stand near insects during |cFF2959D3|Hspell:203552|h[Heart of the Swarm]|h|r."},
			{id=12738,title="Tanks",body="$bullet;Move away from others while afflicted with |cFF2959D3|Hspell:204463|h[Volatile Rot]|h|r.\n$bullet;Quickly run out of |cFF2959D3|Hspell:202977|h[Infested Breath]|h|r.\n$bullet;Do not stand near insects during |cFF2959D3|Hspell:203552|h[Heart of the Swarm]|h|r."},
			{id=13916,title="Stage One: The Plagued Dreamer"},
			{id=12828,title="Section 13",body="$[!15\n\nAll applications of Infested are removed once Nythendra completes Heart of the Swarm.$]",difficultyIDs={15,16}},
