	[1704]={
		encounterID=1704,
		instanceID=768,
		order=5,
		name="Dragons of Nightmare",
		lore="The Emerald Dream was entrusted to Ysera for safekeeping, and the mightiest of her green dragon brood were assigned to stand watch over four portals that connected directly to Azeroth. But even before the Cataclysm, these dragons began to show signs of corruption. Now, the path to the Nightmare's core runs through the dragons' lair.",
