	[1706]={
		encounterID=1706,
		instanceID=786,
		order=1,
		name="Skorpyron",
		lore="Deep within the foundations of the Nighthold, beneath the sea, lie long-forgotten vaults that give access to the Nightwell itself. This monstrous armored scorpid has made its home in one of these vaults. Infused with the power of the Nightwell, and surrounded by a teeming brood, Skorpyron presents a serious complication to an otherwise-promising back entry to the Nighthold.",
		dungeonEncounterID=1849,
		uiMapID=764,
