		sections={
			{id=12817,title="Overview",body="Skorpyron's lair is a constantly spawning chamber of scorpids that join the battle following |cFF2959D3|Hspell:204371|h[Call of the Scorpid]|h|r, but which also attack if any player strays too close."},
			{id=12818,title="Damage Dealers",body="$bullet;Take shelter behind |cFF2959D3|Hspell:204292|h[Crystaline Fragments]|h|r to protect yourself from |cFF2959D3|Hspell:204316|h[Shockwave]|h|r."},
			{id=12819,title="Healers",body="$bullet;Take shelter behind |cFF2959D3|Hspell:204292|h[Crystaline Fragments]|h|r to protect yourself from |cFF2959D3|Hspell:204316|h[Shockwave]|h|r."},
			{id=12820,title="Tanks",body="$bullet;|cFF2959D3|Hspell:204531|h[Arcane Tethers]|h|r accrue during |cFF2959D3|Hspell:204275|h[Arcanoslash]|h|r, and need to be broken to reduce damage taken.\n$bullet;Take shelter behind |cFF2959D3|Hspell:204292|h[Crystaline Fragments]|h|r to protect yourself from |cFF2959D3|Hspell:204316|h[Shockwave]|h|r."},
			{id=12825,title="Scorpid Spawning Ground",body="Skorpyron resides in an active spawning ground, continually creating Scorpids which inhabit the space throughout the encounter."},
			{id=12829,title="Crystalline Scorpid"},
