	[1718]={
		encounterID=1718,
		instanceID=800,
		order=1,
		name="Patrol Captain Gerdo",
		lore="Captain of the Duskwatch, Gerdo has devoted his life to keeping the peace within the walls of Suramar. Though he has a growing unease since the arrival of the Legion, he remains faithful and loyal to the leadership of Suramar. Elisande has safeguarded them for generations, and she knows what is best for the people of the city. Tonight, Gerdo's task is to ensure that only citizens with the proper credentials are able to enter a gathering of particular importance at the manor.",
		dungeonEncounterID=1868,
		uiMapID=761,
		pin={x=0.3168,y=0.2486},
		difficultyIDs={2,8,23,24},
		npcIDs={104215},
		displayIDs={68521},
		loot={
			{itemID=137484,diffs={},faction=-1},
			{itemID=134280,diffs={},faction=-1},
