			{itemID=134268,diffs={},faction=-1},
			{itemID=137483,diffs={},faction=-1},
			{itemID=134296,diffs={},faction=-1},
		},
		sections={
			{id=12928,title="Overview",body="Patrol Captain Gerdo locks down enemies while signalling for additional Nightwatch assistance."},
			{id=12929,title="Damage Dealers",body="$bullet;Jump to free yourself from |cFF2959D3|Hspell:207278|h[Arcane Lockdown]|h|r.\n$bullet;Quickly defeat Nightwatch Reinforcements when |cFF2959D3|Hspell:207806|h[Signal Beacon]|h|r occurs to prevent them from overwhelming the party."},
			{id=12930,title="Healers",body="$bullet;Jump to free yourself from |cFF2959D3|Hspell:207278|h[Arcane Lockdown]|h|r.\n$bullet;Be careful when Gerdo drinks his |cFF2959D3|Hspell:207815|h[Flask of the Solemn Night]|h|r, as he will inflict substantially more damage."},
			{id=12931,title="Tanks",body="$bullet;Jump to free yourself from |cFF2959D3|Hspell:207278|h[Arcane Lockdown]|h|r.\n$bullet;Gain threat on additional Nightwatch Reinforcements when Patrol Captain Gerdo uses |cFF2959D3|Hspell:207806|h[Signal Beacon]|h|r."},
			{id=12932,title="Ability"},
			{id=13709,title="Section 10",difficultyIDs={8,23}},
