	[1719]={
		encounterID=1719,
		instanceID=800,
		order=2,
		name="Talixae Flamewreath",
		lore="A sadistic eredar sorcerer, even as she understands the importance of the nightborne to her master's plans, Talixae chafes at the indignity of standing guard over a building full of elves. Nevertheless, she and her lieutenants remain vigilant, and while they live, no intruders will disrupt the gathering.",
		dungeonEncounterID=1869,
		uiMapID=761,
		pin={x=0.5772,y=0.5752},
		difficultyIDs={2,8,23,24},
		npcIDs={111149},
		displayIDs={69267},
		loot={
			{itemID=137491,diffs={1,2,23},faction=-1},
			{itemID=134460,diffs={},faction=-1},
			{itemID=134385,diffs={},faction=-1},
			{itemID=137492,diffs={1,2,23},faction=-1},
