			{itemID=137488,diffs={},faction=-1},
			{itemID=201994,diffs={8},faction=-1},
		},
		sections={
			{id=12933,title="Overview",body="Talixae and her Fel Covenant enforce the will of Gul'dan through might and flames. Each emissary's mere existence strengthens each of the others. Discovering methods to split them up would be the wisest path here."},
			{id=12934,title="Damage Dealers",body="$bullet;Move out of |cFF2959D3|Hspell:207887|h[Infernal Eruption]|h|r to avoid being blasted into the air.\n$bullet;Interrupt |cFF2959D3|Hspell:208165|h[Withering Soul]|h|r when possible to prevent it from stacking too much."},
			{id=12935,title="Healers",body="$bullet;Dispel |cFF2959D3|Hspell:208165|h[Withering Soul]|h|r from allies before it stacks too much.\n$bullet;Beware that |cFF2959D3|Hspell:207907|h[Burning Intensity]|h|r can inflict more and more damage as the fight continues.",difficultyIDs={2,8,23,24}},
			{id=13903,title="Healers",body="$bullet;Dispel |cFF2959D3|Hspell:208165|h[Withering Soul]|h|r from allies before it stacks too much.\n$bullet;Beware, |cFF2959D3|Hspell:207907|h[Burning Intensity]|h|r increases Fire damage dealt by Talixae.",difficultyIDs={1}},
			{id=12936,title="Tanks",body="$bullet;Beware that |cFF2959D3|Hspell:207907|h[Burning Intensity]|h|r can inflict more and more damage as the fight continues.\n$bullet;Interrupt |cFF2959D3|Hspell:208165|h[Withering Soul]|h|r when possible to prevent it from stacking too much.",difficultyIDs={2,8,23,24}},
			{id=13904,title="Tanks",body="$bullet;Beware, |cFF2959D3|Hspell:207907|h[Burning Intensity]|h|r increases Fire damage dealt by Talixae.\n$bullet;Interrupt |cFF2959D3|Hspell:208165|h[Withering Soul]|h|r when possible to prevent it from stacking too much.",difficultyIDs={1}},
			{id=13071,title="Section 6"},
			{id=13854,title="Infernal Imp",body="Infernal Eruptions cause the ground to crack open, spilling forth an Infernal Imp.",difficultyIDs={8,23}},
			{id=13855,title="Section 16"},
			{id=13856,title="Section 17"},
			{id=13072,title="Section 7"},
			{id=13079,title="Section 13"},
			{id=12937,title="Fel Covenant",body="Each demonic emissary gains increased power for nearby allies. Each additional member increases damage done by $207850s1% and health by $207850s2%"},
			{id=13074,title="Jazshariu",body="Jazshariu contributes his brute strength to the Fel Covenant."},
