	[1725]={
		encounterID=1725,
		instanceID=786,
		order=2,
		name="Chronomatic Anomaly",
		lore="The cavern at the base of the Nightwell is a maelstrom of raw energy, as the power to fuel an entire civilization courses from the earth. Born from this chaotic flux, the Chronomatic Anomaly is an embodiment of the power of the Eye of Aman'thul. As it lashes out with energy attacks, the bursts of energy warp the very flow of time.",
		dungeonEncounterID=1865,
		uiMapID=764,
		pin={x=0.5238,y=0.4741},
		difficultyIDs={14,15,16,17},
		npcIDs={83371,104415},
		displayIDs={55561,68616,68970},
		loot={
			{itemID=140894,diffs={},faction=-1},
			{itemID=140882,diffs={},faction=-1},
			{itemID=140792,diffs={},faction=-1},
