	[1726]={
		encounterID=1726,
		instanceID=768,
		order=7,
		name="Xavius",
		lore="Once a powerful mage, and a councilor to Queen Azshara, Xavius forged a pact with Sargeras to enable the Legion's first invasion of Azeroth. Cursed and tormented in the wake of that defeat, Xavius plots vengeance against the world from within the Rift of Aln. Those who venture into the Nightmare will face the full extent of his power, and his true form - a grotesque and distended monstrosity.",
		dungeonEncounterID=1864,
		uiMapID=788,
		pin={x=0.4886,y=0.4848},
		difficultyIDs={14,15,16,17},
		npcIDs={102206,103769,112155},
		displayIDs={65636,68390,68972,69120,69215,69684},
		loot={
			{itemID=139335,diffs={},faction=-1},
