	[1731]={
		encounterID=1731,
		instanceID=786,
		order=3,
		name="Trilliax",
		lore="Trilliax, once proud servant to the nightborne aristocracy, has been discarded and left to slowly deteriorate among other surplus constructs. While an unwavering will to carry out its tasks remains, the passage of time has splintered this construct's personality matrix. It now unpredictably switches from one mode to the next, ranging from doting caretaker to homicidal sterilizer, craving recognition and validation from a master that no longer exists.",
		dungeonEncounterID=1867,
		uiMapID=764,
		pin={x=0.4154,y=0.198},
		difficultyIDs={14,15,16,17},
		npcIDs={104288},
		displayIDs={68567},
		loot={
			{itemID=138375,diffs={},faction=-1},
