			{id=13475,title="The Maniac Personality Transference",difficultyIDs={16}},
			{id=13476,title="Section 29",difficultyIDs={16}},
			{id=13477,title="Section 30",difficultyIDs={16}},
			{id=13285,title="The Cleaner",body="Trilliax's cleaner personality takes over and wants to scrub the raid into oblivion."},
			{id=13007,title="Section 7"},
			{id=13464,title="Section 23",difficultyIDs={15,16}},
			{id=13083,title="Section 19"},
			{id=13008,title="Section 10"},
			{id=13281,title="The Maniac",body="Trilliax's maniac personality takes over, increasing the frequency of Arcane Slash."},
			{id=13010,title="Section 12"},
			{id=13106,title="Section 20"},
			{id=13011,title="Section 13"},
			{id=13282,title="The Caretaker",body="Trilliax's caretaker personality takes over and is no longer hostile."},
			{id=13013,title="Section 15"},
			{id=13015,title="Scrubber",body="These small arcane scrubbers are nigh indestructible and are used to clear rubbish. They prefer Toxic Slices, which will immediately destroy the scrubber, but if none are around they will clean pools of Arcane Seepage. As it cleans seepage, the scrubber gains energy. If a scrubber reaches max energy, it explodes."},
			{id=13016,title="Section 18"},
			{id=13014,title="Section 16"},
		},
	},
	[1732]={
		encounterID=1732,
		instanceID=786,
		order=8,
		name="Star Augur Etraeus",
		lore="The nightborne astromancer Etraeus has devoted long years of research to scouring the skies of Azeroth, seeking answers to the great mysteries of the universe. His scrying has shown him worlds beyond our ken, and the power of the Nightwell allows him to draw upon the essence of those worlds to amplify his own powers.",
