	[1738]={
		encounterID=1738,
		instanceID=768,
		order=2,
		name="Il'gynoth, Heart of Corruption",
		lore="Lodged in the hollows of a now-decrepit world tree, Il'gynoth is a manifestation of the horrors that lie at the heart of the Nightmare. It is a mass of corruption - a thing that should not be. Its tendrils seep through the ground, emerging in countless horrifying eyestalks and limbs.",
		dungeonEncounterID=1873,
		uiMapID=780,
		pin={x=0.4835,y=0.4829},
		difficultyIDs={14,15,16,17},
		npcIDs={105393,110808},
		displayIDs={69115,69231,69880,69881,69882,69925},
		loot={
			{itemID=139259,diffs={},faction=-1},
			{itemID=139188,diffs={},faction=-1},
			{itemID=139324,diffs={},faction=-1},
			{itemID=139258,diffs={},faction=-1},
			{itemID=139215,diffs={},faction=-1},
			{itemID=139256,diffs={},faction=-1},
			{itemID=139233,diffs={},faction=-1},
			{itemID=139257,diffs={},faction=-1},
			{itemID=139237,diffs={},faction=-1},
			{itemID=139206,diffs={},faction=-1},
			{itemID=139326,diffs={},faction=-1},
			{itemID=139325,diffs={},faction=-1},
			{itemID=139187,diffs={},faction=-1},
			{itemID=139202,diffs={},faction=-1},
			{itemID=139227,diffs={},faction=-1},
			{itemID=139213,diffs={},faction=-1},
			{itemID=137749,diffs={109},faction=-1},
			{itemID=139569,diffs={109},faction=-1},
			{itemID=139637,diffs={109},faction=-1},
		},
		sections={
			{id=13179,title="Overview",body="Players begin the encounter fighting against Il'gynoth's erupting eyestalks and tentacles, while the monstrous Eye bars the way to the heart of the tree. Defeating these tentacles spawns animated Nightmare Ichor globules, which players can destroy near the Eye to damage it.\n\nOnce the Eye is defeated, players can enter the hollow to damage Il'gynoth directly for a time, after which the Eye reforms to seal the entrance to the hollow once more, killing any players who remain inside. This repeats until players defeat Il'gynoth."},
			{id=13180,title="Tanks",body="$bullet;Dominator Tentacles' |cFF2959D3|Hspell:215234|h[Nightmarish Fury]|h|r and Nightmare Horrors' |cFF2959D3|Hspell:210984|h[Eye of Fate]|h|r deal heavy damage.\n$bullet;Nightmare Horrors create pools of |cFF2959D3|Hspell:208931|h[Nightmare Corruption]|h|r - move them to minimize the damage dealt.\n$bullet;Avoid players targeted by |cFF2959D3|Hspell:208689|h[Ground Slam]|h|r."},
			{id=13181,title="Healers",body="$bullet;Dominator Tentacles' |cFF2959D3|Hspell:215234|h[Nightmarish Fury]|h|r and Nightmare Horrors' |cFF2959D3|Hspell:210984|h[Eye of Fate]|h|r deal heavy damage to Tanks.\n$bullet;Dispel |cFF2959D3|Hspell:209469|h[Touch of Corruption]|h|r.\n$bullet;Lure Nightmare Ichors that are fixated on you to the Eye of Il'gynoth when they are low on health.\n$bullet;Move away from the raid when affected by |cFF2959D3|Hspell:208929|h[Spew Corruption]|h|r."},
			{id=13182,title="Damage Dealers",body="$bullet;Move away from the raid when affected by |cFF2959D3|Hspell:208929|h[Spew Corruption]|h|r.\n$bullet;Interrupt Deathglare Tentacles' |cFF2959D3|Hspell:208697|h[Mind Flay]|h|r.\n$bullet;Lure Nightmare Ichors that are fixated on you to the Eye of Il'gynoth when they are low on health, and wait to kill them until they are in range of the Eye.\n$bullet;Avoid players targeted by |cFF2959D3|Hspell:208689|h[Ground Slam]|h|r, and move away from other players when targeted by it."},
			{id=13184,title="Stage One: The Ruined Ground",body="Players engage creatures of nightmare while the Eye of Il'gynoth watches over them, directing the forces of corruption."},
			{id=13183,title="Nightmare Corruption"},
			{id=13501,title="Section 33",difficultyIDs={16}},
			{id=13649,title="Section 46",difficultyIDs={16}},
			{id=13185,title="The Eye of Il'gynoth"},
			{id=13201,title="Section 23"},
			{id=13244,title="Section 28"},
			{id=13186,title="Nightmare Ichor"},
			{id=13194,title="Section 16"},
			{id=13195,title="Section 18"},
			{id=13196,title="Section 17",body="$[!16\n\nOn Mythic Difficulty, all players in the encounter also suffer $209471s2 Shadow damage every $209471t2 seconds for $209471d. \n\nThis effect stacks.$]"},
			{id=13187,title="The Forces of Corruption",body="When killed, the forces of corruption will spawn Nightmare Ichor."},
			{id=13188,title="Nightmare Horror"},
			{id=13242,title="Section 27",body="$[!17\n\nOn Raid Finder difficulty, Eye of Fate only affects the Nightmare Horror's current target.$]"},
			{id=13202,title="Section 25"},
			{id=13190,title="Deathglare Tentacle"},
			{id=13199,title="Section 21"},
			{id=13191,title="Corruptor Tentacle"},
			{id=13200,title="Section 22"},
			{id=13189,title="Dominator Tentacle"},
			{id=13197,title="Section 19"},
			{id=13478,title="Section 32",body="$[!15,16\n\nOn Heroic difficulty and above, each time the Dominator Tentacle attacks a player with Nightmarish Fury, they will also permanently increase their Physical damage inflicted by $215233s2%. \n\nThis effect stacks.$]"},
			{id=13198,title="Section 20"},
			{id=13192,title="Stage Two: The Heart of Corruption",body="When the Eye of Il'gynoth is destroyed, the chamber holding Il'gynoth's beating heart is revealed."},
			{id=13193,title="The Heart of Il'gynoth"},
			{id=13502,title="Section 33"},
			{id=13243,title="Section 26"},
			{id=13321,title="Section 31"},
			{id=13561,title="Section 35",difficultyIDs={16}},
			{id=13838,title="Section 46",difficultyIDs={14,15,17}},
			{id=13570,title="Shriveled Eyestalk",difficultyIDs={16}},
			{id=13571,title="Section 43"},
		},
	},
	[1743]={
		encounterID=1743,
		instanceID=786,
		order=9,
		name="Grand Magistrix Elisande",
		lore="Elisande once distinguished herself by resisting the Legion. She and her highborne followers broke away from Queen Azshara and the dark path she was taking, harnessing the power of the Eye of Aman'thul to create the Nightwell to protect Suramar from the Sundering. But over ten thousand years later, the Legion's arrival offered her no such recourse. She has cast her lot with the demons, hoping to once again use the power of the Nightwell - albeit this time in a very different sense - to save her people.",
		dungeonEncounterID=1872,
		uiMapID=770,
		pin={x=0.4597,y=0.4569},
		difficultyIDs={14,15,16,17},
		npcIDs={106643,110965,211664},
		displayIDs={55131,55143,69082},
		loot={
			{itemID=138342,diffs={},faction=-1},
			{itemID=138378,diffs={},faction=-1},
			{itemID=140837,diffs={},faction=-1},
			{itemID=138343,diffs={},faction=-1},
			{itemID=140806,diffs={},faction=-1},
			{itemID=138357,diffs={},faction=-1},
			{itemID=140911,diffs={},faction=-1},
			{itemID=138314,diffs={},faction=-1},
			{itemID=138331,diffs={},faction=-1},
			{itemID=138330,diffs={},faction=-1},
			{itemID=138313,diffs={},faction=-1},
			{itemID=140910,diffs={},faction=-1},
			{itemID=140842,diffs={},faction=-1},
			{itemID=138355,diffs={},faction=-1},
			{itemID=140893,diffs={},faction=-1},
			{itemID=138332,diffs={},faction=-1},
			{itemID=140912,diffs={},faction=-1},
			{itemID=138356,diffs={},faction=-1},
			{itemID=140810,diffs={},faction=-1},
			{itemID=138312,diffs={},faction=-1},
			{itemID=140889,diffs={},faction=-1},
			{itemID=140805,diffs={},faction=-1},
			{itemID=140890,diffs={},faction=-1},
			{itemID=137762,diffs={109},faction=-1},
			{itemID=139650,diffs={109},faction=-1},
			{itemID=143565,diffs={14,15,16},faction=-1},
			{itemID=143568,diffs={14,15,16},faction=-1},
			{itemID=143575,diffs={14,15,16},faction=-1},
		},
		sections={
			{id=13218,title="Overview",body="Grand Magistrix Elisande harness the power of the Nightwell to shape time itself. When her health is low and she is nearing defeat, she rewinds time to send players back to the point at which they first engaged her. The fight recommences from this point, but Elisande uses new abilities mixed in with echoes of her past actions. She can perform this feat twice, after which time can no longer save her."},
			{id=13219,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:210022|h[Epocheric Orb]|h|r damages the entire raid if allowed to strike the ground.\n$bullet;Expedient Elementals continually damage the raid with |cFF2959D3|Hspell:209568|h[Exothermic Release]|h|r until they are dispatched. This damage increases with each successful cast."},
			{id=13220,title="Healers",body="$[14$bullet;|cFF2959D3|Hspell:210387|h[Permeliative Torment]|h|r inflicts increasing damage over time to its victims.$]\n$[15$bullet;|cFF2959D3|Hspell:210387|h[Permeliative Torment]|h|r inflicts increasing damage over time to its victims.$]\n$[16$bullet;|cFF2959D3|Hspell:210387|h[Permeliative Torment]|h|r inflicts increasing damage over time to its victims.$]\n$bullet;|cFF2959D3|Hspell:210022|h[Epocheric Orb]|h|r damages the entire raid if allowed to strike the ground.\n$[17$bullet;|cFF2959D3|Hspell:229738|h[Cascadent Star]|h|r will damage a large portion of the raid.$]\n$[14$bullet;|cFF2959D3|Hspell:209597|h[Conflexive Burst]|h|r's duration can be manipulated by using time zones.$]\n$[15$bullet;|cFF2959D3|Hspell:209597|h[Conflexive Burst]|h|r's duration can be manipulated by using time zones.$]\n$[16$bullet;|cFF2959D3|Hspell:209597|h[Conflexive Burst]|h|r's duration can be manipulated by using time zones.$]"},
			{id=13221,title="Tanks",body="$bullet;In each time layer, Elisande employs a different ability to threaten tanks.\n$bullet;|cFF2959D3|Hspell:209973|h[Ablating Explosion]|h|r inflicts falloff damage to the entire raid when it expires.\n$bullet;Interrupt |cFF2959D3|Hspell:209971|h[Ablative Pulse]|h|r."},
			{id=13783,title="Section 27"},
			{id=13241,title="Section 24"},
			{id=14406,title="Section 32"},
			{id=13225,title="Time Elementals",body="Grand Magistrix periodically summons Time Elementals to aid her in combat. When these elementals are dispatched they leave behind a rift that persists until they are consumed."},
			{id=13226,title="Recursive Elemental",body="When this elemental dies it leaves behind a zone of Slow Time."},
			{id=13930,title="Section 30"},
			{id=13227,title="Section 15"},
			{id=13888,title="Section 29"},
			{id=13228,title="Postpone",difficultyIDs={16}},
			{id=13784,title="Section 28"},
			{id=13238,title="Inexorant"},
			{id=13229,title="Expedient Elemental",body="When this elemental dies it leaves behind a zone of  Fast Time."},
			{id=13230,title="Burst"},
			{id=13231,title="Expedite",difficultyIDs={16}},
			{id=13239,title="Section 22"},
			{id=13222,title="Time Layer 1",body="While in this Time Layer Grand Magistrix Elisande will use her |cFF2959D3|Hspell:209168|hSpanning Singularity|h|r and |cFF2959D3|Hspell:208807|hArcanetic Ring|h|r abilities."},
			{id=13223,title="Section 6",body="$[!14,15,16,17\n\nThis ability echoes.$]\n$[!16\n\nIn Mythic Difficulty, the Arcanetic Ring expands to the outside of the room after collapsing.$]",difficultyIDs={15,16}},
			{id=15135,title="Section 33",difficultyIDs={14}},
			{id=13233,title="Section 10",body="$[!14,15,16,17\n\nSpanning Singularities appear at the same time and place in successive Time Layers.$]\n$[!16\n\nThis ability echoes in Mythic Difficulty.$]"},
			{id=13268,title="Section 23"},
			{id=13235,title="Time Layer 2",body="While in this Time Layer Grand Magistrix Elisande will use her |cFF2959D3|Hspell:210022|hEpocheric Orb|h|r and |cFF2959D3|Hspell:209242|hDelphuric Beam|h|r abilities."},
			{id=13236,title="Section 12",body="$[!16\n\nThis ability echoes in Mythic difficulty, and the beam continues through the target rather than stopping at the target.$]"},
			{id=13237,title="Epochera",body="$[!14,15,16,17\n\nThis ability echoes.$]\n$[!16\n\nIn Mythic difficulty, players catching the Orbs are afflicted with Epocheric Vulnerability.$]",difficultyIDs={15,16}},
			{id=14266,title="Section 31",difficultyIDs={16}},
			{id=15136,title="Section 34",difficultyIDs={14}},
			{id=13269,title="Section 23"},
			{id=13232,title="Time Layer 3",body="While in this Time Layer Grand Magistrix Elisande will use her |cFF2959D3|Hspell:209597|hConflexive Burst|h|r and |cFF2959D3|Hspell:210387|hPermeliative Torment|h|r abilities."},
			{id=13224,title="Section 7"},
			{id=13234,title="Section 9",body="$[!16\n\nIn Mythic difficulty, the damage of this ability inflicts falloff damage to all players in the raid.$]",difficultyIDs={14,15,16}},
			{id=13270,title="Section 23"},
		},
	},
	[1744]={
		encounterID=1744,
		instanceID=768,
		order=3,
		name="Elerethe Renferal",
		lore="Elerethe, once a mighty druid and adept shapeshifter, was led down a dark path by the belief that she was betrayed by her closest allies. Her consciousness now resides in the nightmare, damning her to an existence of fear, confusion, and hatred.",
		dungeonEncounterID=1876,
		uiMapID=779,
		pin={x=0.3314,y=0.6141},
		difficultyIDs={14,15,16,17},
