	[1749]={
		encounterID=1749,
		instanceID=822,
		order=10,
		name="Nithogg",
		lore="The great dragon Nithogg was once of the Thorignir, having left the brood shortly after they swore fealty to the titan keepers. Nithogg believed that one day he would be more powerful than even the keepers, and refused to be their subject. Instead, he took up roost in the mountain Nastrondir, where he raises his brood and terrorizes the nearby lands whenever the mood strikes him.",
		uiMapID=449,
		pin={x=0.2934,y=0.3505},
		difficultyIDs={14,15,16,17},
		npcIDs={107023,107544},
		displayIDs={69816},
		loot={
			{itemID=141541,diffs={},faction=-1},
			{itemID=141420,diffs={},faction=-1},
			{itemID=141424,diffs={},faction=-1},
