	[1750]={
		encounterID=1750,
		instanceID=768,
		order=6,
		name="Cenarius",
		lore="The demigod Cenarius is the father of druidism in Azeroth, and one of Azeroth's oldest and most powerful protectors. His disturbing slumber within the groves of Val'sharah was the first sign of the depth of the growing threat from within the Nightmare. That dark power now has complete hold over him, and he may lie beyond hope of redemption.",
		dungeonEncounterID=1877,
		uiMapID=787,
		pin={x=0.6001,y=0.3346},
		difficultyIDs={14,15,16,17},
		npcIDs={104636,106482,113534,192649},
		displayIDs={68656,70004},
		loot={
			{itemID=139333,diffs={},faction=-1},
			{itemID=139192,diffs={},faction=-1},
			{itemID=139207,diffs={},faction=-1},
			{itemID=139218,diffs={},faction=-1},
			{itemID=139198,diffs={},faction=-1},
			{itemID=139334,diffs={},faction=-1},
			{itemID=139225,diffs={},faction=-1},
			{itemID=139263,diffs={},faction=-1},
			{itemID=139248,diffs={},faction=-1},
			{itemID=139194,diffs={},faction=-1},
			{itemID=139211,diffs={},faction=-1},
