			{itemID=137753,diffs={109},faction=-1},
			{itemID=139641,diffs={109},faction=-1},
		},
		sections={
			{id=13335,title="Overview",body="The fallen Cenarius periodically creates Nightmare Seeds, which germinate for a short duration and then summon an Ally of Nightmare that must be defeated. Malfurion aids in the battle and cleanses the Nightmare Seed with the largest number of nearby players, purifying that Ally so that it instead helps the raid."},
			{id=13336,title="Damage Dealers",body="$bullet;Interrupt |cFF2959D3|Hspell:211368|h[Twisted Touch of Life]|h|r cast by the Twisted Sister.\n$bullet;Defeat the Rotten Drakes before |cFF2959D3|Hspell:211178|h[Nightmare Buffet]|h|r becomes lethal.\n$bullet;Use Malfurion's |cFF2959D3|Hspell:212630|h[Cleansed Ground]|h|r to avoid damage from |cFF2959D3|Hspell:210279|h[Creeping Nightmares]|h|r.\n$bullet;Malfurion's |cFF2959D3|Hspell:212630|h[Cleansed Ground]|h|r fully clears stacks of |cFF2959D3|Hspell:210279|h[Creeping Nightmares]|h|r from any players near the chosen target."},
			{id=13337,title="Healers",body="$bullet;The Nightmare Drake's |cFF2959D3|Hspell:211180|h[Nightmare Buffet]|h|r deals heavy raid damage.\n$bullet;Use Malfurion's |cFF2959D3|Hspell:212630|h[Cleansed Ground]|h|r to avoid damage from |cFF2959D3|Hspell:210279|h[Creeping Nightmares]|h|r.\n$bullet;Malfurion's |cFF2959D3|Hspell:212630|h[Cleansed Ground]|h|r fully clears stacks of |cFF2959D3|Hspell:210279|h[Creeping Nightmares]|h|r from any players near the chosen target."},
			{id=13338,title="Tanks",body="$bullet;Be mindful of |cFF2959D3|Hspell:210346|h[Dread Thorns]|h|r when positioning Cenarius.\n$bullet;Be quick to grab the attention of Forces of Nightmare as they spawn.\n$bullet;Use Malfurion's |cFF2959D3|Hspell:212630|h[Cleansed Ground]|h|r to avoid damage from |cFF2959D3|Hspell:210279|h[Creeping Nightmares]|h|r.\n$bullet;Malfurion's |cFF2959D3|Hspell:212630|h[Cleansed Ground]|h|r fully clears stacks of |cFF2959D3|Hspell:210279|h[Creeping Nightmares]|h|r from any players near the chosen target."},
			{id=13479,title="Stage One: Forces of Nightmare!"},
			{id=13480,title="Malfurion Stormrage"},
			{id=13481,title="Section 13"},
			{id=13482,title="Section 29"},
			{id=13483,title="Cenarius"},
			{id=13484,title="Section 6"},
			{id=13485,title="Nightmare Brambles"},
			{id=13486,title="Thorns",body="$[!15,16\n\nOn Heroic and Mythic Difficulty, Aura of Dread Thorns affects all enemies within 30 yards.$]\n\n$[!14,17\n\nOn Raid Finder and Normal Difficulty, Aura of Dread Thorns affects all enemies within 20 yards.$]"},
			{id=13487,title="Allies of Nightmare",body="$[!16\n\nOn Mythic difficulty, existing Allies of Nature are corrupted by Cenarius and fall to the Nightmare, assaulting all nearby players.$]"},
			{id=13892,title="Section 47",difficultyIDs={16}},
			{id=13347,title="Forces of Nightmare",body="Forces of Nightmare will spawn after a short duration if not Cleansed. Players can signal Malfurion to Cleanse the ground near an Ally of Nightmare by being near the location that it is being summoned at. Malfurion will choose to cast |cFF2959D3|Hspell:212630|h[Cleansing Ground]|h|r on the Ally of Nightmare with the most players near it."},
			{id=13348,title="Corrupted Wisp",body="Many Corrupted Wisps will spawn around the edge of the room if the Tormented Souls are not Cleansed."},
			{id=13349,title="Section 14"},
			{id=13929,title="Section 50",difficultyIDs={16}},
			{id=13350,title="Nightmare Ancient",body="A Nightmare Ancient will spawn under the Corrupted Sapling if it is not cleansed."},
			{id=13351,title="Section 16",difficultyIDs={14,15,17}},
			{id=13352,title="Section 17",difficultyIDs={14,15,17}},
			{id=13927,title="Section 48",body="$[!16 \n\n In Mythic difficulty, the Nightmare Ancient will cast Desiccating Stomp twice in rapid succession. $]",difficultyIDs={16}},
			{id=13928,title="Section 49",difficultyIDs={16}},
			{id=13354,title="Rotten Drake",body="A Rotten Drake will spawn from the Corrupted Emerald Egg if it is not cleansed."},
			{id=13355,title="Section 20"},
			{id=13356,title="Section 21"},
			{id=13357,title="Twisted Sister",body="A Twisted Sister will spawn from the Corrupted Nature if it is not cleansed."},
			{id=13358,title="Section 23"},
			{id=13359,title="Section 24"},
			{id=13360,title="Section 25",difficultyIDs={14,15,16}},
			{id=13361,title="Allies of Nature",body="Allies of Nature will spawn after a short duration once Cleansed by Malfurion's |cFF2959D3|Hspell:212630|h[Cleansing Ground]|h|r."},
			{id=13362,title="Wisp",body="Many Wisps will spawn around the edge of the room if the Tormented Souls are Cleansed."},
			{id=13363,title="Section 28"},
			{id=13364,title="Section 30"},
			{id=13365,title="Cleansed Ancient",body="A Cleansed Ancient will spawn from the Sapling if it is cleansed."},
			{id=13366,title="Section 32"},
			{id=13367,title="Emerald Drake",body="An Emerald Drake will spawn from the Emerald Egg if it is cleansed."},
			{id=13368,title="Section 34"},
			{id=13369,title="Redeemed Sister",body="A Redeemed Sister will spawn from the Corrupted Nature if it is cleansed."},
			{id=13370,title="Section 36"},
			{id=13488,title="Stage Two: Your Nightmare Ends!",body="After the last wave of Forces of Nightmare are defeated or when Cenarius reaches 35% health Stage Two will begin."},
