	[1751]={
		encounterID=1751,
		instanceID=786,
		order=4,
		name="Spellblade Aluriel",
		lore="Aluriel always had an affinity for magic. She rose through the ranks of the Nightguard effortlessly, having a natural talent with the sword. But no matter how strong she became, she wanted more. She studied with the mages at the University of Suramar, spending her days in combat training and her evenings in the artificery. She forged her weapons and armor in the Nightwell, weaving magic spells into the precious metals. She is the first Spellblade, adept in the schools of Fire, Frost and Arcane.",
		dungeonEncounterID=1871,
		uiMapID=766,
		pin={x=0.394,y=0.3965},
		difficultyIDs={14,15,16,17},
		npcIDs={81378,104881,107699,120933},
		displayIDs={1204,68819,69885,69906,70177},
		loot={
			{itemID=140877,diffs={},faction=-1},
			{itemID=140905,diffs={},faction=-1},
			{itemID=140895,diffs={},faction=-1},
