			{itemID=140813,diffs={},faction=-1},
			{itemID=140832,diffs={},faction=-1},
			{itemID=140866,diffs={},faction=-1},
			{itemID=140867,diffs={},faction=-1},
			{itemID=140852,diffs={},faction=-1},
			{itemID=140868,diffs={},faction=-1},
			{itemID=140850,diffs={},faction=-1},
			{itemID=140878,diffs={},faction=-1},
			{itemID=140834,diffs={},faction=-1},
			{itemID=140796,diffs={},faction=-1},
			{itemID=256682,diffs={},faction=-1},
			{itemID=137757,diffs={109},faction=-1},
			{itemID=139645,diffs={109},faction=-1},
		},
		sections={
			{id=13398,title="Overview",body="Spellblade Aluriel cycles between three enchantments: Frost, Fire, and Arcane. Each enchantment grants her an ability that she can only use while she's under the effect of that enchantment. She will then manipulate that magic with a few commands: replicate, detonate, and animate."},
			{id=13890,title="Tanks",body="$bullet;When Aluriel performs |cFF2959D3|Hspell:212494|h[Annihilate]|h|r, gather together to share the damage.\n$bullet;Transfer |cFF2959D3|Hspell:212587|h[Mark of Frost]|h|r to an ally when its damage becomes excessive, but be mindful that each transfer triggers an explosion.\n$bullet;Quickly move away from the target of |cFF2959D3|Hspell:213328|h[Detonate: Arcane Orb]|h|r, which deals more damage the closer players are to the impact point.",difficultyIDs={14,17}},
			{id=13403,title="Tanks",body="$bullet;When Aluriel performs |cFF2959D3|Hspell:212494|h[Annihilate]|h|r, gather together to share the damage.\n$bullet;Transfer |cFF2959D3|Hspell:212587|h[Mark of Frost]|h|r to an ally when its damage becomes excessive, but be mindful that each transfer triggers an explosion.\n$bullet;Quickly move away from the target of |cFF2959D3|Hspell:213328|h[Detonate: Arcane Orb]|h|r, which deals more damage the closer players are to the impact point.\n$bullet;Interrupt Fiery Enchantments when they cast |cFF2959D3|Hspell:213281|h[Pyroblast]|h|r, which deals critical damage to a target.",difficultyIDs={15,16}},
			{id=13400,title="Healers",body="$bullet;Transfer |cFF2959D3|Hspell:212587|h[Mark of Frost]|h|r to an ally when its damage becomes excessive, but be mindful that each transfer triggers an explosion.\n$bullet;Quickly move away from the target of |cFF2959D3|Hspell:213328|h[Detonate: Arcane Orb]|h|r, which deals more damage the closer players are to the impact point."},
			{id=13891,title="Damage Dealers",body="$bullet;Kill Arcane Enchantments quickly to prevent them from triggering |cFF2959D3|Hspell:213568|h[Armageddon]|h|r.\n$bullet;Transfer |cFF2959D3|Hspell:212587|h[Mark of Frost]|h|r to an ally when its damage becomes excessive, but be mindful that each transfer triggers an explosion.\n$bullet;Quickly move away from the target of |cFF2959D3|Hspell:213328|h[Detonate: Arcane Orb]|h|r, which deals more damage the closer players are to the impact point.",difficultyIDs={14,17}},
			{id=13401,title="Damage Dealers",body="$bullet;Kill Arcane Enchantments quickly to prevent them from triggering |cFF2959D3|Hspell:213568|h[Armageddon]|h|r.\n$bullet;Transfer |cFF2959D3|Hspell:212587|h[Mark of Frost]|h|r to an ally when its damage becomes excessive, but be mindful that each transfer triggers an explosion.\n$bullet;Quickly move away from the target of |cFF2959D3|Hspell:213328|h[Detonate: Arcane Orb]|h|r, which deals more damage the closer players are to the impact point.\n$bullet;Interrupt Fiery Enchantments when they cast |cFF2959D3|Hspell:213281|h[Pyroblast]|h|r, which deals critical damage to a target.",difficultyIDs={15,16}},
			{id=13375,title="Champion of Blades"},
			{id=13374,title="Section 1"},
			{id=13376,title="Master of Frost"},
			{id=13377,title="Section 6"},
			{id=13378,title="Section 7"},
			{id=13381,title="Replicate: Mark of Frost",body="Additional targets are affected by Mark of Frost."},
			{id=13382,title="Section 8"},
			{id=13383,title="Section 11"},
			{id=13416,title="Animate: Mark of Frost",body="From the Pools of Frost, the remnants of magic stir. Aluriel commands Icy Enchantments to rise.",difficultyIDs={15,16}},
			{id=13417,title="Section 13",difficultyIDs={15,16}},
			{id=13387,title="Animate: Mark of Frost",body="From the Pools of Ice, the remnants of magic stir. Aluriel commands Icy Enchantments to rise.",difficultyIDs={14,17}},
