	[1756]={
		encounterID=1756,
		instanceID=822,
		order=13,
		name="The Soultakers",
		lore="Sent by Helya to raid the crypts of noble vrykul kings, this trio of raiders and their crew has found their way into the Tomb of the Old Kings and seek to claim the souls that rest there.",
		uiMapID=449,
		pin={x=0.6906,y=0.2671},
		difficultyIDs={14,15,16,17},
		npcIDs={106981,106982,106984},
		displayIDs={62703,69803,69849},
		loot={
			{itemID=141436,diffs={},faction=-1},
			{itemID=141514,diffs={},faction=-1},
			{itemID=141506,diffs={},faction=-1},
			{itemID=141434,diffs={},faction=-1},
