	[1761]={
		encounterID=1761,
		instanceID=786,
		order=7,
		name="High Botanist Tel'arn",
		lore="From his youth, the nightborne Tel'arn was fascinated by plant life: the resilience and adaptability of weeds, the ability of simple grass to harness the power of the sun, the way a tree may be divided into two, or two branches grafted into one. Aided by the energies of the Nightwell, he has transformed himself to the point that he is scarely recognizable as a nightborne elf. He now considers himself something far, far greater.",
		dungeonEncounterID=1886,
		uiMapID=767,
		pin={x=0.6586,y=0.3447},
		difficultyIDs={14,15,16,17},
		npcIDs={104528,109038,109040,109041},
		displayIDs={68963,70822,70823,70824},
		loot={
			{itemID=140801,diffs={},faction=-1},
			{itemID=140836,diffs={},faction=-1},
			{itemID=140883,diffs={},faction=-1},
			{itemID=140896,diffs={},faction=-1},
			{itemID=140874,diffs={},faction=-1},
			{itemID=140881,diffs={},faction=-1},
			{itemID=140802,diffs={},faction=-1},
			{itemID=140822,diffs={},faction=-1},
			{itemID=140839,diffs={},faction=-1},
			{itemID=140886,diffs={},faction=-1},
			{itemID=140908,diffs={},faction=-1},
			{itemID=140861,diffs={},faction=-1},
			{itemID=140873,diffs={},faction=-1},
			{itemID=137759,diffs={109},faction=-1},
			{itemID=139647,diffs={109},faction=-1},
			{itemID=143751,diffs={109},faction=-1},
		},
		sections={
			{id=13675,title="Overview",body="High Botanist Tel'arn uses Arcane, Nature, and Solar magic to defend his garden. When he reaches 75% and 50% health remaining he divides his energy, creating empowered forms that focus in a particular school of magic. This division removes High Botanist Tel'arn's access to that school of magic, but the empowered form gains new abilities."},
			{id=13676,title="Damage Dealers",body="$bullet;Move away from targets of |cFF2959D3|Hspell:218424|h[Parasitic Fetter]|h|r and quickly kill Parasitic Lashers.\n$bullet;Damage |cFF2959D3|Hspell:218774|h[Plasma Spheres]|h|r so that they die at least $218780d apart from one another to avoid lethal damage from |cFF2959D3|Hspell:218780|h[Plasma Explosion]|h|r. \n$bullet;Avoid |cFF2959D3|Hspell:218438|h[Controlled Chaos]|h|r and |cFF2959D3|Hspell:218148|h[Solar Collapse]|h|r."},
			{id=13677,title="Tanks",body="$bullet;Take turns tanking Tel'arn to manage the application of |cFF2959D3|Hspell:218502|h[Recursive Strikes]|h|r.\n$bullet;Position Naturalist Tel'arn away from his allies and quickly move him out of |cFF2959D3|Hspell:218927|h[Grace of Nature]|h|r.\n$bullet;High Botanist Tel'arn splits into images that must be tanked at 75% and 50% health remaining."},
			{id=13678,title="Healers",body="$bullet;|cFF2959D3|Hspell:218780|h[Plasma Explosion]|h|r inflicts significant damage to all players.\n$bullet;Dispel |cFF2959D3|Hspell:218424|h[Parasitic Fetter]|h|r when your allies have moved far enough away to avoid Parasitic Lashers.\n$bullet;|cFF2959D3|Hspell:218438|h[Controlled Chaos]|h|r inflicts moderate damage to all players with each explosion."},
			{id=13679,title="Stage One: The High Botanist",difficultyIDs={14,15,17}},
			{id=13680,title="Section 8"},
			{id=13685,title="Section 11"},
			{id=13686,title="Section 12"},
			{id=13699,title="Parasitic Lasher",body="Pursues the closest player and attempts to jump into them and afflict them with Parasitic Fetter. Once Parasitic Fetter is dispelled again, the parasite is recreated at the same health it had when it afflicted the target with Parasitic Fetter."},
			{id=13702,title="Section 27"},
			{id=13687,title="Section 13"},
			{id=13681,title="Stage Two: Nightosis",body="When High Botanist Tel'arn reaches 75% health remaining, he sacrifices his ability to cast Solar magic to create an empowered Solar image of himself.",difficultyIDs={14,15,17}},
			{id=13682,title="Solarist Tel'arn"},
			{id=13688,title="Section 14"},
			{id=13689,title="Section 15"},
			{id=13690,title="Section 16"},
			{id=13698,title="Section 24"},
			{id=13683,title="Stage Three: Pure Forms",body="When High Botanist Tel'arn reaches 50% health remaining, he divides his remaining power into an empowered Nature and empowered Arcane image.",difficultyIDs={14,15,17}},
			{id=13684,title="Naturalist Tel'arn"},
			{id=13691,title="Section 17"},
			{id=13692,title="Section 20"},
			{id=13693,title="Section 21"},
			{id=13700,title="Parasitic Lasher",body="Pursues the closest player and attempts to jump into them and afflict them with Parasitic Fetter. Once Parasitic Fetter is dispelled again, the parasite is recreated at the same health it had when it afflicted the target with Parasitic Fetter."},
			{id=13703,title="Section 28"},
			{id=13694,title="Arcanist Tel'arn"},
			{id=13695,title="Section 23"},
			{id=13696,title="Section 19"},
			{id=13697,title="Section 22"},
			{id=13824,title="Stage One: Division of Power",body="On Mythic difficutly, High Botanist Tel'arn starts the fight in his three pure forms and no longer shares health between the forms. Whenever a form dies, the remaining are healed to full health and gain additional effects on their abilities.",difficultyIDs={16}},
			{id=13825,title="Arcanist Tel'arn",difficultyIDs={16}},
			{id=13826,title="Recursive Strikes",difficultyIDs={16}},
			{id=13827,title="Section 34",difficultyIDs={16}},
			{id=13828,title="Section 36",difficultyIDs={16}},
			{id=13830,title="Solarist Tel'arn",difficultyIDs={16}},
			{id=13832,title="Section 37",difficultyIDs={16}},
			{id=13833,title="Section 38",difficultyIDs={16}},
			{id=13834,title="Section 39",difficultyIDs={16}},
			{id=14487,title="Section 62",difficultyIDs={16}},
			{id=13831,title="Naturalist Tel'arn",difficultyIDs={16}},
			{id=13835,title="Section 40",difficultyIDs={16}},
			{id=13836,title="Section 41",difficultyIDs={16}},
			{id=13837,title="Section 42",difficultyIDs={16}},
			{id=14467,title="Stage Two: Coallesced Energy",body="When one of Tel'arn's forms dies, the remaining forms become empowered with its energy.",difficultyIDs={16}},
			{id=14468,title="Arcanist Tel'arn's Death"},
			{id=14469,title="Solarist Tel'arn"},
			{id=14500,title="Section 72"},
			{id=14491,title="Section 66"},
			{id=14501,title="Section 73"},
			{id=14502,title="Section 74"},
			{id=14470,title="Naturalist Tel'arn"},
			{id=14503,title="Section 75"},
			{id=14504,title="Section 76"},
			{id=14498,title="Parasitic Fetter",body="High Botanist Tel'arn roots a random player in place, inflicting $218304s2 Nature damage every second until dispelled. This effect increases in damage by 10% each time it ticks.\n\nWhen Parasitic Fetter is removed a Controlled Chaos occurs and Parasitic Lashers are formed that pursues a random player. If the parasite reaches its target, it jumps into them and afflicts them with Parasitic Fetter."},
			{id=14471,title="Solarist Telarn's Death"},
			{id=14473,title="Arcanist Tel'arn"},
			{id=14505,title="Section 82"},
			{id=14486,title="Section 61"},
			{id=14488,title="Section 63"},
			{id=14506,title="Section 83"},
			{id=14474,title="Naturalist Tel'arn"},
			{id=14492,title="Toxic Spores",body="Naturalist Tel'arn shoots $219233s1 Toxic Spores at a random player's location that persist for $219231d. If any player comes into contact with the spore it bursts, inflicting $219235s1 Nature damage to them every $219235t1 sec for $219235d. In addition a Solar Collapse occurs at the target's location when Toxic Spores is cast."},
			{id=14507,title="Section 84"},
			{id=14508,title="Section 85"},
			{id=14472,title="Naturalist Telarn's Death"},
			{id=14475,title="Arcanist Tel'arn"},
			{id=14509,title="Section 77"},
			{id=14510,title="Section 78"},
			{id=14490,title="Call of Night",body="Arcanist Tel'arn marks several players with Nightwell energy for $218809d. Marked players inflict $218838s1 Arcane damage to all players within $218838A1 yards if they are ever within $218820A1 yards of another marked player or if they aren't within $218820A1 yards of at least one unmarked player. In addition, this effect periodically summons Toxic Spores."},
			{id=14476,title="Solarist Tel'arn"},
			{id=14511,title="Section 79"},
			{id=14512,title="Section 81"},
			{id=14496,title="Summon Plasma Spheres",body="Solarist Tel'arn summons 3 Plasma Spheres that cause a Plasma Explosion upon death, creating Parasitic Lashers at its location.\n\nPlasma Spheres slowly immolate, losing $218520s1% of their maximum health every $218520t1 sec."},
			{id=14513,title="Section 80"},
			{id=14477,title="Stage Three: The Final Stand",body="As a second form falls, Tel'arns final body becomes empowered.",difficultyIDs={16}},
			{id=14478,title="Arcanist Tel'arn Final Form",difficultyIDs={16}},
			{id=14481,title="Arcanist Tel'arn",difficultyIDs={16}},
			{id=14485,title="Recursive Strikes",body="High Botanist Tel'arn inflicts $218508s1% of his melee attack damage to all players with Recursive Strikes each time he melee attacks.\n\nThis effect is applied to Tel'arn's primary target each time he melee attacks for $218503d. Each additional stack increases the damage taken from Recursive Strikes by $218508s1%.\n\nIn addition, this effect creates Plasma Spheres when it expires.",difficultyIDs={16}},
			{id=14516,title="Summon Plasma Spheres",body="Solarist Tel'arn summons 3 Plasma Spheres that cause a Plasma Explosion upon death, creating Parasitic Lashers at its location.\n\nPlasma Spheres slowly immolate, losing $218520s1% of their maximum health every $218520t1 sec.",difficultyIDs={16}},
			{id=14517,title="Section 90",difficultyIDs={16}},
			{id=14489,title="Controlled Chaos",body="High Botanist Tel'arn unleashes several explosions in quick succession at a player's location. Each explosion inflicts $218463s2 Arcane damage to all players within a $218463A2 yard radius and increases in size to a $218466A2 and $218470A2 yard radius with each successive explosion. With each explosion, several points of Solar Collapse spawn around the perimeter. In addition, each explosion inflicts $219950s1 Arcane damage to all players.",difficultyIDs={16}},
			{id=14518,title="Call of Night",body="Arcanist Tel'arn marks several players with Nightwell energy for $218809d. Marked players inflict $218838s1 Arcane damage to all players within $218838A1 yards if they are ever within $218820A1 yards of another marked player or if they aren't within $218820A1 yards of at least one unmarked player. In addition, this effect periodically summons Toxic Spores.",difficultyIDs={16}},
			{id=14479,title="Solarist Tel'arn Final Form",difficultyIDs={16}},
			{id=14482,title="Solarist Tel'arn",difficultyIDs={16}},
			{id=14484,title="Flare",body="Solarist Tel'arn blasts a player, inflicting $218806s1 Fire damage and applies Parasitic Fetter to them and all players within $218806A1 yards.",difficultyIDs={16}},
			{id=14521,title="Parasitic Fetter",body="High Botanist Tel'arn roots a random player in place, inflicting $218304s2 Nature damage every second until dispelled. This effect increases in damage by 10% each time it ticks.\n\nWhen Parasitic Fetter is removed a Controlled Chaos occurs and Parasitic Lashers are formed that pursues a random player. If the parasite reaches its target, it jumps into them and afflicts them with Parasitic Fetter.",difficultyIDs={16}},
			{id=14497,title="Summon Plasma Spheres",body="Solarist Tel'arn summons 3 Plasma Spheres that cause a Plasma Explosion upon death, creating Toxic Spores at its location.\n\nPlasma Spheres slowly immolate, losing $218520s1% of their maximum health every $218520t1 sec.",difficultyIDs={16}},
			{id=14522,title="Collapse of Night",body="Solarist Tel'arn marks several players with Nightwell energy for $218809d. Marked players inflict $218838s1 Arcane damage to all players within $218838A1 yards if they are ever within $218820A1 yards of another marked player or if they aren't within $218820A1 yards of at least one unmarked player. In addition, marked players will periodically summon a Solar Collapse at their location.",difficultyIDs={16}},
			{id=14480,title="Naturalist Tel'arn Final Form",difficultyIDs={16}},
			{id=14483,title="Naturalist Tel'arn",difficultyIDs={16}},
			{id=14519,title="Toxic Spores",body="Naturalist Tel'arn shoots $219233s1 Toxic Spores at a random player's location that persist for $219231d. If any player comes into contact with the spore it bursts, inflicting $219235s1 Nature damage to them every $219235t1 sec for $219235d. In addition a Solar Collapse occurs at the target's location when Toxic Spores is cast.",difficultyIDs={16}},
			{id=14520,title="Parasitic Fetter",body="High Botanist Tel'arn roots a random player in place, inflicting $218304s2 Nature damage every second until dispelled. This effect increases in damage by 10% each time it ticks.\n\nWhen Parasitic Fetter is removed a Parasitic Lasher is formed that pursues a random player. If the parasite reaches its target, it jumps into them and afflicts them with Parasitic Fetter.\n\nEach Parsitic Lasher is infused with Call of Night for $218809d. Infused Lashers inflict $218838s1 Arcane damage to all players within $218838A1 yards if they are ever within $218820A1 yards of another marked target or if they aren't within $218820A1 yards of at least one unmarked player.",difficultyIDs={16}},
			{id=14499,title="Section 71",difficultyIDs={16}},
		},
	},
	[1762]={
		encounterID=1762,
		instanceID=786,
		order=5,
		name="Tichondrius",
		lore="The dreadlord Tichondrius, once leader of the nathrezim, was once slain by the newly-awakened power of none other than Illidan Stormrage. Reconstituted in the Twisting Nether, Tichondrius returns to watch over Gul'dan on behalf of the Legion, ensuring that the orc warlock does not once again fail his masters.",
		dungeonEncounterID=1862,
		uiMapID=768,
		pin={x=0.265,y=0.6393},
		difficultyIDs={14,15,16,17},
		npcIDs={103685},
		displayIDs={68320},
		loot={
			{itemID=138361,diffs={},faction=-1},
