			{itemID=137758,diffs={109},faction=-1},
			{itemID=139646,diffs={109},faction=-1},
			{itemID=143566,diffs={14,15,16},faction=-1},
			{itemID=143570,diffs={14,15,16},faction=-1},
			{itemID=143576,diffs={14,15,16},faction=-1},
		},
		sections={
			{id=13504,title="Overview",body="Tichondrius wields foul carrion magic, unleashing waves of chaos and pestilence to assault the raid. \n\nAs the fight progresses, Tichondrius periodically uses |cFF2959D3|Hspell:206311|h[Illusionary Night]|h|r to trap all players in an illusion, within which they may find some respite if they can endure his |cFF2959D3|Hspell:215988|h[Carrion Nightmare]|h|r assault for $206311d."},
			{id=13893,title="Damage Dealers",body="$bullet;Carefully position to avoid spreading |cFF2959D3|Hspell:206480|h[Carrion Plague]|h|r.\n$bullet;Quickly kill Phantasmal Bloodfangs and obtain |cFF2959D3|Hspell:206466|h[Essence of Night]|h|r while trapped in the |cFF2959D3|Hspell:206365|h[Illusionary Night]|h|r.\n$bullet;Coordinate |cFF2959D3|Hspell:212795|h[Brand of Argus]|h|r detonations to avoid lethal raidwide damage.",difficultyIDs={15,16}},
			{id=13505,title="Damage Dealers",body="$bullet;Carefully position to avoid spreading |cFF2959D3|Hspell:206480|h[Carrion Plague]|h|r.\n$bullet;Quickly kill Phantasmal Bloodfangs and obtain |cFF2959D3|Hspell:206466|h[Essence of Night]|h|r while trapped in the |cFF2959D3|Hspell:206365|h[Illusionary Night]|h|r.",difficultyIDs={14,17}},
			{id=13506,title="Healers",body="$bullet;Players with |cFF2959D3|Hspell:206480|h[Carrion Plague]|h|r take sustained damage until the debuff can fade during |cFF2959D3|Hspell:206365|h[Illusionary Night]|h|r.\n$bullet;Position for and quickly dispel |cFF2959D3|Hspell:216040|h[Burning Soul]|h|r.\n$bullet;Tanks suffer significant damage from Tichondrius' nightborne allies."},
			{id=13507,title="Tanks",body="$bullet;Position nightborne and Legion minions outside of |cFF2959D3|Hspell:206893|h[Vampiric Aura]|h|r.\n$bullet;Avoid taking multiple stacks of |cFF2959D3|Hspell:208230|h[Feast of Blood]|h|r."},
			{id=13552,title="Stage One: Lord of the Nathrezim"},
			{id=13508,title="Section 5",body="$[!16\n\nIn Mythic difficulty, this effect increases the damage taken from Seeker Swarm by 1,000%.$]"},
			{id=13509,title="Section 6",body="$[!16\n\nIn Mythic difficulty, this effect only hits the player closest to Tichondrius in the path of Seeker Swarm.$]"},
			{id=13510,title="Section 7",body="$[!16\n\nIn Mythic difficulty, Flames of Argus erupt under each player that triggers Brand of Argus.$]",difficultyIDs={15,16}},
			{id=13581,title="Section 31",difficultyIDs={16}},
			{id=13512,title="Section 9"},
			{id=13511,title="Section 8"},
			{id=13583,title="Tainted Blood",body="Tainted Blood fixates the target of Feast of Blood until it is killed."},
			{id=13513,title="Section 10"},
			{id=13553,title="Stage Two: Shadow of Terror"},
			{id=13514,title="Section 11",body="$[!16\n\nIn Mythic difficulty, players without the Essence of Night when Illusionary Night ends are instantly killed.$]"},
			{id=13527,title="Section 24"},
			{id=13528,title="Phantasmal Bloodfang",body="Phantasmal Bloodfangs continuously form in the illusion at an increasing rate."},
			{id=13529,title="Section 26"},
			{id=13554,title="The Nightborne",body="When Tichondrius exits the Illusionary Night for the first time, he begins to call the Nightborne to aid him."},
			{id=13515,title="Felsworn Spellguard"},
