		sections={
			{id=13530,title="Overview",body="While fighting Shar'thos, positioning is very important. Avoid standing behind or directly in front of Shar'thos, as it will leave you vulnerable to |cFF2959D3|Hspell:215821|h[Nightmare Breath]|h|r or |cFF2959D3|Hspell:215806|h[Tail Lash]|h|r."},
			{id=13531,title="Damage Dealers",body="$bullet;Stay spread to decrease chaining damage from |cFF2959D3|Hspell:216043|h[Dread Flame]|h|r."},
			{id=13532,title="Healers",body="$bullet;Stay spread to decrease chaining damage from |cFF2959D3|Hspell:216043|h[Dread Flame]|h|r."},
			{id=13533,title="Tanks",body="$bullet;Avoid moving Shar'thos erratically to avoid exposing allies to |cFF2959D3|Hspell:215821|h[Nightmare Breath]|h|r or |cFF2959D3|Hspell:215806|h[Tail Lash]|h|r."},
