		instanceID=822,
		order=7,
		name="Levantus",
		lore="Her abyssal slumber disturbed, Levantus surfaced to find the isles teeming with strange demons. The fel magic seeping into the surrounding waters have left her in an extremely ornery mood.",
		uiMapID=449,
		pin={x=0.4351,y=0.6637},
