		sections={
			{id=13556,title="Overview",body="Levantus uses a variety of attacks that are very difficult to dodge when swimming through water. Remember to use |cFF2959D3|Hspell:217206|h[Gust of Wind]|h|r often to avoid damage!"},
			{id=13557,title="Damage Dealers",body="$bullet;Grab the water walking ability from |cFF2959D3|Hspell:217206|h[Gust of Wind]|h|r to maintain your mobility while fighting Levantus.\n$bullet;Run around Levantus while she casts |cFF2959D3|Hspell:217277|h[Massive Spout]|h|r to avoid taking massive damage."},
			{id=13558,title="Healers",body="$bullet;Grab the water walking ability from |cFF2959D3|Hspell:217206|h[Gust of Wind]|h|r to maintain your mobility while fighting Levantus.\n$bullet;Run around Levantus while she casts |cFF2959D3|Hspell:217277|h[Massive Spout]|h|r to avoid taking massive damage."},
			{id=13559,title="Tanks",body="$bullet;Swim around Levantus while she casts |cFF2959D3|Hspell:217277|h[Massive Spout]|h|r to avoid taking massive damage.\n$bullet;Try to stay in melee range as often as possible to prevent Levantus from using |cFF2959D3|Hspell:217229|h[Rampaging Torrent]|h|r."},
			{id=13607,title="Section 7"},
