	[1770]={
		encounterID=1770,
		instanceID=822,
		order=6,
		name="Humongris",
		lore="Humongris has always had the dream of wielding magic. After finding he had no aptitude in the arcane arts, Humongris instead settled for wielding a wizard. Humongris sought out and captured the mage Padawsen and now wields him as a wand, using threats of violence and a tightening grip to hurl magic around the battlefield.",
		uiMapID=449,
		pin={x=0.4277,y=0.4556},
		difficultyIDs={14,15,16,17},
		npcIDs={108879},
