			{id=13586,title="Damage Dealers",body="$bullet;Stay spread so less allies are effected by splash damage dealt by |cFF2959D3|Hspell:216429|h[Fire Boom]|h|r and |cFF2959D3|Hspell:216432|h[Ice Fist]|h|r."},
			{id=13587,title="Healers",body="$bullet;Stay spread so less allies are affected by splash damage dealt by |cFF2959D3|Hspell:216429|h[Fire Boom]|h|r and |cFF2959D3|Hspell:216432|h[Ice Fist]|h|r."},
