		instanceID=822,
		order=3,
		name="Calamir",
		lore="A being of immense magical power, Calamir was called forth by the ancient exemplars in their howling rage. Imbued with the powers of Fire, Frost, and Arcane, Calamir eradicates those who dare to stand in his way.",
		uiMapID=449,
