			{itemID=137847,diffs={43193},faction=-1},
		},
		sections={
			{id=13635,title="Overview",body="Calamir shifts between using |cFF2959D3|Hspell:217563|h[Ancient Rage: Fire]|h|r, |cFF2959D3|Hspell:217831|h[Ancient Rage: Frost]|h|r, and |cFF2959D3|Hspell:217834|h[Ancient Rage: Arcane]|h|r to pummel its foes. Be careful, as each of the schools provide very different threats!"},
			{id=13636,title="Damage Dealers",body="$bullet;Back away while Calamir casts |cFF2959D3|Hspell:217966|h[Howling Gale]|h|r to avoid taking unnecessary damage.\n$bullet;Move away from other players while afflicted with |cFF2959D3|Hspell:217877|h[Burning Bomb]|h|r to avoid blowing them up."},
			{id=13637,title="Healers",body="$bullet;Dispel players afflicted by |cFF2959D3|Hspell:217877|h[Burning Bomb]|h|r to prevent them from blowing up others.\n$bullet;Avoid |cFF2959D3|Hspell:218012|h[Arcanopulse]|h|r to not get stunned."},
			{id=13638,title="Tanks",body="$bullet;Back away while Calamir casts |cFF2959D3|Hspell:217966|h[Howling Gale]|h|r to avoid taking unnecessary damage.\n$bullet;Avoid |cFF2959D3|Hspell:218012|h[Arcanopulse]|h|r to not get stunned."},
