	[1783]={
		encounterID=1783,
		instanceID=822,
		order=9,
		name="Na'zak the Fiend",
		lore="The alpha of the Fal'dorei, this terrifying monstrosity lurks deep within the Falanaar Tunnels. As he churns through the rubble, he uncovers ley-infused stones and feeds upon their arcane energy to sustain himself, biding his time for more worthy prey.",
		uiMapID=449,
		pin={x=0.4279,y=0.462},
		difficultyIDs={14,15,16,17},
		npcIDs={110321},
		displayIDs={71534},
		loot={
			{itemID=141415,diffs={},faction=-1},
			{itemID=141488,diffs={},faction=-1},
			{itemID=141421,diffs={},faction=-1},
			{itemID=141417,diffs={},faction=-1},
			{itemID=141425,diffs={},faction=-1},
			{itemID=141515,diffs={},faction=-1},
			{itemID=141534,diffs={},faction=-1},
			{itemID=142121,diffs={43513},faction=-1},
		},
		sections={
			{id=13704,title="Overview",body="During the fight, Na'zak the Fiend shakes Ley-Infused Rubble loose from the ceiling, and begins to absorb its energy with |cFF2959D3|Hspell:219813|h[Absorb Leystones]|h|r. For each Leystone still on the ground when he finishes casting, Na'zak gains a charge of  |cFF2959D3|Hspell:219836|h[Ley Infusion]|h|r."},
			{id=13705,title="Damage Dealers",body="$bullet;Do not stand in front of the boss during |cFF2959D3|Hspell:219349|h[Corroding Spray]|h|r.\n$bullet;Collect Ley-Infused Rubble before Na'zak absorbs their energy.\n$bullet;Attack allies encased by |cFF2959D3|Hspell:219861|h[Web Wrap]|h|r to free them."},
			{id=13706,title="Tanks",body="$bullet;Face Na'zak the Fiend away from allies to avoid hitting them with |cFF2959D3|Hspell:219349|h[Corroding Spray]|h|r."},
			{id=13707,title="Healers",body="$bullet;Do not stand in front of the boss during |cFF2959D3|Hspell:219349|h[Corroding Spray]|h|r.\n$bullet;Collect Ley-Infused Rubble before Na'zak absorbs their energy.\n$bullet;Allies take massive damage during |cFF2959D3|Hspell:219836|h[Ley Infusion]|h|r"},
			{id=13708,title="Section 1"},
