		instanceID=822,
		order=4,
		name="Drugon the Frostblood",
		lore="Drugon the Frostblood has terrorized the tribes of Highmountain from atop its frozen peaks for ages. Now, seeing opportunity in the chaos, this powerful ettin descends from his perch to claim the region for himself.",
		uiMapID=449,
		pin={x=0.364,y=0.4878},
		difficultyIDs={14,15,16,17},
		npcIDs={110378},
		displayIDs={68225},
		loot={
			{itemID=141439,diffs={},faction=-1},
