		instanceID=822,
		order=0,
		name="Ana-Mouz",
		lore="This foul imp mother rests deep within Felsoul Hold, immersed in a pool of pure Fel energy. Her children swarm around her, as she soaks in the fetid air and corrupts anything that comes within her grasp.",
		uiMapID=449,
		pin={x=0.3153,y=0.6666},
