	[1795]={
		encounterID=1795,
		instanceID=822,
		order=5,
		name="Flotsam",
		lore="Flotsam emerged from the ocean depths to sate his hunger. The first to cross his path were the swamp murlocs of Shipwreck Cove, which Flotsam devoured by the dozens. Despite consuming most of their tribe, these creatures worshipped the giant as a god, and continued feeding him family and friends until the beast passed out. When he awakens, Flotsam will expand his menu to include everyone within the region.",
		uiMapID=449,
		pin={x=0.5,y=0.5},
		difficultyIDs={14,15,16,17},
		npcIDs={99929},
		displayIDs={66811},
		loot={
			{itemID=141539,diffs={},faction=-1},
			{itemID=141475,diffs={},faction=-1},
			{itemID=141544,diffs={},faction=-1},
			{itemID=141470,diffs={},faction=-1},
			{itemID=141516,diffs={},faction=-1},
			{itemID=141466,diffs={},faction=-1},
			{itemID=141476,diffs={},faction=-1},
			{itemID=139573,diffs={43985,43192},faction=-1},
		},
		sections={
			{id=13841,title="Overview",body="As the fight progresses, Flotsam hurls |cFF2959D3|Hspell:220295|h[Jetsam]|h|r at random targets. Once the boss has full energy, he uses |cFF2959D3|Hspell:220340|h[Getsam]|h|r to damage all enemies and destroys any Jetsam on the field, inflicting additional damage to nearby targets.\n\nFlotsam also uses |cFF2959D3|Hspell:223373|h[Yaksam]|h|r to summon Regurgitated Marshstompers that will fixate random targets and continually spray |cFF2959D3|Hspell:223355|h[Oozing Bile]|h|r."},
			{id=13842,title="Damage Dealers",body="$bullet;Avoid standing by |cFF2959D3|Hspell:220295|h[Jetsam]|h|r.\n$bullet;Do not stand in front of the boss during |cFF2959D3|Hspell:223373|h[Yaksam]|h|r.\n$bullet;Kill Regurgitated Marshstompers."},
			{id=13843,title="Healers",body="$bullet;Avoid standing by |cFF2959D3|Hspell:220295|h[Jetsam]|h|r.\n$bullet;Do not stand in front of the boss during |cFF2959D3|Hspell:223373|h[Yaksam]|h|r.\n$bullet;Allies take massive damage from |cFF2959D3|Hspell:220340|h[Getsam]|h|r."},
			{id=13844,title="Tanks",body="$bullet;Face Flotsam away from allies to avoid hitting them with |cFF2959D3|Hspell:223373|h[Yaksam]|h|r.\n$bullet;Move away from Flotsam during |cFF2959D3|Hspell:223317|h[Breaksam]|h|r."},
			{id=13846,title="Section 6"},
			{id=13847,title="Section 7"},
			{id=13848,title="Section 8"},
			{id=13849,title="Regurgitated Marshstomper",body="Spit up during the encounter and begin attacking random enemies."},
			{id=13850,title="Section 10"},
			{id=13851,title="Section 11"},
		},
	},
	[1796]={
		encounterID=1796,
		instanceID=822,
		order=14,
		name="Withered J'im",
		lore="Cast out from the sanctuary of Suramar, this nightfallen wandered the coastline as his body deteriorated, and his sanity along with it. Just as he was about to lose the last vestiges of personhood, he sensed a radiating energy from a nearby cave. Within, he found a shard of power originating from the Nightwell itself. It sustains and empowers him, but also warps the flow of time and space nearby. It has broken his mind completely. Now, no one enters the cave of Withered J'im. Even fools know better.",
		uiMapID=449,
		pin={x=0.4943,y=0.5317},
		difficultyIDs={14,15,16,17},
		npcIDs={112350},
		displayIDs={67466},
		loot={
			{itemID=141459,diffs={},faction=-1},
			{itemID=141492,diffs={},faction=-1},
			{itemID=141482,diffs={},faction=-1},
