			{itemID=141543,diffs={},faction=-1},
		},
		sections={
			{id=13857,title="Overview",body="Withered J'im himself is frail, but those in his presence gain Withered Presence, reducing their damage by $223599s2%. Withered J'im draws power from an Unstable Manashard nearby, creating volatile gouts of arcane energy and leverages that energy to create copies of himself."},
			{id=13858,title="Damage Dealers",body="$bullet;Avoid getting hit by |cFF2959D3|Hspell:223623|h[Nightshifted Bolts]|h|r.\n$bullet;Defeat |cFF2959D3|Hspell:223689|h[Nightstable Energy]|h|r to reduce area denial.\n$bullet;Avoid attacking J'im when he is afflicted with |cFF2959D3|Hspell:223614|h[Resonance]|h|r."},
			{id=13859,title="Healers",body="$bullet;Avoid getting hit by |cFF2959D3|Hspell:223623|h[Nightshifted Bolts]|h|r."},
			{id=13860,title="Tanks",body="$bullet;Avoid getting hit by |cFF2959D3|Hspell:223623|h[Nightshifted Bolts]|h|r.\n$bullet;Be aware, J'im's |cFF2959D3|Hspell:223614|h[Resonance]|h|r can create many additional enemies."},
			{id=13866,title="Section 9"},
			{id=13862,title="Section 6"},
			{id=13863,title="Section 7"},
			{id=13864,title="Section 11"},
			{id=14392,title="Section 9"},
		},
	},
	[1817]={
		encounterID=1817,
		instanceID=860,
		order=8,
		name="Shade of Medivh",
		lore="So great was the power of the Last Guardian, Medivh, that his magic still echoes through the halls of Karazhan. Some of these echoes take the shape of visions, revealing past events to the tower's guests. Others assume more malevolent forms, recalling a time when the Guardian's will was not his own.",
		dungeonEncounterID=1965,
		uiMapID=818,
		pin={x=0.7323,y=0.4703},
		difficultyIDs={2,8,23},
		npcIDs={114350},
		displayIDs={18718},
