		sections={
			{id=14350,title="Overview",body="Medivh assaults players with |cFF2959D3|Hspell:227628|h[Piercing Missiles]|h|r, |cFF2959D3|Hspell:227615|h[Inferno Bolt]|h|r and |cFF2959D3|Hspell:227592|h[Frostbite]|h|r until he reaches full mana. Once he has reached full mana he uses one of his Focused Power abilities.\n\nPlayers must stop all movement when |cFF2959D3|Hspell:228269|h[Flamewreath]|h|r is cast."},
			{id=14351,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:228334|h[Guardian's Image]|h|r must be killed quickly.\n$bullet;Interrupt |cFF2959D3|Hspell:227592|h[Frostbite]|h|r whenever possible."},
			{id=14352,title="Healers",body="$bullet;|cFF2959D3|Hspell:228334|h[Guardian's Image]|h|r inflicts heavy groupwide damage until all 3 images are killed."},
			{id=14353,title="Tanks",body="$bullet;|cFF2959D3|Hspell:227628|h[Piercing Missiles]|h|r inflicts significant damage to the tank."},
