	[1818]={
		encounterID=1818,
		instanceID=860,
		order=9,
		name="Mana Devourer",
		lore="Rarely does the sight of a mana wyrm cause a seasoned adventurer concern. These small, simple creatures float about, consuming stray pockets of arcane energy. But in Karazhan, tables are often turned, and what at first glance appears harmless may be revealed as an enormous threat.",
		dungeonEncounterID=1959,
		uiMapID=819,
		pin={x=0.5698,y=0.5308},
		difficultyIDs={2,8,23},
		npcIDs={114252,116802},
		displayIDs={73157},
		loot={
			{itemID=142180,diffs={},faction=-1},
			{itemID=142128,diffs={},faction=-1},
			{itemID=142215,diffs={},faction=-1},
			{itemID=142162,diffs={},faction=-1},
			{itemID=142305,diffs={},faction=-1},
			{itemID=142307,diffs={},faction=-1},
			{itemID=142150,diffs={},faction=-1},
			{itemID=142135,diffs={},faction=-1},
			{itemID=142144,diffs={},faction=-1},
		},
		sections={
			{id=13989,title="Overview",body="When threatened, the Mana Devourer attacks its enemies with a variety of area effect attacks. Periodically during combat, the Mana Devourer will |cFF2959D3|Hspell:227297|h[Coalesce Power]|h|r,expelling all of its mana as |cFF2959D3|Hspell:227296|h[Loose Unstable Mana]|h|r. Players will need to collect the |cFF2959D3|Hspell:227296|h[Loose Mana]|h|r before it reaches the Mana Devourer. After collecting the |cFF2959D3|Hspell:227502|h[Unstable Mana]|h|r, the players need to clear its stacks by standing in |cFF2959D3|Hspell:227528|h[Energy Void]|h|r. If the Mana Devourer should ever reach full mana it will cast |cFF2959D3|Hspell:227507|h[Decimating Essence]|h|r, most likely killing the entire party."},
			{id=13990,title="Damage Dealers",body="$bullet;Absorb |cFF2959D3|Hspell:227296|h[Loose Mana]|h|r before it gets to the Mana Devourer to keep the Mana Devourer from reaching full mana and casting |cFF2959D3|Hspell:227507|h[Decimating Essence]|h|r.\n$bullet;Use |cFF2959D3|Hspell:227523|h[Energy Void]|h|r to remove stacks of |cFF2959D3|Hspell:227502|h[Unstable Mana]|h|r."},
			{id=13991,title="Healer",body="$bullet;Absorb |cFF2959D3|Hspell:227296|h[Loose Mana]|h|r before it gets to the Mana Devourer to keep the Mana Devourer from reaching full mana and casting |cFF2959D3|Hspell:227507|h[Decimating Essence]|h|r.\n$bullet;Use |cFF2959D3|Hspell:227523|h[Energy Void]|h|r to remove stacks of |cFF2959D3|Hspell:227502|h[Unstable Mana]|h|r."},
			{id=13992,title="Tanks",body="$bullet;Absorb |cFF2959D3|Hspell:227296|h[Loose Mana]|h|r before it gets to the Mana Devourer to keep the Mana Devourer from reaching full mana and casting |cFF2959D3|Hspell:227507|h[Decimating Essence]|h|r.\n$bullet;Use |cFF2959D3|Hspell:227523|h[Energy Void]|h|r to remove stacks of |cFF2959D3|Hspell:227502|h[Unstable Mana]|h|r."},
			{id=13993,title="Section 5"},
			{id=13994,title="Section 6"},
			{id=13995,title="Section 7"},
