	[1819]={
		encounterID=1819,
		instanceID=861,
		order=1,
		name="Odyn",
		lore="In ages past, Odyn led the titan-forged armies against the Black Empire of the Old Gods. But for millennia he has been confined to the Halls of Valor by the curse of his bitter nemesis, Helya. Odyn seeks mortal champions to vanquish the ruler of Helheim and secure his freedom.",
		dungeonEncounterID=1958,
		uiMapID=807,
		pin={x=0.5164,y=0.8168},
		difficultyIDs={14,15,16,17},
		npcIDs={96589,114263,115323,117445,118760,119092,119893,119894},
		displayIDs={67230},
		loot={
			{itemID=142425,diffs={},faction=-1},
			{itemID=142419,diffs={},faction=-1},
			{itemID=142540,diffs={},faction=-1},
