		sections={
			{id=14045,title="Overview",body="Avoid Galindre's |cFF2959D3|Hspell:227346|h[Magic Magnificent]|h|r by using the vortices left over from Elfyra's |cFF2959D3|Hspell:227405|h[Defy Gravity]|h|r."},
			{id=14046,title="Tanks",body="$bullet;Move out of |cFF2959D3|Hspell:227410|h[Wondrous Radiance]|h|r when it appears below you."},
			{id=14047,title="Damage Dealers",body="$bullet;Kill off Winged Assistants summoned by |cFF2959D3|Hspell:227477|h[Summon Assistants]|h|r to avoid being overrun."},
			{id=14048,title="Healers",body="$bullet;Expect a spike in healing needed if the tank does not avoid |cFF2959D3|Hspell:227410|h[Wondrous Radiance]|h|r.\n$bullet;While there are Winged Assistants alive, the entire party will be taking damage and need healing."},
