	[1825]={
		encounterID=1825,
		instanceID=860,
		order=4,
		name="Maiden of Virtue",
		lore="Arriving in Karazhan to cleanse the tower of vice and corruption, the titan watcher was infuriated by Medivh's infamous parties and debaucheries. As her crusade for virtue seeks converts to her cause, the Maiden remains committed to purging immorality using all the powers at her disposal.",
		dungeonEncounterID=1954,
		uiMapID=812,
		pin={x=0.8361,y=0.5},
		difficultyIDs={2,8,23},
		npcIDs={113971},
		displayIDs={16198},
		loot={
			{itemID=142138,diffs={},faction=-1},
			{itemID=142187,diffs={},faction=-1},
			{itemID=142124,diffs={},faction=-1},
			{itemID=142158,diffs={},faction=-1},
			{itemID=142139,diffs={},faction=-1},
			{itemID=142193,diffs={},faction=-1},
			{itemID=142170,diffs={},faction=-1},
			{itemID=142153,diffs={},faction=-1},
		},
		sections={
			{id=14102,title="Overview",body="The Maiden of Virtue will place patches of |cFF2959D3|Hspell:227789|h[Sacred Ground]|h|r underneath players which will slowly expand and inflict damage to players who enter.\n\nShe will later cast |cFF2959D3|Hspell:227508|h[Mass Repentance]|h|r, which places a stun on the entire group that breaks on damage taken. She then protects herself with |cFF2959D3|Hspell:227817|h[Holy Bulwark]|h|r, which players must damage her to remove, and casts |cFF2959D3|Hspell:227823|h[Holy Wrath]|h|r, which players should interrupt after removing |cFF2959D3|Hspell:227817|h[Holy Bulwark]|h|r."},
			{id=14103,title="Tank",body="$bullet;|cFF2959D3|Hspell:227800|h[Holy Shock]|h|r will deal increasing damage if not interrupted.\n$bullet;Stand near a growing patch of |cFF2959D3|Hspell:227789|h[Sacred Ground]|h|r when Maiden of Virtue casts |cFF2959D3|Hspell:227508|h[Mass Repentance]|h|r.\n$bullet;When Maiden of Virtue is protected by |cFF2959D3|Hspell:227817|h[Holy Bulwark]|h|r, damage her to remove it and then interrupt |cFF2959D3|Hspell:227823|h[Holy Wrath]|h|r."},
			{id=14104,title="Healer",body="$bullet;|cFF2959D3|Hspell:227800|h[Holy Shock]|h|r will deal increasing damage to the tank if not interrupted.\n$bullet;Avoid standing near other players to minimize |cFF2959D3|Hspell:227809|h[Holy Bolt]|h|r chaining.\n$bullet;Stand near a growing patch of |cFF2959D3|Hspell:227789|h[Sacred Ground]|h|r when Maiden of Virtue casts |cFF2959D3|Hspell:227508|h[Mass Repentance]|h|r."},
			{id=14105,title="Damage Dealers",body="$bullet;Avoid standing near other players to minimize |cFF2959D3|Hspell:227809|h[Holy Bolt]|h|r chaining.\n$bullet;Stand near a growing patch of |cFF2959D3|Hspell:227789|h[Sacred Ground]|h|r when Maiden of Virtue casts |cFF2959D3|Hspell:227508|h[Mass Repentance]|h|r.\n$bullet;When Maiden of Virtue is protected by |cFF2959D3|Hspell:227817|h[Holy Bulwark]|h|r, damage her to remove it and then interrupt |cFF2959D3|Hspell:227823|h[Holy Wrath]|h|r."},
			{id=14106,title="Section 5"},
			{id=14107,title="Section 6"},
			{id=14108,title="Section 7"},
			{id=14109,title="Section 8"},
			{id=14110,title="Section 9"},
