		sections={
			{id=14138,title="Overview",body="Coggleston, along with the other castle servants, protects Bella and prevents any would-be interlopers from obstructing true love."},
			{id=14139,title="Damage Dealers",body="$bullet;Interrupt Luminore's |cFF2959D3|Hspell:228025|h[Heat Wave]|h|r to help the party's survivability.\n$bullet;Try not to lead Babblet through |cFF2959D3|Hspell:228200|h[Burning Blaze]|h|r to prevent her from gaining |cFF2959D3|Hspell:228225|h[Sultry Heat]|h|r.\n$bullet;Use |cFF2959D3|Hspell:228013|h[Drenched]|h|r to clear up |cFF2959D3|Hspell:228200|h[Burning Blaze]|h|r if it gets out of hand."},
			{id=14140,title="Healers",body="$bullet;Try not to lead Babblet through |cFF2959D3|Hspell:228200|h[Burning Blaze]|h|r to prevent her from gaining |cFF2959D3|Hspell:228225|h[Sultry Heat]|h|r.\n$bullet;Use |cFF2959D3|Hspell:228013|h[Drenched]|h|r to clear up |cFF2959D3|Hspell:228200|h[Burning Blaze]|h|r if it gets out of hand."},
			{id=14141,title="Tanks",body="$bullet;Be careful when Coggleston uses |cFF2959D3|Hspell:227985|h[Dent Armor]|h|r, as it can be very dangerous.\n$bullet;Interrupt Coggleston's |cFF2959D3|Hspell:227987|h[Dinner Bell!]|h|r whenever possible."},
			{id=14307,title="Section 18"},
			{id=14145,title="Luminore",body="Luminore, the noble candle keeper and light bearer, has been forced into the form of a lowly kobold by a mysterious curse."},
			{id=14146,title="Throw Flame"},
			{id=14147,title="Heat Wave"},
			{id=14148,title="Mrs. Cauldrons",body="A chef of singular talent, Mrs. Cauldrons has been terribly transformed into a simple pot by evil magics."},
			{id=14149,title="Water Bolt [NNF]"},
			{id=14177,title="Section 17"},
			{id=14150,title="Water Nova [NNF]"},
			{id=14151,title="Babblet",body="Once a head maid of striking grace, Babblet is now magically trapped in the form of a broom."},
			{id=14152,title="Dust Cloud [NNF]"},
			{id=14153,title="Burning Rush [NNF]"},
			{id=14142,title="Coggleston",body="The most loyal of castle denizens, Coggleston has been cursed into the form of a stove by an evil witch."},
