	[1829]={
		encounterID=1829,
		instanceID=861,
		order=3,
		name="Helya",
		lore="Though she once served as Odyn's right hand, the vengeful Helya will stop at nothing to ensure her ancient curse binds the titan keeper to the Halls of Valor. No longer satisfied with ruling her shadowy realm, Helya now commands her vast kvaldir army to plague the lands of the living.",
		dungeonEncounterID=2008,
		uiMapID=808,
		pin={x=0.3595,y=0.2386},
		difficultyIDs={14,15,16,17},
