	[1830]={
		encounterID=1830,
		instanceID=861,
		order=2,
		name="Guarm",
		lore="Helya's vicious three-headed hound stands guard at the gates of Helheim. Bred to require neither comfort nor sleep, Guarm remains ever-watchful for any invaders who come to challenge the reign of his cruel mistress.",
		dungeonEncounterID=1962,
		uiMapID=808,
		pin={x=0.5065,y=0.316},
		difficultyIDs={14,15,16,17},
		npcIDs={114341,114343,114344},
		displayIDs={70104},
		loot={
			{itemID=142512,diffs={},faction=-1},
			{itemID=142516,diffs={},faction=-1},
			{itemID=142426,diffs={},faction=-1},
			{itemID=142515,diffs={},faction=-1},
			{itemID=142412,diffs={},faction=-1},
			{itemID=142435,diffs={},faction=-1},
			{itemID=142434,diffs={},faction=-1},
			{itemID=142432,diffs={},faction=-1},
			{itemID=142506,diffs={},faction=-1},
			{itemID=142423,diffs={},faction=-1},
			{itemID=142417,diffs={},faction=-1},
			{itemID=142413,diffs={},faction=-1},
			{itemID=142415,diffs={},faction=-1},
			{itemID=142105,diffs={109},faction=-1},
			{itemID=142111,diffs={109},faction=-1},
		},
		sections={
			{id=14233,title="Overview",body="Guarm's |cFF2959D3|Hspell:227573|h[Guardian's Breath]|h|r unleashes three elements: Fire, Nature and Shadow. Guarm gains a stack of |cFF2959D3|Hspell:228174|h[Frothing Rage]|h|r for every player not hit by one of his breath attacks.\n\nTaking damage from |cFF2959D3|Hspell:227573|h[Guardian's Breath]|h|r will result in a debuff: |cFF2959D3|Hspell:227539|h[Fiery Phlegm]|h|r, |cFF2959D3|Hspell:227566|h[Salty Spittle]|h|r or |cFF2959D3|Hspell:227570|h[Dark Discharge]|h|r.  Gaining any two of these is deadly.\n\nPeriodically Guarm will become more mobile and aggressive, casting |cFF2959D3|Hspell:227883|h[Roaring Leap]|h|r and|cFF2959D3|Hspell:227816|h[Headlong Charge]|h|r."},
			{id=14234,title="Damage Dealers",body="$bullet;Avoid standing near allies so the effects of |cFF2959D3|Hspell:228226|h[Flame Lick]|h|r, |cFF2959D3|Hspell:228246|h[Frost Lick]|h|r and |cFF2959D3|Hspell:228250|h[Shadow Lick]|h|r are minimized.\n$bullet;When Guarm casts |cFF2959D3|Hspell:227573|h[Guardian's Breath]|h|r, stand grouped with allies within either |cFF2959D3|Hspell:227539|h[Fiery Phlegm]|h|r, |cFF2959D3|Hspell:227566|h[Salty Spittle]|h|r or |cFF2959D3|Hspell:227570|h[Dark Discharge]|h|r.  Don't mix the elements!\n$bullet;Move out of Guarm's way when he performs a |cFF2959D3|Hspell:227816|h[Headlong Charge]|h|r."},
			{id=14235,title="Healers",body="$bullet;Avoid standing near allies so the effects of |cFF2959D3|Hspell:228226|h[Flame Lick]|h|r, |cFF2959D3|Hspell:228246|h[Frost Lick]|h|r and |cFF2959D3|Hspell:228250|h[Shadow Lick]|h|r are minimized.\n$bullet;Dispel allies affected by |cFF2959D3|Hspell:228246|h[Frost Lick]|h|r.\n$bullet;When Guarm casts |cFF2959D3|Hspell:227573|h[Guardian's Breath]|h|r, stand grouped with allies within either |cFF2959D3|Hspell:227539|h[Fiery Phlegm]|h|r, |cFF2959D3|Hspell:227566|h[Salty Spittle]|h|r or |cFF2959D3|Hspell:227570|h[Dark Discharge]|h|r.  Don't mix the elements!\n$bullet;Move out of Guarm's way when he performs a |cFF2959D3|Hspell:227816|h[Headlong Charge]|h|r."},
			{id=14236,title="Tanks",body="$bullet;|cFF2959D3|Hspell:227512|h[Multi-Headed]|h|r causes Guarm's basic attacks to hit two players.  Stand next to one another!\n$bullet;Face Guarm away from your allies to avoid hitting them with |cFF2959D3|Hspell:227514|h[Flashing Fangs]|h|r.\n$bullet;When Guarm casts |cFF2959D3|Hspell:227573|h[Guardian's Breath]|h|r, stand grouped with allies within either |cFF2959D3|Hspell:227539|h[Fiery Phlegm]|h|r, |cFF2959D3|Hspell:227566|h[Salty Spittle]|h|r or |cFF2959D3|Hspell:227570|h[Dark Discharge]|h|r.  Don't mix the elements!\n$bullet;Move out of Guarm's way when he performs a |cFF2959D3|Hspell:227816|h[Headlong Charge]|h|r."},
