	[1835]={
		encounterID=1835,
		instanceID=860,
		order=5,
		name="Attumen the Huntsman",
		lore="Once charged with hunting game for his master's feasts, Attumen now sets his sights on a very different kind of quarry. Ever wary of those seeking to steal his famed steed, Midnight, Attumen unleashes his well-honed fighting skills against all intruders.",
		dungeonEncounterID=1960,
		uiMapID=809,
		pin={x=0.4532,y=0.8279},
		difficultyIDs={2,8,23},
		npcIDs={114262,114264},
		displayIDs={73160,73162},
		loot={
			{itemID=142185,diffs={},faction=-1},
			{itemID=142140,diffs={},faction=-1},
			{itemID=142183,diffs={},faction=-1},
			{itemID=142126,diffs={},faction=-1},
			{itemID=142148,diffs={},faction=-1},
			{itemID=142174,diffs={},faction=-1},
			{itemID=142136,diffs={},faction=-1},
			{itemID=142191,diffs={},faction=-1},
			{itemID=142161,diffs={},faction=-1},
			{itemID=142236,diffs={23},faction=-1},
		},
		sections={
			{id=14296,title="Overview",body="Attumen fights from the saddle until Midnight has her health reduced to 50%. At this point Midnight and Attumen will fight separately for a short while. Midnight will regain her health, then Attumen will remount and fight from the saddle once again."},
			{id=14297,title="Tanks",body="$bullet;While on foot, Attumen will constantly hit you with |cFF2959D3|Hspell:227493|h[Mortal Strike]|h|r.\n$bullet;Reposition Attumen so you and your Melee Damage Dealers can easily avoid Midnight's |cFF2959D3|Hspell:227339|h[Mezair]|h|r.\n$bullet;You will need the aid of your allies to survive |cFF2959D3|Hspell:228852|h[Shared Suffering]|h|r."},
			{id=14298,title="Damage Dealers",body="$bullet;Attumen is untargetable while riding Midnight.\n$bullet;|cFF2959D3|Hspell:227363|h[Mighty Stomp]|h|r will interrupt all spellcasting.\n$bullet;You will need to stand by your tank to help them survive |cFF2959D3|Hspell:228852|h[Shared Suffering]|h|r."},
			{id=14299,title="Healers",body="$bullet;Pay close attention to which player truly has the |cFF2959D3|Hspell:227404|h[Intangible Presence]|h|r haunting them and dispel that player.\n$bullet;|cFF2959D3|Hspell:227363|h[Mighty Stomp]|h|r will interrupt all spellcasting.\n$bullet;You will need to stand by your tank to help them survive |cFF2959D3|Hspell:228852|h[Shared Suffering]|h|r."},
			{id=14300,title="Horse and Rider as One",body="Attumen begins the fight astride his faithful steed, Midnight."},
			{id=14301,title="Section 6"},
			{id=14302,title="Section 11"},
			{id=14303,title="Section 7"},
			{id=14304,title="Fighting on Foot",body="When Midnight has her health reduced, Attumen dismounts and fights on foot until Midnight's health regenerates."},
			{id=14305,title="Section 9"},
			{id=14306,title="Section 10"},
			{id=14335,title="Section 12"},
		},
	},
	[1836]={
