		name="The Curator",
		lore="The Curator safeguards the Menagerie from unwelcome guests, terminating trespassers who seek to plunder the secrets of Karazhan. Though assembled by Medivh himself, the guardian construct has deteriorated over time, becoming prone to energy overloads and erratic behavior.",
		dungeonEncounterID=1964,
		uiMapID=817,
		pin={x=0.486,y=0.7058},
