		sections={
			{id=14318,title="Overview",body="The Curator loses mana as it casts spells to strike its foes. When it reaches 10% mana, it will cease attacking and rapidly regenerate its mana. While it does so, it is very vulnerable to player attacks."},
			{id=14319,title="Tanks",body="$bullet;The Curator targets you with |cFF2959D3|Hspell:227465|h[Power Discharge]|h|r. Place damaging area effects strategically."},
			{id=14320,title="Damage Dealers",body="$bullet;Focus fire Volatile Energy before its |cFF2959D3|Hspell:227270|h[Arc Lightning]|h|r becomes unmanageable for healers.\n$bullet;The Curator is at its most vulnerable when it casts |cFF2959D3|Hspell:227254|h[Evocation]|h|r."},
			{id=14321,title="Healers",body="$bullet;The Curator inflicts heavy damage with |cFF2959D3|Hspell:227257|h[Overload]|h|r after finishing |cFF2959D3|Hspell:227254|h[Evocation]|h|r."},
