		sections={
			{id=14355,title="Overview",body="As the fight progresses, Moroes uses |cFF2959D3|Hspell:227742|h[Garrote]|h|r to continously spread damage across the party.\n\nMoroes casts |cFF2959D3|Hspell:227872|h[Ghastly Purge]|h|r at 60% health, making all his dinner guests immune to crowd control abilities."},
			{id=14356,title="Damage Dealers",body="$bullet;Kill the additional dinner guests before Moroes uses |cFF2959D3|Hspell:227872|h[Ghastly Purge]|h|r to make them immune to stuns and bonds.\n$bullet;Use |cFF2959D3|Hspell:227909|h[Ghost Traps]|h|r on Moroes' dinner guests."},
			{id=14357,title="Healers",body="$bullet;Tanks take increased damage when effected by |cFF2959D3|Hspell:227832|h[Coat Check]|h|r.\n$bullet;Moroes uses |cFF2959D3|Hspell:227742|h[Garrote]|h|r to spread damage throughout the party.\n$bullet;Use |cFF2959D3|Hspell:227909|h[Ghost Traps]|h|r on Moroes' dinner guests."},
