		sections={
			{id=14587,title="Overview",body="Handpicked to watch over the flooded passageways, Mistress Sassz'ine stands ready to retrieve the Tidestone from those foolish enough to enter her domain."},
			{id=16187,title="Damage Dealers",body="$bullet;Slay Abyss Stalkers at the correct time to ensure that |cFF2959D3|Hspell:230959|h[Concealing Murk]|h|r is available for |cFF2959D3|Hspell:232722|h[Slicing Tornado]|h|r.\n$bullet;Stand behind |cFF2959D3|Hspell:230959|h[Concealing Murk]|h|r to prevent being struck by |cFF2959D3|Hspell:232722|h[Slicing Tornado]|h|r.\n$bullet;Bring |cFF2959D3|Hspell:232913|h[Befouling Ink]|h|r to Sarukel, The Unending Hunger when he opens his |cFF2959D3|Hspell:234621|h[Devouring Maw]|h|r.",difficultyIDs={14,15,16}},
			{id=14588,title="Damage Dealers",body="$bullet;Avoid being struck by |cFF2959D3|Hspell:232722|h[Slicing Tornado]|h|r to prevent unnecessary damage.\n$bullet;Bring |cFF2959D3|Hspell:232913|h[Befouling Ink]|h|r to Sarukel, The Unending Hunger when he opens his |cFF2959D3|Hspell:234621|h[Devouring Maw]|h|r.",difficultyIDs={17}},
			{id=16188,title="Healers",body="$bullet;Stand behind |cFF2959D3|Hspell:230959|h[Concealing Murk]|h|r to prevent being struck by |cFF2959D3|Hspell:232722|h[Slicing Tornado]|h|r.\n$bullet;Bring |cFF2959D3|Hspell:232913|h[Befouling Ink]|h|r to Sarukel, The Unending Hunger when he opens his |cFF2959D3|Hspell:234621|h[Devouring Maw]|h|r.",difficultyIDs={14,15,16}},
			{id=14589,title="Healers",body="$bullet;Avoid being struck by |cFF2959D3|Hspell:232722|h[Slicing Tornado]|h|r to prevent unnecessary damage.\n$bullet;Bring |cFF2959D3|Hspell:232913|h[Befouling Ink]|h|r to Sarukel, The Unending Hunger when he opens his |cFF2959D3|Hspell:234621|h[Devouring Maw]|h|r.",difficultyIDs={17}},
			{id=16189,title="Tanks",body="$bullet;When afflicted with |cFF2959D3|Hspell:230201|h[Burden of Pain]|h|r, attempt to minimize Physical damage taken.\n$bullet;Stand behind |cFF2959D3|Hspell:230959|h[Concealing Murk]|h|r to prevent being struck by |cFF2959D3|Hspell:232722|h[Slicing Tornado]|h|r.",difficultyIDs={14,15,16}},
			{id=14590,title="Tanks",body="$bullet;When afflicted with |cFF2959D3|Hspell:230201|h[Burden of Pain]|h|r, attempt to minimize Physical damage taken.\n$bullet;Avoid being struck by |cFF2959D3|Hspell:232722|h[Slicing Tornado]|h|r to prevent unnecessary damage.",difficultyIDs={17}},
			{id=15092,title="Delicious Bufferfish",body="Picking up a Delicious Bufferfish grants an additional $239375s1% damage dealt. Healers instead restore $239362s2 mana every $239362t2 sec. These effects increase every $t1 sec, up to 50 stacks.\n\nTaking any damage causes the Delicious Bufferfish to drop onto the ground.",difficultyIDs={16}},
			{id=15103,title="Dread Shark",body="A Dread Shark may catch the scent of a Delicious Bufferfish! It will devour the Bufferfish and all players within $239436A1 yds after $239423d.",difficultyIDs={16}},
