		sections={
			{id=14614,title="Overview",body="Goroth continuously gains fel energy until he can unleash |cFF2959D3|Hspell:233062|h[Infernal Burning]|h|r, decimating any enemy it hits. Use |cFF2959D3|Hspell:233021|h[Infernal Spikes]|h|r to survive |cFF2959D3|Hspell:233062|h[Infernal Burning]|h|r and |cFF2959D3|Hspell:233279|h[Shattering Star]|h|r.$[!16\n\nIn Mythic difficulty, Infernal Spikes explode when destroyed inflicting raid wide damage.$]"},
			{id=14618,title="Damage Dealers",body="$bullet;Hide behind |cFF2959D3|Hspell:233021|h[Infernal Spikes]|h|r to avoid being hit by |cFF2959D3|Hspell:233062|h[Infernal Burning]|h|r.\n$bullet;Avoid destroying |cFF2959D3|Hspell:233021|h[Infernal Spikes]|h|r when targeted with |cFF2959D3|Hspell:230345|h[Crashing Comet]|h|r.\n$bullet;Aim |cFF2959D3|Hspell:233279|h[Shattering Star]|h|r to collide with multiple |cFF2959D3|Hspell:233021|h[Infernal Spikes]|h|r to decrease damage taken."},
			{id=14619,title="Healers",body="$bullet;Hide behind |cFF2959D3|Hspell:233021|h[Infernal Spikes]|h|r to avoid being hit by |cFF2959D3|Hspell:233062|h[Infernal Burning]|h|r.\n$bullet;Avoid destroying |cFF2959D3|Hspell:233021|h[Infernal Spikes]|h|r when targeted with |cFF2959D3|Hspell:230345|h[Crashing Comet]|h|r.\n$bullet;Aim |cFF2959D3|Hspell:233279|h[Shattering Star]|h|r to collide with multiple |cFF2959D3|Hspell:233021|h[Infernal Spikes]|h|r to decrease damage taken."},
			{id=14620,title="Tanks",body="$bullet;Hide behind |cFF2959D3|Hspell:233021|h[Infernal Spikes]|h|r to avoid being hit by |cFF2959D3|Hspell:233062|h[Infernal Burning]|h|r.\n$bullet;Avoid destroying |cFF2959D3|Hspell:233021|h[Infernal Spikes]|h|r when affected by |cFF2959D3|Hspell:231363|h[Burning Armor]|h|r."},
			{id=14616,title="Section 3"},
			{id=15526,title="Section 14"},
			{id=14615,title="Section 2",difficultyIDs={14,15,16}},
			{id=15831,title="Section 15",difficultyIDs={17}},
			{id=14688,title="Section 9",body="$[!16\n\nIn Mythic difficulty, when an Infernal Spike is destroyed, it explodes for $233900s1 Fire damage.$]"},
			{id=14689,title="Section 10"},
			{id=14690,title="Section 11"},
			{id=14936,title="Section 11",difficultyIDs={15,16}},
