	[1867]={
		encounterID=1867,
		instanceID=875,
		order=1,
		name="Demonic Inquisition",
		lore="Anticipating the arrival of mortal forces invading the Tomb of Sargeras, Kil'jaeden has called on his best captors, Atrigan and Belac, to lock down the interlopers and prevent them from using the Pillars to advance deeper into the dungeon.",
		dungeonEncounterID=2048,
		uiMapID=850,
		pin={x=0.45,y=0.1625},
		difficultyIDs={14,15,16,17},
		npcIDs={120996},
		displayIDs={74282,74283},
		loot={
