			{id=14703,title="Section 16"},
			{id=14701,title="Section 14",difficultyIDs={15,16}},
			{id=14704,title="Section 17"},
			{id=14848,title="Section 18"},
			{id=15550,title="Tormented Soul",body="A massive soul has coalesced within Belac's cage, trapped and tormented for thousands of years.  While on the surface it is no more than a mass of ill will and pain, remnants of hope from long-forgotten prisoners remain trapped inside."},
			{id=15551,title="Section 24"},
			{id=16332,title="Section 26"},
			{id=16246,title="Section 25"},
			{id=15307,title="Tormented Fragment",body="When prisoners escape Belac's cage these fragments of the Tormented Soul abscond alongside them.",difficultyIDs={16}},
			{id=15318,title="Section 21",difficultyIDs={16}},
			{id=15319,title="Section 22",difficultyIDs={16}},
		},
	},
	[1872]={
		encounterID=1872,
		instanceID=786,
		order=9,
		name="Grand Magistrix Elisande",
		lore="Elisande once distinguished herself by resisting the Legion. She and her highborne followers broke away from Queen Azshara and the dark path she was taking, harnessing the power of the Eye of Aman'thul to create the Nightwell to protect Suramar from the Sundering. But over ten thousand years later, the Legion's arrival offered her no such recourse. She has cast her lot with the demons, hoping to once again use the power of the Nightwell - albeit this time in a very different sense - to save her people.",
		dungeonEncounterID=1872,
		uiMapID=770,
		pin={x=0.4597,y=0.4569},
		difficultyIDs={14,15,16,17},
		npcIDs={110965,211664},
		displayIDs={55131,55143,69082},
		loot={
			{itemID=138342,diffs={17},faction=-1},
			{itemID=138378,diffs={17},faction=-1},
			{itemID=140837,diffs={17},faction=-1},
			{itemID=138343,diffs={17},faction=-1},
			{itemID=140806,diffs={17},faction=-1},
			{itemID=138357,diffs={17},faction=-1},
			{itemID=140911,diffs={17},faction=-1},
			{itemID=138314,diffs={17},faction=-1},
			{itemID=138313,diffs={17},faction=-1},
