			{itemID=140910,diffs={17},faction=-1},
			{itemID=140893,diffs={17},faction=-1},
			{itemID=138332,diffs={17},faction=-1},
			{itemID=140912,diffs={17},faction=-1},
			{itemID=138356,diffs={17},faction=-1},
			{itemID=140810,diffs={17},faction=-1},
