		sections={
			{id=14759,title="Overview",body="Mephistroth uses shadow magic to attack the party until he reaches 100% energy. Once his energy is full, Mephistroth fades away and strikes at the heroes from the shadows. During this, Illidan must be protected with the Aegis of Aggramar long enough for him to pull the dreadlord back into the light.\n\n$[!23\nOn Mythic difficulty, fel bats fly in through the windows during Shadow Fade and assault the heroes with Fel Blaze.$]"},
			{id=14760,title="Damage Dealers",body="$bullet;Move away from your allies when targeted by |cFF2959D3|Hspell:233196|h[Demonic Upheaval]|h|r.\n$bullet;Defeat Shadows of Mephistroth during |cFF2959D3|Hspell:233206|h[Shadow Fade]|h|r."},
			{id=14761,title="Healers",body="$bullet;Allies take increasing damage from |cFF2959D3|Hspell:234382|h[Creeping Shadows]|h|r while Mephistroth is hidden."},
			{id=14762,title="Tanks",body="$bullet;|cFF2959D3|Hspell:233155|h[Carrion Swarm]|h|r is a heavy attack that needs to be faced away from the party.\n$bullet;During |cFF2959D3|Hspell:233206|h[Shadow Fade]|h|r, face the Aegis of Agrammar towards Shadows Orbs to protect Illidan."},
			{id=14769,title="Section 10"},
			{id=14949,title="Stage One: Mephistroth"},
			{id=14763,title="Section 5"},
			{id=14764,title="Section 6",difficultyIDs={1,2}},
