			{id=14770,title="Section 12"},
			{id=14965,title="Shadow of Mephistroth",body="Appears during Stage Two and fires Shadow Blasts at Illidan."},
			{id=14815,title="Section 14"},
			{id=15132,title="Dreadwing",body="Dreadwings fly into the room and harass the party.",difficultyIDs={23}},
			{id=15133,title="Section 17"},
