		sections={
			{id=14791,title="Overview",body="Brutallus' |cFF2959D3|Hspell:233484|h[Meteor Slash]|h|r is devastating unless its damage is shared between many enemies.\n\nAvoid taking damage from |cFF2959D3|Hspell:233519|h[Crashing Embers]|h|r, especially when affected by |cFF2959D3|Hspell:233484|h[Meteor Slash]|h|r."},
			{id=14794,title="Damage Dealers",body="$bullet;Stand near your allies when Brutallus casts |cFF2959D3|Hspell:233484|h[Meteor Slash]|h|r.\n$bullet;Avoid taking damage from |cFF2959D3|Hspell:233519|h[Crashing Embers]|h|r, especially when affected by |cFF2959D3|Hspell:233484|h[Meteor Slash]|h|r."},
			{id=14795,title="Tanks",body="$bullet;Face Brutallus toward a large group of allies when he casts |cFF2959D3|Hspell:233484|h[Meteor Slash]|h|r."},
			{id=14792,title="Healers",body="$bullet;Stand near your allies when Brutallus casts |cFF2959D3|Hspell:233484|h[Meteor Slash]|h|r.\n$bullet;Prioritize allies affected by |cFF2959D3|Hspell:233484|h[Meteor Slash]|h|r for heavy healing if they are affected by |cFF2959D3|Hspell:233519|h[Crashing Embers]|h|r."},
