	[1896]={
		encounterID=1896,
		instanceID=875,
		order=6,
		name="The Desolate Host",
		lore="Once, this was a sacred burial site for the Night Elves, but the Legion has twisted these grounds with the Engine of Souls. This foul machine draws upon the energy of the dead, twisting them into abominations. Due to this corruption, these tormented spirits have become monstrosities, looking to feed on any who descend into the tomb's depths.",
