	[1897]={
		encounterID=1897,
		instanceID=875,
		order=7,
		name="Maiden of Vigilance",
		lore="Charged by Aegwynn to defend the Tomb of Sargeras, the Maiden of Vigilance has stood watch for hundreds of years. Yet, the guardian did not forsee what effect the avatar's seeping fel energy would have on this titan construct. Slowly warped by this maleficence, the Maiden now seeks to destroy any in her path.",
