	[1898]={
		encounterID=1898,
		instanceID=875,
		order=9,
		name="Kil'jaeden",
		lore="Since striking the bargain that chased the draenei into the stars, Kil'jaeden believed the Legion could not be stopped. Yet, none of his deceptions have prevented you from reaching this critical moment. Infuriated that Sargeras' promise of victory has never come to pass, the demon lord prepares to face you himself, for a final battle that will shape Azeroth's destiny forever.",
		dungeonEncounterID=2051,
		uiMapID=856,
		pin={x=0.7279,y=0.4458},
		difficultyIDs={14,15,16,17},
		npcIDs={117269,121609},
