	[1903]={
		encounterID=1903,
		instanceID=875,
		order=4,
		name="Sisters of the Moon",
		lore="The Sisters of the Moon served as wardens for the temple long before the avatar of Sargeras was buried beneath it. Even in death, the sisters maintained their vigil, but over the millennia something twisted their ability to distinguish friend from foe. Their madness slowly consumed them, and now any who enter their sacred chambers are put to death.",
		dungeonEncounterID=2050,
		uiMapID=852,
		pin={x=0.519,y=0.5725},
		difficultyIDs={14,15,16,17},
		npcIDs={118374,118518,118523,121498},
		displayIDs={74748,74775,74874,75101},
		loot={
			{itemID=147068,diffs={},faction=-1},
