	[1904]={
		encounterID=1904,
		instanceID=900,
		order=3,
		name="Domatrax",
		lore="With the Aegis of Aggramar socketed back into its cradle, Domatrax leads an onslaught of demons to destroy the relic.",
		dungeonEncounterID=2053,
		uiMapID=849,
		pin={x=0.523,y=0.4635},
		difficultyIDs={2,8,23},
		npcIDs={119542},
		displayIDs={76609},
		loot={
			{itemID=144475,diffs={},faction=-1},
			{itemID=144495,diffs={},faction=-1},
			{itemID=144466,diffs={},faction=-1},
