			{itemID=144488,diffs={},faction=-1},
			{itemID=144474,diffs={},faction=-1},
		},
		sections={
			{id=15007,title="Overview",body="Upon reaching 90% and 50% health, the Fel Lord opens up additonal portals to allow greater numbers of the Legion's soldiers to pour into the tomb.\n\nThe Aegis of Aggramar provides protection against the Legion's attacks, but if drained of all its energy, this aura will fall.\n\n$[!23\nOn Mythic difficulty,  if the Fel Portal Guardians are not destroyed within a specific time, an overfiend emerges.$]"},
			{id=15353,title="Damage Dealers",body="$bullet;Destroy Fel Portal Guardians to stop the flow of demons.",difficultyIDs={1,2}},
			{id=15008,title="Damage Dealers",body="$bullet;Destroy Fel Portal Guardians before they can complete |cFF2959D3|Hspell:241622|h[Approaching Doom]|h|r.",difficultyIDs={23}},
			{id=15009,title="Healers",body="$bullet;The Aegis' protection aura reduces damage from |cFF2959D3|Hspell:234107|h[Choatic Energy]|h|r."},
			{id=15010,title="Tanks",body="$bullet;Turn the Fel Lord away from the party and the Aegis to avoid having them get hit with |cFF2959D3|Hspell:236543|h[Felsoul Cleave]|h|r.\n$bullet;At 25% health, Domatrax goes into a |cFF2959D3|Hspell:243157|h[Frenzy]|h|r."},
			{id=15011,title="Domatrax",body="This Fel Lord leads the onslaught against the Aegis of Aggramar."},
			{id=15012,title="Section 6"},
			{id=15013,title="Section 7"},
			{id=15549,title="Section 27"},
			{id=15076,title="Fel Portal Guardian",body="Defeat these guardians to close their portals and prevent additional demons from entering the battle."},
			{id=15352,title="Section 25",difficultyIDs={23}},
			{id=15349,title="Searing Overfiend",difficultyIDs={23}},
			{id=15350,title="Section 24",difficultyIDs={23}},
			{id=15098,title="Section 22"},
			{id=15014,title="Stage One: The March of the Imps",body="Upon reaching 90% health, Domatrax tears open portals allowing imps to enter the fray."},
			{id=15015,title="Hellblaze Imp"},
			{id=15016,title="Section 9"},
			{id=15018,title="Stage Two: The Burning Hordes",body="Upon reaching 50% health, Domatrax tears open portals summoning felguard into the battle.\n$[!23\nOn Mythic difficulty,  shivan emerge from the portals.$]"},
			{id=15017,title="Hellblaze Felguard",difficultyIDs={1,2}},
