	[1905]={
		encounterID=1905,
		instanceID=900,
		order=1,
		name="Agronox",
		lore="This ancient served the night elves priestesses of the Temple of Elune, tending the beautiful Hanging Gardens. But after the malevolence of the Legion infected the Cathedral, the guardian absorbed fel energy through his roots. Now the twisted Agronox spreads corruption throughout the sanctuary he once protected, believing he has finally achieved his ideal state.",
		dungeonEncounterID=2055,
		uiMapID=846,
		pin={x=0.5527,y=0.4391},
		difficultyIDs={2,8,23},
		npcIDs={117193},
		displayIDs={74482},
