		sections={
			{id=15028,title="Overview",body="Agronox corrupts the garden he once tended and turns it against players. Quickly defeat his Lasher minions to avoid being overwhelmed.\n\nRun from |cFF2959D3|Hspell:236650|h[Choking Vines]|h|r before you are strangled. |cFF2959D3|Hspell:236524|h[Poisonous Spores]|h|r inflict increasing amounts of damage over time.\n$[!23\nOn Mythic difficulty, Agronox summons Nourishing Lashers and restores his health via |cFF2959D3|Hspell:242199|h[Nature's Infusion]|h|r.$]"},
			{id=15552,title="Damage Dealers",body="$bullet;Defeat Fulminating Lashers and Succulent Lashers quickly, to keep the party from being overrun.\n$bullet;Avoid standing too close to allies when |cFF2959D3|Hspell:236627|h[Floral Fulmination]|h|r is imminent.",difficultyIDs={1,2}},
			{id=15029,title="Damage Dealers",body="$bullet;Defeat Fulminating Lashers and Succulent Lashers quickly, to keep the party from being overrun.\n$bullet;Avoid standing too close to allies when |cFF2959D3|Hspell:236627|h[Floral Fulmination]|h|r is imminent.",difficultyIDs={23}},
			{id=15030,title="Healers",body="$bullet;Players struck by |cFF2959D3|Hspell:236627|h[Floral Fulmination]|h|r take significant damage.\n$bullet;Avoid standing too close to allies when |cFF2959D3|Hspell:236627|h[Floral Fulmination]|h|r is imminent."},
			{id=15553,title="Tanks",body="$bullet;Position Succulent Lashers such that |cFF2959D3|Hspell:236640|h[Toxic Sap]|h|r can be avoided by party members.\n$bullet;Defeat Fulminating Lashers and Succulent Lashers quickly, to keep the party from being overrun.",difficultyIDs={1,2}},
			{id=15031,title="Tanks",body="$bullet;Position Succulent Lashers such that |cFF2959D3|Hspell:236640|h[Toxic Sap]|h|r can be avoided by party members.\n$bullet;Defeat Fulminating Lashers and Succulent Lashers quickly, to keep the party from being overrun.",difficultyIDs={23}},
			{id=15081,title="Section 6"},
			{id=15082,title="Section 5"},
			{id=15083,title="Section 7"},
			{id=15084,title="Fulminating Lashers",body="Agronox calls forth a swarm of explosive Fulminating Lashers from the dense fauna of the Fel Gardens."},
			{id=15093,title="Section 10"},
			{id=15085,title="Succulent Lashers",body="Dripping with toxins, Succulent Lashers spring from the grounds of the Fel Garden at Agronox's command.",difficultyIDs={23}},
			{id=15094,title="Section 11",difficultyIDs={23}},
		},
	},
	[1906]={
