		instanceID=900,
		order=2,
		name="Thrashbite the Scornful",
		lore="Smashspite's detestable brother, Thrashbite, has been dispatched to wipe out the mortals entering the cathedral's grand library. The dimwitted mo'arg lacks any respect for knowledge or learning, feeling petty satisfaction as he crashes through ancient artifacts and tramples priceless tomes.",
		dungeonEncounterID=2057,
		uiMapID=847,
		pin={x=0.5243,y=0.5852},
		difficultyIDs={2,8,23},
		npcIDs={117194},
