		sections={
			{id=15032,title="Overview",body="Thrashbite the Scornful favors imprecise, sweeping attacks with little regard for his surroundings. Trick him into going toe to toe with something thicker than himself, though, and he just might lose his balance.  Beware: this ancient library contains many magical tomes with unpredictable enchantments!\n$[!23\nOn Mythic difficulty, Thrashbite unleashes the powers of the Wondrous Library each time he collides with a bookcase, bringing ancient animated tomes into the fray.\n$]"},
			{id=15033,title="Damage Dealers",body="$bullet;Move as far from Thrashbite as possible when he performs |cFF2959D3|Hspell:237276|h[Pulverizing Cudgel]|h|r.\n$bullet;Avoid Thrashbite's path during |cFF2959D3|Hspell:237891|h[Scornful Charge]|h|r.\n$bullet;Take cover when Thrashbite uses |cFF2959D3|Hspell:243153|h[Heave Cudgel]|h|r!"},
			{id=15034,title="Healers",body="$bullet;Move as far from Thrashbite as possible when he performs |cFF2959D3|Hspell:237276|h[Pulverizing Cudgel]|h|r.\n$bullet;Avoid Thrashbite's path during |cFF2959D3|Hspell:237891|h[Scornful Charge]|h|r.\n$bullet;Take cover when Thrashbite uses |cFF2959D3|Hspell:243153|h[Heave Cudgel]|h|r!"},
			{id=15035,title="Tanks",body="$bullet;Move as far from Thrashbite as possible when he performs |cFF2959D3|Hspell:237276|h[Pulverizing Cudgel]|h|r.\n$bullet;Avoid Thrashbite's path during |cFF2959D3|Hspell:237891|h[Scornful Charge]|h|r.\n$bullet;Take cover when Thrashbite uses |cFF2959D3|Hspell:243153|h[Heave Cudgel]|h|r!"},
			{id=15067,title="Section 5"},
			{id=15068,title="Section 6"},
			{id=15069,title="Section 7"},
