			{id=15466,title="Satirical Animated Book",body="An animated, magical tome overflowing with stiflingly satirical writing.",difficultyIDs={23}},
			{id=15467,title="Section 12",difficultyIDs={23}},
			{id=15468,title="Section 15",difficultyIDs={23}},
			{id=15469,title="Fictional Animated Book",body="An ancient work of fiction springs to life, the magical runes leaping from the page to fetter would-be readers.",difficultyIDs={23}},
