		sections={
			{id=15861,title="Overview",body="Zuraal uses the void to empower himself and injure his opponents. |cFF2959D3|Hspell:244579|h[Decimate]|h|r creates pools of damaging void energy, while |cFF2959D3|Hspell:244602|h[Coalesced Void]|h|r triggers a devastating |cFF2959D3|Hspell:244599|h[Dark Expulsion]|h|r when it reaches Zuraal."},
			{id=15862,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:1263399|h[Oozing Slam]|h|r causes |cFF2959D3|Hspell:244602|h[Coalesced Void]|h|r to spawn, which erupts in a |cFF2959D3|Hspell:244599|h[Dark Expulsion]|h|r when they reach Zuraal.\n$bullet; |cFF2959D3|Hspell:244579|h[Decimate]|h|r leaves behind |cFF2959D3|Hspell:244588|h[Void Sludge]|h|r in its impact area."},
			{id=15863,title="Healers",body="$bullet; |cFF2959D3|Hspell:1263399|h[Oozing Slam]|h|r causes |cFF2959D3|Hspell:244602|h[Coalesced Void]|h|r to spawn, which erupts in a |cFF2959D3|Hspell:244599|h[Dark Expulsion]|h|r when they reach Zuraal.\n$bullet; |cFF2959D3|Hspell:244579|h[Decimate]|h|r leaves behind |cFF2959D3|Hspell:244588|h[Void Sludge]|h|r in its impact area."},
			{id=15864,title="Tanks",body="$bullet; |cFF2959D3|Hspell:1263440|h[Void Slash]|h|r inflicts heavy Physical and Shadow damage.\n$bullet; |cFF2959D3|Hspell:1263399|h[Oozing Slam]|h|r causes |cFF2959D3|Hspell:244602|h[Coalesced Void]|h|r to spawn, which erupts in a |cFF2959D3|Hspell:244599|h[Dark Expulsion]|h|r when they reach Zuraal."},
