	[1980]={
		encounterID=1980,
		instanceID=945,
		order=2,
		name="Saprish",
		lore="The ever-tactical Saprish deploys the forces of the Shadowguard with calculated precision. Though a skilled commander and strategist, Saprish relishes taking a direct hand in battle. He turns his foes' weaknesses against them, leaving his vulnerable adversaries at the mercy of his voracious pets.",
