		sections={
			{id=16066,title="Overview",body="Saprish cover the battlefield with |cFF2959D3|Hspell:246026|h[Void Bombs]|h|r and rushes players with |cFF2959D3|Hspell:1263516|h[Phase Dash]|h|r.\n\nAt 100 energy, Saprish casts |cFF2959D3|Hspell:1263526|h[Overload]|h|r that ignites all |cFF2959D3|Hspell:246026|h[Void Bombs]|h|r."},
			{id=16067,title="Damage Dealers",body="$bullet; Saprish's |cFF2959D3|Hspell:1263518|h[Phase Dash]|h|r causes an |cFF2959D3|Hspell:1263508|h[Umbral Nova]|h|r when dashing through a |cFF2959D3|Hspell:246026|h[Void Bomb]|h|r.\n$bullet; |cFF2959D3|Hspell:1263526|h[Overload]|h|r causes all the |cFF2959D3|Hspell:246026|h[Void Bombs]|h|r to explode, afflicting all players with |cFF2959D3|Hspell:1268840|h[Seeping Void]|h|r."},
			{id=16068,title="Healers",body="$bullet; Saprish's |cFF2959D3|Hspell:1263518|h[Phase Dash]|h|r causes an |cFF2959D3|Hspell:1263508|h[Umbral Nova]|h|r when dashing through a |cFF2959D3|Hspell:246026|h[Void Bomb]|h|r.\n$bullet; |cFF2959D3|Hspell:1263526|h[Overload]|h|r causes all the |cFF2959D3|Hspell:246026|h[Void Bombs]|h|r to explode, afflicting all players with |cFF2959D3|Hspell:1268840|h[Seeping Void]|h|r."},
			{id=16069,title="Tanks",body="$bullet; |cFF2959D3|Hspell:1266449|h[Rending Void]|h|r inflicts Shadow damage on all melee strikes.\n$bullet; |cFF2959D3|Hspell:1263526|h[Overload]|h|r causes all the |cFF2959D3|Hspell:246026|h[Void Bombs]|h|r to explode, afflicting all players with |cFF2959D3|Hspell:1268840|h[Seeping Void]|h|r."},
