	[1981]={
		encounterID=1981,
		instanceID=945,
		order=3,
		name="Viceroy Nezhar",
		lore="Like others of his ilk, Viceroy Nezhar is obsessed with harnessing the power of the Void to serve his own ambitions. Drawn to the Seat of the Triumvirate by the immense darkness emanating from deep within, Nezhar will stop at nothing to claim it for his own.\n\nGiven the viceroy's experiments at infusing vessels with the power of shadow, the implications of what he might accomplish on Argus are dire indeed.",
