		sections={
			{id=15825,title="Overview",body="Varimathras uses the darkness of his cell to stalk his prey, attacking them with |cFF2959D3|Hspell:243963|h[Alone in the Darkness]|h|r."},
			{id=16376,title="Damage Dealers",body="$bullet;Position |cFF2959D3|Hspell:244042|h[Marked Prey]|h|r to avoid being knocked out of range of your allies.\n$bullet;Quickly move out of |cFF2959D3|Hspell:243999|h[Dark Fissure]|h|r.",difficultyIDs={14,17}},
			{id=15775,title="Damage Dealers",body="$bullet;Position |cFF2959D3|Hspell:244042|h[Marked Prey]|h|r to avoid being knocked out of range of your allies.\n$bullet;Avoid spreading |cFF2959D3|Hspell:244093|h[Necrotic Embrace]|h|r to multiple allies.",difficultyIDs={15,16}},
			{id=15776,title="Healers",body="$bullet;Torments of the Shivarra inflict constant raid wide damage.",difficultyIDs={17}},
			{id=16374,title="Healers",body="$bullet;Players who suffer any Shadow damage are afflicted with |cFF2959D3|Hspell:243961|h[Misery]|h|r and cannot be healed for $243961d.\n$bullet;Torments of the Shivarra inflict constant raid wide damage.",difficultyIDs={14,15,16}},
			{id=15777,title="Tanks",body="$bullet;Avoid being hit by |cFF2959D3|Hspell:243960|h[Shadow Strike]|h|r while not tanking.",difficultyIDs={17}},
			{id=16375,title="Tanks",body="$bullet;|cFF2959D3|Hspell:243961|h[Misery]|h|r prevents all healing received and increases Physical damage taken for $243961d.\n$bullet;Avoid being hit by |cFF2959D3|Hspell:243960|h[Shadow Strike]|h|r while not tanking.",difficultyIDs={14,15,16}},
			{id=15778,title="Torments of the Shivarra",body="The Coven of Shivarra designed Varimathras' cell to torture him for all time."},
