	[1984]={
		encounterID=1984,
		instanceID=946,
		order=9,
		name="Aggramar",
		lore="Once the noble Avenger of the Pantheon, Aggramar was struck down by Sargeras and reborn as a titan of destruction. He now stands at the core of Argus, guarding a power that could unmake the universe.\n\nNot even demons are permitted to tread within the titan's halls, and any mortals bold enough to trespass will be reduced to cinders by Aggramar's burning blade, Taeshalach.",
		dungeonEncounterID=2063,
		uiMapID=917,
		pin={x=0.2419,y=0.5403},
