	[1985]={
		encounterID=1985,
		instanceID=946,
		order=4,
		name="Portal Keeper Hasabel",
		lore="Portal Keeper Hasabel maintains the nexus through which the Legion has unleashed its insidious armies upon countless worlds. With portals that open to a myriad of strategic locations throughout the Great Dark Beyond, Hasabel is capable of bringing the might of the Legion's arsenal to bear upon any who oppose her.",
		dungeonEncounterID=2064,
		uiMapID=911,
		pin={x=0.4355,y=0.5113},
		difficultyIDs={14,15,16,17},
		npcIDs={122104},
		displayIDs={78229},
		loot={
			{itemID=151941,diffs={},faction=-1},
			{itemID=152020,diffs={},faction=-1},
			{itemID=151945,diffs={},faction=-1},
