			{itemID=151965,diffs={},faction=-1},
			{itemID=151958,diffs={},faction=-1},
			{itemID=152086,diffs={},faction=-1},
			{itemID=152035,diffs={},faction=-1},
			{itemID=152008,diffs={},faction=-1},
			{itemID=152049,diffs={},faction=-1},
			{itemID=152057,diffs={},faction=-1},
			{itemID=151748,diffs={109},faction=-1},
			{itemID=208050,diffs={77183,109},faction=-1},
			{itemID=213014,diffs={79455,109},faction=-1},
		},
		sections={
			{id=15803,title="Overview",body="Portal Keeper Hasabel commands the portal nexus for the Burning Legion, transporting demons to and from the frontlines.\n\nAt 90% health remaining, Hasabel opens a fiery portal to Xoroth to burn her enemies. Vulcanar arrives through the portal and empowers it until his death.\n\nAt 60% health remaining, Hasabel opens a fel portal to Rancora to liquify her enemies. Lady Dacidion arrives through the portal and empowers it until her death.\n\nAt 30% health remaining, Hasabel opens a shadow portal to Nathreza to confuse the minds of her enemies. Lord Eilgar arrives through the portal and empowers it until his death."},
			{id=16157,title="Damage Dealers",body="$bullet;Move away from |cFF2959D3|Hspell:243983|h[Collapsing World]|h|r to prevent being knocked off the platforms.\n$bullet;Interrupt and slay demons pouring forth from the |cFF2959D3|Hspell:244677|h[Transport Portal]|h|r when it is opened.",difficultyIDs={14,15,17}},
			{id=15796,title="Damage Dealers",body="$bullet;Utilize the essence of the demon homeworlds, such as |cFF2959D3|Hspell:245157|h[Everburning Light]|h|r, |cFF2959D3|Hspell:244853|h[Caustic Detonation]|h|r, and |cFF2959D3|Hspell:245075|h[Hungering Gloom]|h|r to combat each of the other homeworld's properties. \n$bullet;Interrupt and slay demons pouring forth from the |cFF2959D3|Hspell:244677|h[Transport Portal]|h|r when it is opened.",difficultyIDs={16}},
			{id=16158,title="Healers",body="$bullet;Allies will suffer high damage when |cFF2959D3|Hspell:244016|h[Reality Tear]|h|r expires.\n$bullet;Players within |cFF2959D3|Hspell:245240|h[Oppressive Gloom]|h|r cannot be healed unless they are near an |cFF2959D3|Hspell:245157|h[Everburning Light]|h|r.",difficultyIDs={16}},
			{id=15797,title="Healers",body="$bullet;Allies will suffer high damage when |cFF2959D3|Hspell:244016|h[Reality Tear]|h|r expires.\n$bullet;Move away from |cFF2959D3|Hspell:243983|h[Collapsing World]|h|r to prevent being knocked off the platforms.",difficultyIDs={14,15,17}},
			{id=15798,title="Tanks",body="$bullet;Manage applications of |cFF2959D3|Hspell:244016|h[Reality Tear]|h|r to reduce the damage from |cFF2959D3|Hspell:244021|h[Bursting Darkness]|h|r.\n$bullet;Interrupt demons pouring forth from the |cFF2959D3|Hspell:244677|h[Transport Portal]|h|r when it is opened.\n$bullet;Move away from |cFF2959D3|Hspell:243983|h[Collapsing World]|h|r to prevent being knocked off the platforms."},
			{id=15799,title="Platform: Nexus",body="A central platform that connects Legion portals."},
