	[1986]={
		encounterID=1986,
		instanceID=946,
		order=8,
		name="The Coven of Shivarra",
		lore="Having proven themselves to be the most depraved and fanatical of all his followers, Sargeras entrusted the Coven with the unholy task of twisting the minds of the fallen titans into an unstoppable Dark Pantheon.\n\nEach sister employs her own signature brand of torture, eliciting screams which echo throughout the halls of Antorus. It is said that neither mortal nor demon can refuse their whispers, making it only a matter of time before the will of the titans is broken.",
		dungeonEncounterID=2073,
		uiMapID=915,
		pin={x=0.3215,y=0.5274},
		difficultyIDs={14,15,16,17},
		npcIDs={123597,123598,123599},
