	[1987]={
		encounterID=1987,
		instanceID=946,
		order=2,
		name="Felhounds of Sargeras",
		lore="Infused with fire and shadow, F'harg and Shatug are the prized pets of Sargeras. Bred for carnage, these hounds delight in eviscerating their master's enemies.\n\nWith the Army of the Light and their allies advancing upon Antorus, the Legion prepares to unleash these vicious creatures onto the battlefield and put an end to the mortals' invasion.",
		dungeonEncounterID=2074,
		uiMapID=909,
		pin={x=0.4129,y=0.5355},
		difficultyIDs={14,15,16,17},
		npcIDs={122135,122477},
