		sections={
			{id=15832,title="Overview",body="The Felhounds of Sargeras combat players while performing attacks at specific power thresholds, but each has their own power generation rate. |cFF2959D3|Hspell:251356|h[Focusing Power]|h|r temporarily suspends this power generation.\n\nWhile within $244050s1 yards of each other, |cFF2959D3|Hspell:246057|h[Sargeras' Blessing]|h|r imbues them with $244050s4% increased damage."},
			{id=16558,title="Damage Dealers",body="$bullet;Be aware of targets afflicted with |cFF2959D3|Hspell:244768|h[Desolate Gaze]|h|r, as it inflicts damage from F'harg to the targets' direction.",difficultyIDs={17}},
			{id=16928,title="Damage Dealers",body="$bullet;Be aware of targets afflicted with |cFF2959D3|Hspell:244768|h[Desolate Gaze]|h|r, as it inflicts damage from F'harg to the targets' direction.\n$bullet;Avoid standing in front of F'harg and Shatug because of |cFF2959D3|Hspell:2547477|h[Burning Maw]|h|r and |cFF2959D3|Hspell:254760|h[Corrupting Maw]|h|r.",difficultyIDs={14}},
			{id=15833,title="Damage Dealers",body="$bullet;Be aware of targets afflicted with |cFF2959D3|Hspell:244768|h[Desolate Gaze]|h|r, as it inflicts damage from F'harg to the targets' direction.\n$bullet;Help players afflicted with |cFF2959D3|Hspell:244071|h[Weight of Darkness]|h|r as the duration divides amongst nearby targets.\n$bullet;Assist players afflicted with |cFF2959D3|Hspell:248819|h[Siphoned]|h|r during |cFF2959D3|Hspell:244056|h[Siphon Corruption]|h|r, and avoid players afflicted with |cFF2959D3|Hspell:248815|h[Enflamed]|h|r during |cFF2959D3|Hspell:244057|h[Enflame Corruption]|h|r.",difficultyIDs={15,16}},
			{id=16559,title="Healers",body="$bullet;Be aware of targets afflicted with |cFF2959D3|Hspell:244768|h[Desolate Gaze]|h|r, as it inflicts damage from F'harg to the targets' direction.\n$bullet;Pay attention when a Felhound reaches 100 power, as |cFF2959D3|Hspell:257236|h[Erupting Flames]|h|r and |cFF2959D3|Hspell:257238|h[Erupting Shadows]|h|r inflict sustained raid-wide damage.",difficultyIDs={17}},
			{id=16929,title="Healers",body="$bullet;Be aware of targets afflicted with |cFF2959D3|Hspell:244768|h[Desolate Gaze]|h|r, as it inflicts damage from F'harg to the targets' direction.\n$bullet;Assist players afflicted with |cFF2959D3|Hspell:248819|h[Siphoned]|h|r during |cFF2959D3|Hspell:244056|h[Siphon Corruption]|h|r, and avoid players afflicted with |cFF2959D3|Hspell:248815|h[Enflamed]|h|r during |cFF2959D3|Hspell:244057|h[Enflame Corruption]|h|r.",difficultyIDs={14}},
			{id=15834,title="Healers",body="$bullet;Be aware of targets afflicted with |cFF2959D3|Hspell:244768|h[Desolate Gaze]|h|r, as it inflicts damage from F'harg to the targets' direction.\n$bullet;|cFF2959D3|Hspell:244086|h[Molten Touch]|h|r targets take high amounts of Fire damage through |cFF2959D3|Hspell:244091|h[Singed]|h|r in a short period of time.\n$bullet;Assist players afflicted with |cFF2959D3|Hspell:248819|h[Siphoned]|h|r during |cFF2959D3|Hspell:244056|h[Siphon Corruption]|h|r, and avoid players afflicted with |cFF2959D3|Hspell:248815|h[Enflamed]|h|r during |cFF2959D3|Hspell:244057|h[Enflame Corruption]|h|r.",difficultyIDs={15,16}},
			{id=15835,title="Tanks",body="$bullet;Be aware of targets afflicted with |cFF2959D3|Hspell:244768|h[Desolate Gaze]|h|r, as it inflicts damage from F'harg to the targets' direction.\n$bullet;Watch for the |cFF2959D3|Hspell:251448|h[Burning Maw]|h|r or |cFF2959D3|Hspell:251447|h[Corrupting Maw]|h|r auras, as they indicate that the targeted boss can cast the aforementioned ability."},
			{id=15842,title="F'harg"},
