	[1992]={
		encounterID=1992,
		instanceID=946,
		order=1,
		name="Garothi Worldbreaker",
		lore="Constructed deep within the core of Argus and outfitted with an arsenal capable of decimating worlds, this war machine has been designed for a single purpose: to bring the mortals' invasion to its knees.",
		dungeonEncounterID=2076,
		uiMapID=909,
		pin={x=0.7276,y=0.5874},
		difficultyIDs={14,15,16,17},
		npcIDs={122450,123371},
		displayIDs={76534},
		loot={
			{itemID=152009,diffs={},faction=-1},
			{itemID=152031,diffs={},faction=-1},
			{itemID=152039,diffs={},faction=-1},
