	[1997]={
		encounterID=1997,
		instanceID=946,
		order=3,
		name="Antoran High Command",
		lore="Long ago in the golden age of eredar civilization, a council was formed to oversee the defense of Argus and maintain peace. But after their dark bargain was struck with Sargeras, these master tacticians used their military expertise to help orchestrate a Burning Crusade that ravaged countless worlds.\n\nNow the full might of the Legion's army is theirs to command, and they wield this terrible power to annihilate all who oppose the Dark Titan's will.",
		dungeonEncounterID=2070,
		uiMapID=910,
		pin={x=0.4118,y=0.4661},
		difficultyIDs={14,15,16,17},
		npcIDs={122084,126258},
		displayIDs={76921,76922,78817},
		loot={
