			{id=16535,title="Section 37"},
			{id=16098,title="Out of Pod",body="While out of their command pod, each commander fights their enemies more directly using a shared set of attacks."},
			{id=16134,title="Section 33"},
			{id=16586,title="Section 23"},
			{id=16132,title="Section 21",difficultyIDs={16}},
			{id=16122,title="Section 21",difficultyIDs={16}},
			{id=16125,title="Stealing Power",body="While a commander is out of their pod and attacking directly, players can commandeer the pod and use its powerful abilities. This causes the player to suffer a |cFF2959D3|Hspell:244172|h[Psychic Assault]|h|r, which will eventually overwhelm and kill the player for meddling with powers beyond their station."},
