	[2009]={
		encounterID=2009,
		instanceID=946,
		order=6,
		name="Imonar the Soulhunter",
		lore="The infamous Imonar serves as the Legion's bloodhound, capable of tracking prey across the cosmos. With a vast array of gadgets and traps at his disposal, Imonar has yet to lose a bounty... and he certainly doesn't intend to sully his perfect record by failing to fulfil his latest contract.",
