		sections={
			{id=16200,title="Overview",body="Imonar the Soulhunter is called forth by the Legion to hunt down and capture high priority targets. He starts out utilizing controlling and suppressing effects to defeat his enemies. \n\nAt $247651s1% health remaining, Imonar backs up to a secondary platform, dropping several traps along the way. He then begins to use more lethal effects on enemies, calling in Legion ships to assist him.\n\nAt $247653s1% health remaining, Imonar leaps back to the primary platform, once more planting traps along the way. His weapons are now empowered and fully operational.$]$[!16\n\nIn Mythic difficulty, these transitions occur every time Imonar loses 20% of his maximum health.$]"},
			{id=16201,title="Damage Dealers",body="$bullet;Interrupt |cFF2959D3|Hspell:248321|h[Conflagration]|h|r when the raid has safely arrived on the correct platform to prevent |cFF2959D3|Hspell:248424|h[Gathering Power]|h|r from stacking too high.\n$bullet;Avoid triggering traps such as |cFF2959D3|Hspell:247641|h[Stasis Trap]|h|r and |cFF2959D3|Hspell:247962|h[Blastwire]|h|r when traversing the walkways!",difficultyIDs={17}},
			{id=17046,title="Damage Dealers",body="$bullet;Interrupt |cFF2959D3|Hspell:248321|h[Conflagration]|h|r when the raid has safely arrived on the correct platform to prevent |cFF2959D3|Hspell:248424|h[Gathering Power]|h|r from stacking too high.\n$bullet;Avoid triggering traps such as |cFF2959D3|Hspell:247641|h[Stasis Trap]|h|r and |cFF2959D3|Hspell:247962|h[Blastwire]|h|r when traversing the walkways!\n$bullet;Move away from players afflicted with |cFF2959D3|Hspell:247552|h[Sleep Canister]|h|r to avoid |cFF2959D3|Hspell:247565|h[Slumber Gas]|h|r.",difficultyIDs={14,15,16}},
			{id=16202,title="Healers",body="$bullet;Dispel |cFF2959D3|Hspell:247552|h[Sleep Canister]|h|r from affected players after allies move to a safe distance.\n$bullet;Avoid triggering traps such as |cFF2959D3|Hspell:247641|h[Stasis Trap]|h|r and |cFF2959D3|Hspell:247962|h[Blastwire]|h|r when traversing the walkways!"},
			{id=16203,title="Tanks",body="$bullet;Manage stacks of |cFF2959D3|Hspell:247367|h[Shock Lance]|h|r, |cFF2959D3|Hspell:247687|h[Sever]|h|r, and |cFF2959D3|Hspell:250255|h[Empowered Shock Lance]|h|r to ensure they don't stack too high.\n$bullet;Interrupt |cFF2959D3|Hspell:248321|h[Conflagration]|h|r when the raid has safely arrived on the correct platform to prevent |cFF2959D3|Hspell:248424|h[Gathering Power]|h|r from stacking too high.\n$bullet;Avoid triggering traps such as |cFF2959D3|Hspell:247641|h[Stasis Trap]|h|r and |cFF2959D3|Hspell:247962|h[Blastwire]|h|r when traversing the walkways!"},
