		sections={
			{id=16247,title="Overview",body="Mistress Alluradel periodically casts |cFF2959D3|Hspell:247551|h[Beguiling Charm]|h|r, charming all players who are facing her when the cast completes. Bringing a charmed player to 50% health breaks the effect, freeing them from Alluradel's control."},
			{id=16248,title="Damage Dealers",body="$bullet;Turn away from Mistress Alluradel when she casts |cFF2959D3|Hspell:247551|h[Beguiling Charm]|h|r.\n$bullet;Help free players affected by |cFF2959D3|Hspell:247551|h[Beguiling Charm]|h|r by brining them to 50% health."},
			{id=16249,title="Healers",body="$bullet;Turn away from Mistress Alluradel when she casts |cFF2959D3|Hspell:247551|h[Beguiling Charm]|h|r.\n$bullet;|cFF2959D3|Hspell:247604|h[Fel Lash]|h|r inflicts heavy damage to players caught in the cone."},
			{id=16250,title="Tanks",body="$bullet;Turn away from Mistress Alluradel when she casts |cFF2959D3|Hspell:247551|h[Beguiling Charm]|h|r.\n$bullet;Take turns tanking Mistress Alluradel to manage the application of |cFF2959D3|Hspell:247544|h[Sadist]|h|r."},
