	[2012]={
		encounterID=2012,
		instanceID=959,
		order=0,
		name="Inquisitor Meto",
		lore="Inquisitor Meto's mastery over fel magic is rivaled by few in the Legion. Meto uses this power to sow chaos and destruction across the cosmos, leaving countless burning worlds in his wake.",
		uiMapID=930,
		pin={x=0.8253,y=0.4639},
