		sections={
			{id=16263,title="Overview",body="Sotanathor uses his great weapon to |cFF2959D3|Hspell:247410|h[Cleave]|h|r his enemies in twain or to send forth |cFF2959D3|Hspell:247432|h[Wakes of Destruction]|h|r at random enemies. Sotanathor will periodically use his powerful voice to |cFF2959D3|Hspell:247698|h[Silence]|h|r all nearby enemies."},
			{id=16264,title="Damage Dealers",body="$bullet;Dodge |cFF2959D3|Hspell:247432|h[Wakes of Destruction]|h|r.\n$bullet;Stand with the tank to help mitigate |cFF2959D3|Hspell:247410|h[Soul Cleave]|h|r."},
			{id=16265,title="Healers",body="$bullet;Dodge |cFF2959D3|Hspell:247432|h[Wakes of Destruction]|h|r.\n$bullet;|cFF2959D3|Hspell:247410|h[Soul Cleave]|h|r will need to hit multiple players in order for the tank to survive.\n$bullet;|cFF2959D3|Hspell:247698|h[Silence]|h|r lasts for $247698d."},
			{id=16266,title="Tanks",body="$bullet;You will need other players in the raid to help you survive |cFF2959D3|Hspell:247410|h[Soul Cleave]|h|r.\n$bullet;|cFF2959D3|Hspell:247444|h[Cloven Soul]|h|r will increase the damage of |cFF2959D3|Hspell:247410|h[Soul Cleave]|h|r."},
