		sections={
			{id=16284,title="Overview",body="Pit Lord Vilemus will periodically use his |cFF2959D3|Hspell:247731|h[Fel Breath]|h|r and |cFF2959D3|Hspell:247733|h[Stomp]|h|r to damage the raid. Tanks will need to manage threat in order to survive his |cFF2959D3|Hspell:247739|h[Drain]|h|r ability."},
			{id=16285,title="Damage Dealers",body="$bullet;Spread out to avoid taking unnecessary damage from |cFF2959D3|Hspell:247731|h[Fel Breath]|h|r.\n$bullet;|cFF2959D3|Hspell:247733|h[Stomp]|h|r will interrupt any spells being cast and send you flying into the air."},
			{id=16286,title="Healers",body="$bullet;|cFF2959D3|Hspell:247731|h[Fel Breath]|h|r hits many players in a cone and leaves a damage over time effect on any victims.\n$bullet;|cFF2959D3|Hspell:247733|h[Stomp]|h|r will interrupt your spellcasting and then launch all players into the air, causing them to take falling damage in addition to the initial damage from the ability.\n$bullet;|cFF2959D3|Hspell:247739|h[Drain]|h|r will lower the victim's maximum health in addition to inflicting damage."},
			{id=16287,title="Tanks",body="$bullet;|cFF2959D3|Hspell:247739|h[Drain]|h|r will lower your maximum health in addition to inflicting damage."},
