	[2025]={
		encounterID=2025,
		instanceID=946,
		order=5,
		name="Eonar the Life-Binder",
		lore="Though she was felled by the blade of Sargeras, the Life-Binder's essence escaped the grasp of the Dark Titan. After millennia spent hiding in isolation, Eonar's sanctuary has been discovered by the Legion.\n\nShould her soul fall into the enemy's hands, Eonar's powers of nature and growth will be perverted to make the Burning Crusade unstoppable.",
		dungeonEncounterID=2075,
		uiMapID=913,
		pin={x=0.4011,y=0.5919},
		difficultyIDs={14,15,16,17},
