		sections={
			{id=16341,title="Overview",body="The forces of the Legion will warp in and charge at Eonar's Essence and attempt to destroy her outright.  Players must defend Eonar until she can gather her energies and strike back at her attackers."},
			{id=16342,title="Tanks",body="$bullet;Fel-Powered Purifiers will divert from their path to Eonar to engage players in combat once damaged.\n$bullet;Fel-Infused Destructors will fire at a much faster rate unless engaged in melee combat.\n$bullet;Move away from other players when targeted by |cFF2959D3|Hspell:248326|h[Rain of Fel]|h|r.",difficultyIDs={14,15,16}},
			{id=16522,title="Tanks",body="$bullet;Fel-Powered Purifiers will divert from their path to Eonar to engage players in combat once damaged.\n$bullet;Fel-Infused Destructors will fire at a much faster rate unless engaged in melee combat.\n$bullet;Avoid getting hit by |cFF2959D3|Hspell:248333|h[Meteor Storm]|h|r.",difficultyIDs={17}},
			{id=16343,title="Damage Dealers",body="$bullet;Most creatures are oblivious to your attempts to thwart their advance.\n$bullet;Many of your crowd-controlling effects will work here.\n$bullet;Move away from other players when targeted by |cFF2959D3|Hspell:248326|h[Rain of Fel]|h|r.\n$bullet;Kite |cFF2959D3|Hspell:248861|h[Spear of Doom]|h|r away from the normal walkways to mitigate its impact on the encounter.\n$bullet;Eonar will provide portals to board the Paraxis and interrupt its |cFF2959D3|Hspell:249121|h[Final Doom]|h|r attack.\n$bullet;When interrupting |cFF2959D3|Hspell:249121|h[Final Doom]|h|r coordinate which Feedback effect you will take.",difficultyIDs={16}},
			{id=16524,title="Damage Dealers",body="$bullet;Most creatures are oblivious to your attempts to thwart their advance.\n$bullet;Many of your crowd-controlling effects will work here.\n$bullet;Move away from other players when targeted by |cFF2959D3|Hspell:248326|h[Rain of Fel]|h|r.\n$bullet;Kite |cFF2959D3|Hspell:248861|h[Spear of Doom]|h|r away from the normal walkways to mitigate its impact on the encounter.",difficultyIDs={15}},
			{id=16525,title="Damage Dealers",body="$bullet;Most creatures are oblivious to your attempts to thwart their advance.\n$bullet;Many of your crowd-controlling effects will work here.\n$bullet;Move away from other players when targeted by |cFF2959D3|Hspell:248326|h[Rain of Fel]|h|r.",difficultyIDs={14}},
			{id=16523,title="Damage Dealers",body="$bullet;Most creatures are oblivious to your attempts to thwart their advance.\n$bullet;Many of your crowd-controlling effects will work here.\n$bullet;Move away from other players when targeted by |cFF2959D3|Hspell:248326|h[Rain of Fel]|h|r.\n$bullet;Avoid getting hit by |cFF2959D3|Hspell:248333|h[Meteor Storm]|h|r.",difficultyIDs={17}},
			{id=16526,title="Healers",body="$bullet;Most creatures will not turn to engage players. Instead, the Paraxis will fire off many spells that will damage the raid.\n$bullet;Move away from other players when targeted by |cFF2959D3|Hspell:248326|h[Rain of Fel]|h|r.\n$bullet;Kite |cFF2959D3|Hspell:248861|h[Spear of Doom]|h|r away from the normal walkways to mitigate its impact on the encounter.\n$bullet;Eonar will provide portals to board the Paraxis and interrupt its |cFF2959D3|Hspell:249121|h[Final Doom]|h|r attack.\n$bullet;When interrupting |cFF2959D3|Hspell:249121|h[Final Doom]|h|r coordinate which Feedback effect you will take.",difficultyIDs={16}},
			{id=16527,title="Healers",body="$bullet;Most creatures will not turn to engage players. Instead, the Paraxis will fire off many spells that will damage the raid.\n$bullet;Move away from other players when targeted by |cFF2959D3|Hspell:248326|h[Rain of Fel]|h|r.\n$bullet;Kite |cFF2959D3|Hspell:248861|h[Spear of Doom]|h|r away from the normal walkways to mitigate its impact on the encounter.",difficultyIDs={15}},
			{id=16528,title="Healers",body="$bullet;Most creatures will not turn to engage players. Instead, the Paraxis will fire off many spells that will damage the raid.\n$bullet;Move away from other players when targeted by |cFF2959D3|Hspell:248326|h[Rain of Fel]|h|r.",difficultyIDs={14}},
			{id=16344,title="Healers",body="$bullet;Most creatures will not turn to engage players. Instead, the Paraxis will fire off many spells that will damage the raid.\n$bullet;Avoid getting hit by |cFF2959D3|Hspell:248333|h[Meteor Storm]|h|r.",difficultyIDs={17}},
			{id=17031,title="Section 39"},
			{id=17032,title="Section 40",body="$[!16 In Mythic difficulty, players can only have one charge of Surge of Life at a time.$]"},
			{id=17180,title="Section 47"},
			{id=17280,title="Dive Down",body="While gliding, use this ability to dive down to the targeted location."},
			{id=17040,title="Section 46"},
			{id=16521,title="Section 23",body="$[!16 In Mythic difficulty, each cast of Life Force reenergizes players with Essence of the Lifebinder.$]"},
			{id=17181,title="Section 48"},
			{id=16560,title="Section 33",body="$[!16 \nFel Shielding can only be removed by the explosion of a |cFF2959D3|Hspell:248326|h[Rain of Fel]|h|r.$]"},
			{id=16345,title="The Paraxis",body="The Paraxis spearheads the Legion's invasion against Eonar, launching several different attacks at players to cover the insertion of Legion forces."},
			{id=16346,title="Section 6"},
			{id=16529,title="Meteor Storm",difficultyIDs={17}},
			{id=16349,title="Section 9",difficultyIDs={15,16}},
			{id=16446,title="Section 8"},
			{id=16447,title="Section 9",difficultyIDs={14,15,16}},
			{id=16555,title="Final Doom",body="Periodically throughout the encounter, the Paraxis will attempt to annihilate all life in the zone.  Players must enter the Paraxis by using special portals that Eonar creates on her platform.  While there, players must dispatch a Paraxis Inquisitor and then deactivate four Focusing Crystals in order to disrupt the sequence.  Deactivating a crystal gives the player a Feedback application based on the color of the Focusing Crystal.",difficultyIDs={16}},
			{id=16448,title="Section 10",difficultyIDs={16}},
			{id=16452,title="Section 14",difficultyIDs={16}},
			{id=16451,title="Section 13",difficultyIDs={16}},
			{id=16450,title="Section 12",difficultyIDs={16}},
			{id=16449,title="Section 11",difficultyIDs={16}},
			{id=16564,title="Paraxis Inquisitor",body="The Paraxis Inquisitor controls access to the various control devices aboard the Paraxis. Defeat him to be able to interact with the devices and interrupt the Paraxis' Final Doom attack.",difficultyIDs={16}},
			{id=16565,title="Section 35",difficultyIDs={16}},
			{id=16566,title="Section 36",difficultyIDs={16}},
			{id=16567,title="Section 37",difficultyIDs={16}},
			{id=16568,title="Section 38",body="$[!16 \nThis ability is only used when the caster is not actively engaged in melee combat.$]",difficultyIDs={16}},
			{id=17035,title="Forces of the Legion",body="These creatures warp in at various locations and move directly to Eonar's essence. If they reach her essence they will inflict damage to her until they are defeated."},
			{id=17036,title="Felguard",body="Standard Legion infantry unit. Not exceptionally fast or hearty."},
			{id=17037,title="Fel Hound",body="Exceptionall fast, these hounds of the Legion have less health than Felguards."},
			{id=17038,title="Fel Lord",body="Slow-moving, these elite Legion units have exceptionally high health."},
			{id=17039,title="Volant Kerapteron",body="These fel bats fly in and take an airborne route to Eonar's essence.",difficultyIDs={14,15,16}},
			{id=16500,title="Fel-Powered Purifier",body="Removes any active crowd-control effects from nearby allies and grants all nearby allies immunity to crowd-controlling effects.",difficultyIDs={15,16}},
			{id=16507,title="Section 21"},
			{id=16504,title="Section 18"},
			{id=16501,title="Fel-Infused Destructor",body="Continually fires upon Eonar's essence until dispatched. If not actively engaged in melee combat will greatly increase rate of fire.\nThis creature is sessile."},
			{id=16505,title="Section 19"},
			{id=16506,title="Section 20"},
			{id=16502,title="Fel-Charged Obfuscator",body="Cloaks nearby allies, making them invisible.  This creature ignores combat.",difficultyIDs={14,15,16}},
			{id=16508,title="Section 22"},
		},
	},
	[2031]={
		encounterID=2031,
		instanceID=946,
		order=11,
		name="Argus the Unmaker",
		lore="Bound. Broken.\nEons of existence, knowing only pain.\nA shattered soul, fueling infinite evil.\nThe master beckons. Rise... Rise!\nBegin the end of all things.",
		dungeonEncounterID=2092,
		uiMapID=918,
		pin={x=0.5011,y=0.5306},
		difficultyIDs={14,15,16,17},
		npcIDs={124828},
		displayIDs={78709},
		loot={
			{itemID=152283,diffs={},faction=-1},
			{itemID=151986,diffs={},faction=-1},
			{itemID=152005,diffs={},faction=-1},
